// 產生檔：node tools/build_course_v2.js（來源 tools/content/course_v2/）。不要手改。
window.BUZZ_COURSE_V2_LESSONS = Object.assign(window.BUZZ_COURSE_V2_LESSONS || {}, {"taylor-limits-higher":{"id":"taylor-limits-higher","prerequisites":["taylor-limits","maclaurin-series","taylor-error"],"next":["asymptotic-equivalence"],"related":["big-o-little-o","lhopital"],"objectives":["看分母（或分子第一個不會消掉的項）決定每個函數要展到第幾階。","會做合成與相除的展開：e^{sin x}、ln(cos x)、tan x = sin x/cos x。","x → ∞ 的題先令 t = 1/x 換成 t → 0⁺；1^∞ 型先取對數再展開。"],"concept":[{"heading":"① 這一課多了什麼","body":["〈用 Taylor 求極限〉處理的是一個函數展開、減掉前幾項的題。真正難的題有三種變化：函數套函數（e^{sin x}）、相乘相除（tan x、1/sin² x）、變數跑到 ∞。這三種都還是同一個想法：把每一塊寫成多項式加上「更小的東西」，消掉之後看第一個留下來的項。","記號：o(xⁿ) 代表「除以 xⁿ 之後 → 0 的東西」，例如 x⁵ = o(x⁴)。它的運算規則在〈Big-O 與 little-o〉會正式整理，這一課先當成「後面還有項，但不影響答案」的記號。"]},{"heading":"② 展到第幾階：算總次數","body":["分母是 x⁴，分子就要算到 x⁴ 那一項為止。每一塊要展到多少，看它乘上別的因子之後會不會落在 x⁴ 以內。例如 sin² x 要到 x⁴，因為 sin x 從 x 開始，sin x 只要展到 x³：(x − x³/6)² = x² − x⁴/3 + …，x³ 那項乘上 x 剛好到 x⁴。","展少了：留下來的全被 o(…) 吃掉，看起來像 0/0，什麼都看不到。展多了：不會錯，只是白算。"]},{"heading":"③ 合成：把內層展開代進外層","body":["e^{sin x}：先寫 u = sin x = x − x³/6 + …，u 從 x 開始，所以 uᵏ 從 xᵏ 開始。要到 x⁴，外層 eᵘ = 1 + u + u²/2 + u³/6 + u⁴/24 就夠，再把 u、u²、u³、u⁴ 各自展到 x⁴，合併同次項。","前提是內層 → 0（這裡 sin x → 0），外層才能用在 0 附近的展開。ln(cos x) 也一樣：cos x − 1 = −x²/2 + … → 0，套 ln(1 + u) = u − u²/2 + …。"]},{"heading":"④ 相除：1/(1 − w) 是幾何級數","body":["分母展開後長成 1 − w（w → 0）時，用 1/(1 − w) = 1 + w + w² + …。例如 1/cos x = 1/(1 − x²/2 + x⁴/24 − …) = 1 + x²/2 + 5x⁴/24 + …，再乘上 sin x 就得到 tan x = x + x³/3 + 2x⁵/15 + …。"]},{"heading":"⑤ x → ∞ 與 1^∞","body":["x → ∞：令 t = 1/x，t → 0⁺，就回到 0 附近的展開。1^∞（例如 (cos x)^{1/x²}）：寫成 exp( ln(cos x)/x² )，只展開指數裡的部分；指數的極限是 L，原極限就是 e^L（exp 連續）。"]},{"heading":"為什麼可以這樣代：Peano 餘項","body":["若 f 在 0 有 n 階導數，Taylor 定理給 f(x) = Σ_{k≤n} f⁽ᵏ⁾(0)xᵏ/k! + o(xⁿ)（Peano 形式的餘項）。合成時，若 u(x) → 0 而且 |u(x)| ≤ C|x|（u 至少一階小），則 o(uⁿ) = o(xⁿ)：除以 xⁿ 寫成 (o(uⁿ)/uⁿ)·(u/x)ⁿ，前者 → 0、後者有界。這就是「內層代進外層、截到同一階」合法的原因。"],"collapsible":true}],"workedExamples":[{"title":"合成：e^{sin x} 要到 x⁴","prompt":"lim_{x→0} (e^{sin x} − 1 − x − x²/2)/x⁴","problemId":"burst-boss-lim-004","steps":["分母 x⁴，所以 e^{sin x} 要展到 x⁴。令 u = sin x = x − x³/6 + o(x⁴)（sin x 沒有 x⁴ 項，下一項是 x⁵）。","各次方展到 x⁴：u² = x² − x⁴/3 + o(x⁴)，u³ = x³ + o(x⁴)，u⁴ = x⁴ + o(x⁴)。","代進 eᵘ = 1 + u + u²/2 + u³/6 + u⁴/24 + o(u⁴)：1 + (x − x³/6) + (x²/2 − x⁴/6) + x³/6 + x⁴/24 + o(x⁴)。","合併：x³ 項 −1/6 + 1/6 = 0；x⁴ 項 −1/6 + 1/24 = −1/8。所以 e^{sin x} = 1 + x + x²/2 − x⁴/8 + o(x⁴)。","分子 = −x⁴/8 + o(x⁴)，除以 x⁴ → −1/8。"],"answer":"−1/8"},{"title":"相減再通分：1/x² − 1/sin² x","prompt":"lim_{x→0} (1/x² − 1/sin² x)","problemId":"fd-limx-607","steps":["∞ − ∞，先通分：(sin² x − x²)/(x² sin² x)。","分母：sin² x = x² + o(x²)，所以分母 = x⁴ + o(x⁴)，是 x⁴ 階。分子也要算到 x⁴。","sin x = x − x³/6 + o(x³)，平方：sin² x = x² − x⁴/3 + o(x⁴)（交叉項 2 · x · (−x³/6) = −x⁴/3）。","分子 = −x⁴/3 + o(x⁴)，比值 → −1/3。"],"answer":"−1/3"},{"title":"x → ∞：先換成 t = 1/x","prompt":"lim_{x→∞} x² ( ln(1 + 1/x) − 1/(x + 1) )","problemId":"depth-lim-006","steps":["令 t = 1/x，t → 0⁺。x² = 1/t²，1/(x + 1) = t/(1 + t)。","前面有 1/t²，括號裡要展到 t²（多寫一項 t³ 方便看）：ln(1 + t) = t − t²/2 + t³/3 + o(t³)；t/(1 + t) = t(1 − t + t² + o(t²)) = t − t² + t³ + o(t³)。","相減：(−1/2 + 1)t² + (1/3 − 1)t³ + o(t³) = t²/2 − (2/3)t³ + o(t³)。","乘上 1/t²：1/2 − (2/3)t + o(t) → 1/2。"],"answer":"1/2"}],"pitfalls":["內層沒有 → 0 就套外層的 0 附近展開，例如把 e^{1 + x} 當成 1 + (1 + x) + …。","合成時 u² 只寫 x²，漏了交叉項（sin² x 的 −x⁴/3）。","分母只看「寫出來的」x²，沒發現 sin² x 讓分母其實是 x⁴ 階。","1^∞ 直接答 1；要先取對數，指數的極限才是答案的關鍵。"],"checks":[{"ask":"求 lim_{x→0} (sin² x − x²)/x⁴ 時，sin x 至少要展到哪一項？","options":[{"label":"到 x³ 項","correct":true},{"label":"只要 x 一項","why":"sin² x 會變成 x²，跟 −x² 消光，分子剩 o(x²)，除以 x⁴ 什麼都看不出來。"},{"label":"到 x² 項就夠，因為平方之後是 x⁴","why":"sin x 沒有 x² 項，截到 x² 等於只留 x；x⁴ 的係數來自 x · (−x³/6) 的交叉項。"}]},{"ask":"lim_{x→0} (tan x − sin x)/x³ 是？","options":[{"label":"1/2","correct":true},{"label":"0","why":"只展到一階，tan x 和 sin x 都是 x，看起來抵銷了；三階是 x³/3 − (−x³/6) = x³/2。"},{"label":"1/6","why":"漏了 tan x 的 x³/3，只剩 sin x 那邊的 x³/6。"}]},{"ask":"ln(cos x) 展開的第一個非零項是？","options":[{"label":"−x²/2","correct":true},{"label":"1 − x²/2","why":"那是 cos x 本身。ln(1 + u) 的 u = cos x − 1 = −x²/2 + …，ln 之後第一項就是 u。"},{"label":"x²/2","why":"符號反了：cos x < 1，ln(cos x) < 0。"}]},{"ask":"lim_{x→0} (cos x)^{1/x²} 是？","options":[{"label":"e^{−1/2}","correct":true},{"label":"1","why":"1^∞ 是不定型。取對數得 ln(cos x)/x² → −1/2，答案是 e^{−1/2}。"},{"label":"e^{1/2}","why":"ln(cos x) ≈ −x²/2 是負的，指數的極限是 −1/2。"}]}],"practice":[{"id":"lim-021","core":true},{"id":"depth-lim-011","core":true},{"id":"depth-lim-003","core":true},{"id":"fd-limx-607","core":true},{"id":"depth-lim-006","core":true},{"id":"world-030","core":true},{"id":"burst-boss-lim-004"},{"id":"burst-boss-lim-005"},{"id":"fd-limx-603"},{"id":"lx-hard-002"},{"id":"world-099","challenge":true,"note":"挑戰：tan(sin x) 與 sin(tan x) 前五階完全相同，要展到 x⁷。"}]},"asymptotic-equivalence":{"id":"asymptotic-equivalence","prerequisites":["taylor-limits-higher","limit-trig-standard","limit-exp-log-standard","limit-at-infinity"],"next":["big-o-little-o"],"related":["taylor-limits","limit-comparison-test","improper-comparison"],"objectives":["說得出 f ~ g 的定義：f/g → 1，並背熟 x → 0 時的一組等價式。","在乘積與商裡用等價式替換，而且知道為什麼可以。","看出在相加、相減、指數裡替換為什麼會出錯，並會把差改寫成積再替換。"],"concept":[{"heading":"① 兩個函數「長得一樣快」","body":["x → 0 時 sin x 與 x 都 → 0，而且 sin x/x → 1：越靠近 0，兩者的差相對於它們本身越來越小。這種關係叫漸近等價，記作 sin x ~ x（x → 0）。","一般定義：x → a 時，若 f(x)/g(x) → 1，就寫 f ~ g。a 可以是一個數，也可以是 ±∞；一定要說清楚 x 往哪裡跑。"]},{"heading":"② 一組要背的等價式（x → 0）","body":["sin x ~ x、tan x ~ x、arcsin x ~ x、arctan x ~ x、eˣ − 1 ~ x、ln(1 + x) ~ x、1 − cos x ~ x²/2、(1 + x)ᵃ − 1 ~ ax（a ≠ 0）。","它們都是〈用 Taylor 求極限〉裡展開式的第一個非零項。x 可以換成任何 → 0 的東西 u(x)：例如 x → 0 時 sin 3x ~ 3x，ln(cos x) = ln(1 + (cos x − 1)) ~ cos x − 1 ~ −x²/2。"]},{"heading":"③ 乘積與商可以替換","body":["若 f ~ f₁、g ~ g₁，則 f·g ~ f₁·g₁、f/g ~ f₁/g₁。理由一行：f/g = (f/f₁)·(f₁/g₁)·(g₁/g)，頭尾兩個比值都 → 1，所以 f/g 與 f₁/g₁ 有相同的極限（一邊存在，另一邊就存在）。","所以 lim_{x→0} sin 3x · ln(1 + 2x)/(x(eˣ − 1)) 可以直接換成 3x · 2x/(x · x) = 6。"]},{"heading":"④ 相減不能替換","body":["tan x − sin x：把兩個都換成 x 得到 0，但真正的 tan x − sin x 不是 0，它 ~ x³/2。等價只保證「比值 → 1」，前兩項一樣、後面的項不一樣；相減時前面的項抵銷，剩下的正是被替換丟掉的部分。","補救：把差改寫成積。tan x − sin x = tan x · (1 − cos x) ~ x · x²/2 = x³/2，這樣就又能替換了。真的寫不成積，就回到 Taylor 展開。"]},{"heading":"⑤ 指數裡也不能替換","body":["x → ∞ 時 x + 1 ~ x，但 e^{x+1}/eˣ = e，不 → 1。等價只控制比值，不控制差；指數裡的差 1 會被 e 放大成倍數。對數反而比較安全：若 f ~ g 且 g → 0⁺ 或 g → ∞，則 ln f ~ ln g，因為 ln f − ln g = ln(f/g) → 0，而 ln g 本身 → ±∞。"],"collapsible":true}],"workedExamples":[{"title":"乘積與商：直接替換","prompt":"lim_{x→0} sin 3x · ln(1 + 2x) / ( x(eˣ − 1) )","steps":["每一個因子都 → 0，而且都是乘除關係，可以換。","sin 3x ~ 3x，ln(1 + 2x) ~ 2x，eˣ − 1 ~ x。","式子 ~ (3x)(2x)/(x · x) = 6。"],"answer":"6"},{"title":"相減：先改寫成積","prompt":"lim_{x→0} (tan x − sin x)/x³","problemId":"lim-013","steps":["分子是差，不能把 tan x、sin x 都換成 x（那樣會得到 0，是錯的）。","提出 tan x：tan x − sin x = tan x − tan x · cos x = tan x (1 − cos x)。","現在是積：tan x ~ x，1 − cos x ~ x²/2，所以分子 ~ x³/2。","除以 x³ → 1/2。"],"answer":"1/2"},{"title":"x → ∞ 的等價","prompt":"lim_{x→∞} √(x² + 1) · ln(1 + 3/x)","steps":["x → ∞ 時只看 x > 0。√(x² + 1) = x√(1 + 1/x²)（x > 0 時 √(x²) = x），而 √(1 + 1/x²) → 1，所以 √(x² + 1) ~ x。","u = 3/x → 0，所以 ln(1 + 3/x) ~ 3/x。","乘積 ~ x · (3/x) = 3。"],"answer":"3"}],"pitfalls":["在相加或相減裡替換，前面的項抵銷後得到錯的 0。","忘了寫 x 往哪裡跑：sin x ~ x 只在 x → 0 成立，x → ∞ 時完全不對。","把等價用在指數裡：x + 1 ~ x 不代表 e^{x+1} ~ eˣ。","替換時漏掉係數：sin 3x ~ 3x，不是 ~ x。"],"checks":[{"ask":"x → 0 時，1 − cos x 等價於？","options":[{"label":"x²/2","correct":true},{"label":"x","why":"(1 − cos x)/x → 0，不是 → 1。1 − cos x 是二階小量。"},{"label":"x²","why":"(1 − cos x)/x² → 1/2，不是 1；要寫 x²/2 比值才 → 1。"}]},{"ask":"下面哪一個替換是對的？","options":[{"label":"lim_{x→0} sin x · (eˣ − 1)/x²：換成 x · x/x²，得 1","correct":true},{"label":"lim_{x→0} (sin x − x)/x³：把 sin x 換成 x，得 0","why":"這是相減。前面的 x 抵銷之後，剩下的正是被丟掉的 −x³/6，答案是 −1/6。"},{"label":"x → ∞ 時 x + 1 ~ x，所以 lim e^{x+1}/eˣ = 1","why":"等價不能放進指數。e^{x+1}/eˣ = e。"}]},{"ask":"lim_{x→0} ln(1 + 5x)/arcsin 2x 是？","options":[{"label":"5/2","correct":true},{"label":"1","why":"兩個都「像 x」，但係數要留著：ln(1 + 5x) ~ 5x，arcsin 2x ~ 2x。"},{"label":"10","why":"這是商，不是積：5x/(2x) = 5/2。"}]},{"ask":"x → 0 時 ln(cos x) 等價於？","options":[{"label":"−x²/2","correct":true},{"label":"cos x","why":"cos x → 1，ln(cos x) → 0，兩者比值不 → 1。要用 ln(1 + u) ~ u，u = cos x − 1。"},{"label":"x²/2","why":"cos x < 1 時 ln(cos x) < 0，符號是負的。"}]}],"practice":[{"id":"tb-lh-001","core":true},{"id":"tb-lh-002","core":true},{"id":"lim-030","core":true},{"id":"exam-lim-015","core":true},{"id":"lim-013","core":true},{"id":"depth-lim-010","core":true},{"id":"rel-boss-019","core":true},{"id":"lx-hard-008"},{"id":"fd-limx-608"},{"id":"lm-nr-003"},{"id":"fd-limx-606","challenge":true,"note":"挑戰：提出 eˣ，e^{tan x} − eˣ = eˣ(e^{tan x − x} − 1)，再用 eᵘ − 1 ~ u。"}]},"big-o-little-o":{"id":"big-o-little-o","prerequisites":["asymptotic-equivalence","taylor-limits-higher","taylor-error"],"next":["stirling"],"related":[],"objectives":["分清楚 f = o(g)（比值 → 0）與 f = O(g)（被 g 的常數倍控制），而且每次都說明 x 往哪裡跑。","會用 o、O 的運算規則做展開的記帳：相加取低階、相乘次數相加、o − o 不是 0。","會用「主項 + 誤差項」的寫法算出 n((1 + 1/n)ⁿ − e) 這類極限。"],"concept":[{"heading":"① 為什麼需要記號：替「剩下的部分」記帳","body":["Taylor 展開寫「sin x = x − x³/6 + …」時，那個「…」到底多小？相乘、相除、代進別的函數之後，它會不會長大到影響答案？o 與 O 就是用來精確回答這個問題的記號。"]},{"heading":"② 定義（x → a，a 可以是數或 ±∞）","body":["f = o(g)：f/g → 0。讀作「f 比 g 小得多」。","f = O(g)：存在常數 C，使得在 a 附近 |f| ≤ C|g|。讀作「f 最多跟 g 一樣大（差一個常數倍）」。","跟上一課接起來：f ~ g 等於 f = g + o(g)。","方向一定要寫：x → 0 時 x³ = o(x²)（次方越高越小）；x → ∞ 時反過來，x² = o(x³)。"]},{"heading":"③ 等號只能從左讀到右","body":["o(x²) 代表「某一個除以 x² 會 → 0 的函數」，是一整類函數，不是一個數。所以 x³ = o(x²) 對，倒過來寫 o(x²) = x³ 沒有意義。兩個 o(x²) 也不一定是同一個函數：o(x²) − o(x²) 還是 o(x²)，不是 0。"]},{"heading":"④ 運算規則（x → 0，m、n ≥ 0）","body":["相加取低階：o(xᵐ) + o(xⁿ) = o(x^{min(m,n)})。常數倍不變：c · o(xⁿ) = o(xⁿ)。","相乘次數相加：xᵐ · o(xⁿ) = o(x^{m+n})，o(xᵐ) · o(xⁿ) = o(x^{m+n})。相除次數相減：o(xⁿ)/xᵐ = o(x^{n−m})。","O 的規則一模一樣。一個實用的對照：o(xⁿ) 是「比 xⁿ 小」，O(x^{n+1}) 是「最多跟 x^{n+1} 一樣大」，後者是更精確的資訊。"]},{"heading":"⑤ x → ∞ 的成長階梯","body":["對任何 p > 0、a > 0、b > 1：(ln x)ᵖ = o(xᵃ)，xᵃ = o(bˣ)。也就是 對數 ≪ 冪次 ≪ 指數。這張表在比較判別、瑕積分、Stirling 公式裡會一直用到。"]},{"heading":"Peano 餘項與 Lagrange 餘項給的是哪一種","body":["f 在 0 有 n 階導數：f(x) = Tₙ(x) + o(xⁿ)（Peano）。若 f⁽ⁿ⁺¹⁾ 在 0 附近有界，由 Lagrange 餘項 f⁽ⁿ⁺¹⁾(c)x^{n+1}/(n + 1)! 得到更強的 f(x) = Tₙ(x) + O(x^{n+1})。〈Taylor 誤差〉裡的誤差上界，就是把 O 裡的常數 C 具體算出來。"],"collapsible":true}],"workedExamples":[{"title":"相乘時的記帳","prompt":"把 eˣ sin x 展開到 x³，並求 lim_{x→0} (eˣ sin x − x − x²)/x³","steps":["sin x 從 x 開始，所以 eˣ 只要展到 x²：eˣ = 1 + x + x²/2 + o(x²)；sin x = x − x³/6 + o(x³)。","相乘並逐項記帳：1 · (x − x³/6) + x · x + (x²/2) · x = x + x² + x³/2 − x³/6。","誤差項：o(x²) · x = o(x³)；1 · o(x³) = o(x³)；x · (−x³/6) 是 x⁴，屬於 o(x³)。全部合起來是 o(x³)。","所以 eˣ sin x = x + x² + x³/3 + o(x³)，所求極限是 1/3。"],"answer":"eˣ sin x = x + x² + x³/3 + o(x³)；極限 1/3"},{"title":"x → ∞：主項與下一項","prompt":"x → ∞ 時，f(x) = (x³ + ln x)/(2x + √x)。找主項，並說明誤差多大。","steps":["提出最大的：f = (x²/2) · (1 + (ln x)/x³)/(1 + 1/(2√x))。","w = 1/(2√x) → 0，1/(1 + w) = 1 − w + O(w²) = 1 − 1/(2√x) + O(1/x)。又 (ln x)/x³ = o(1/x)（成長階梯）。","相乘：f = (x²/2)(1 − 1/(2√x) + O(1/x)) = x²/2 − x^{3/2}/4 + O(x)。","所以 f ~ x²/2，而且 f − x²/2 ~ −x^{3/2}/4。"],"answer":"f = x²/2 − x^{3/2}/4 + O(x)"},{"title":"經典：(1 + 1/n)ⁿ 離 e 多遠","prompt":"lim_{n→∞} n( (1 + 1/n)ⁿ − e )","problemId":"world-091","steps":["寫成指數：(1 + 1/n)ⁿ = exp( n ln(1 + 1/n) )。","t = 1/n → 0，ln(1 + t) = t − t²/2 + O(t³)，所以 n ln(1 + 1/n) = 1 − 1/(2n) + O(1/n²)。","exp(1 + h) = e · eʰ，h = −1/(2n) + O(1/n²) → 0，eʰ = 1 + h + O(h²) = 1 − 1/(2n) + O(1/n²)。","所以 (1 + 1/n)ⁿ − e = −e/(2n) + O(1/n²)，乘上 n → −e/2。"],"answer":"−e/2"}],"pitfalls":["沒寫 x 往哪裡跑：x² = o(x) 在 x → 0 對、在 x → ∞ 錯。","把 o(x²) − o(x²) 寫成 0。","相乘時次數相乘：x³ · o(x²) 是 o(x⁵)，不是 o(x⁶)。","把 o(…) 寫到等號左邊再倒推，例如由 o(x) = x² 推出別的結論。"],"checks":[{"ask":"x → 0 時，下面哪一個成立？","options":[{"label":"x³ = o(x²)","correct":true},{"label":"x² = o(x³)","why":"x²/x³ = 1/x → ∞。在 0 附近次方越高越小，方向反了。"},{"label":"x = o(x)","why":"x/x = 1，不 → 0。o 是「小得多」，不是「一樣大」。"}]},{"ask":"x → 0 時，o(x²) − o(x²) 等於？","options":[{"label":"o(x²)","correct":true},{"label":"0","why":"兩個 o(x²) 代表兩個不一定相同的函數，只知道各自比 x² 小得多，相減不會剛好抵銷。"},{"label":"o(x⁴)","why":"相減不會讓階數變高；只能保證結果仍然比 x² 小得多。"}]},{"ask":"x → 0 時，x³ · o(x²) 等於？","options":[{"label":"o(x⁵)","correct":true},{"label":"o(x⁶)","why":"次數是相加，不是相乘：x³ · x² = x⁵。"},{"label":"沒辦法化簡，只能保留 x³ · o(x²)","why":"可以化簡：x³ · o(x²) 除以 x⁵ 等於 o(x²)/x² → 0。"}]},{"ask":"x → ∞ 時，下面哪一個成立？","options":[{"label":"(ln x)¹⁰ = o(√x)","correct":true},{"label":"eˣ = O(x¹⁰⁰)","why":"指數成長比任何冪次快，eˣ/x¹⁰⁰ → ∞，找不到常數 C 壓住。"},{"label":"√x = o(ln x)","why":"方向反了：對數比任何正冪次都慢，是 ln x = o(√x)。"}]}],"practice":[{"id":"mob-limtrap-005","core":true},{"id":"exam-lim-003","core":true},{"id":"exam-lim-007","core":true},{"id":"cx-hl-002","core":true},{"id":"world-091","core":true},{"id":"lm-nr-005"},{"id":"dm-seq-010"},{"id":"depth-lim-012"},{"id":"dm-seq-005","challenge":true,"note":"挑戰：√(n² + n) = n + 1/2 − 1/(8n) + O(1/n²)，再用 sin 的週期。"},{"id":"rel-hard-lim-010","challenge":true,"note":"挑戰：比範例 3 多展一項，誤差要算到 O(1/n³)。"}]},"stirling":{"id":"stirling","prerequisites":["big-o-little-o","asymptotic-equivalence","ibp-log-invtrig","riemann-sum-intuition"],"next":["stolz-cesaro"],"related":["wallis-product","euler-maclaurin-intro"],"objectives":["寫得出 n! ~ √(2πn)(n/e)ⁿ，並說清楚「~」保證的是比值 → 1，不是差 → 0。","用 ln n! = Σ ln k 與 ∫ ln x dx 的比較，說出 (n/e)ⁿ 從哪裡來。","用 Stirling 算含階乘的極限：(n!)^{1/n}/n、中央二項式係數 C(2n, n)。"],"concept":[{"heading":"① 公式與它的意思","body":["n → ∞ 時 n! ~ √(2πn)(n/e)ⁿ，也就是兩者的比值 → 1。","n = 10：10! = 3,628,800，右邊約 3,598,696，比值約 1.0084，相對誤差不到 1%。但差約 30,104，而且 n 越大差越大（n = 20 時差約 10¹⁶）。Stirling 是相對誤差小，不是絕對誤差小，所以只能用在乘、除、開 n 次方這類看比值的地方。"],"tex":["n!\\sim\\sqrt{2\\pi n}\\left(\\frac{n}{e}\\right)^{n}"]},{"heading":"② (n/e)ⁿ 從哪裡來（直覺，不是證明）","body":["取對數，乘積變成和：ln n! = ln 1 + ln 2 + … + ln n。這是 y = ln x 在 x = 1, 2, …, n 的高度相加，很像 ∫₁ⁿ ln x dx = n ln n − n + 1。","所以 ln n! ≈ n ln n − n，取指數得 n! ≈ (n/e)ⁿ 這個量級。再用梯形法修正（端點各算一半）會多出 (1/2) ln n，也就是 √n 這個因子。","這只是直覺：它說明了 nⁿ、e^{−n}、√n 三個因子，但沒有算出常數 √(2π)，也沒有證明誤差真的趨近 0。"]},{"heading":"③ 怎麼用：先把階乘換掉，再化簡","body":["因為 ~ 可以在乘積與商裡替換（〈漸近等價〉），含階乘的比值可以把每個 n! 換成 √(2πn)(n/e)ⁿ，然後把 e 的次方、n 的次方各自合併。開 n 次方也可以：若 aₙ ~ bₙ，則 (aₙ/bₙ)^{1/n} → 1。","最常用的兩個結果：(n!)^{1/n} ~ n/e，以及 C(2n, n) ~ 4ⁿ/√(πn)。"]},{"heading":"證明的骨架：常數是怎麼定出來的","body":["令 dₙ = ln n! − (n + 1/2) ln n + n。用梯形法估 ∫ₖ^{k+1} ln x dx 的誤差，可以證明 dₙ − dₙ₊₁ = O(1/n²)，而 Σ 1/n² 收斂，所以 dₙ 收斂到某個常數 C，也就是 n! ~ e^C √n (n/e)ⁿ。","常數 e^C = √(2π) 要另外決定：把這個式子代進〈Wallis 乘積〉π/2 = lim 的那個比值，就解出 e^C。更精細的展開 n! = √(2πn)(n/e)ⁿ(1 + 1/(12n) + O(1/n²)) 來自〈Euler–Maclaurin 入門〉。"],"collapsible":true}],"workedExamples":[{"title":"相對誤差 vs. 絕對誤差","prompt":"比較 10! 與 √(20π)(10/e)¹⁰。","steps":["10! = 3,628,800。","√(20π) ≈ 7.927，(10/e)¹⁰ ≈ 453,999.3，相乘約 3,598,695.6。","比值 3,628,800/3,598,695.6 ≈ 1.0084；差 ≈ 30,104。","比值已經很接近 1（實際上 ≈ 1 + 1/(12 · 10)），但差一點都不小。"],"answer":"比值約 1.0084，差約 30,104"},{"title":"開 n 次方","prompt":"lim_{n→∞} (n!)^{1/n}/n","problemId":"cx-hl-004","steps":["n! ~ √(2πn)(n/e)ⁿ，開 n 次方：(n!)^{1/n} 與 (2πn)^{1/(2n)} · (n/e) 的比值 → 1。","(2πn)^{1/(2n)} = exp( ln(2πn)/(2n) )，而 ln(2πn)/(2n) → 0（對數 ≪ 冪次），所以這個因子 → 1。","剩下 (n/e)/n = 1/e。"],"answer":"1/e"},{"title":"中央二項式係數","prompt":"證明 C(2n, n) ~ 4ⁿ/√(πn)，並求 lim √n · C(2n, n)/4ⁿ。","problemId":"dm-seq-004","steps":["C(2n, n) = (2n)!/(n!)²。分子換成 √(4πn)(2n/e)^{2n}，分母換成 (√(2πn)(n/e)ⁿ)² = 2πn (n/e)^{2n}。","根號部分：√(4πn)/(2πn) = 1/√(πn)。","次方部分：(2n/e)^{2n}/(n/e)^{2n} = 2^{2n} = 4ⁿ。","所以 C(2n, n) ~ 4ⁿ/√(πn)，√n · C(2n, n)/4ⁿ → 1/√π。"],"answer":"1/√π"}],"pitfalls":["把 Stirling 用在差上，例如以為 n! − √(2πn)(n/e)ⁿ → 0。","漏掉 √(2πn) 只寫 (n/e)ⁿ：開 n 次方時沒差，但算比值（例如 C(2n, n)）時答案會錯一個 √n 的倍數。","把 (n/e)ⁿ 寫成 nⁿ/e，e 也要 n 次方。","C(2n, n) 的分母 (n!)² 只換一次。"],"checks":[{"ask":"Stirling 公式 n! ~ √(2πn)(n/e)ⁿ 保證的是哪一件事？","options":[{"label":"n!/(√(2πn)(n/e)ⁿ) → 1","correct":true},{"label":"n! − √(2πn)(n/e)ⁿ → 0","why":"差其實越來越大：n = 10 時已經約 30,104。~ 只保證比值 → 1。"},{"label":"n 夠大時 n! = √(2πn)(n/e)ⁿ","why":"右邊從來不是整數，兩者永遠不相等，只是比值越來越接近 1。"}]},{"ask":"lim_{n→∞} (n!)^{1/n}/n 是？","options":[{"label":"1/e","correct":true},{"label":"1","why":"(n!)^{1/n} ~ n/e，不是 ~ n；e^{−n} 開 n 次方剩 1/e。"},{"label":"0","why":"n! 比 nⁿ 小得多是真的，但開 n 次方之後差距只剩常數倍 1/e。"}]},{"ask":"ln(n!) 的主項是？","options":[{"label":"n ln n","correct":true},{"label":"n","why":"後一半的 n/2 項每一項都至少 ln(n/2)，總和至少 (n/2) ln(n/2)，比 n 大得多。"},{"label":"n²","why":"每一項 ln k ≤ ln n，n 項加起來最多 n ln n，到不了 n²。"}]},{"ask":"C(2n, n) 漸近等價於？","options":[{"label":"4ⁿ/√(πn)","correct":true},{"label":"4ⁿ","why":"所有 C(2n, k) 加起來才是 4ⁿ；中間這一項只佔其中約 1/√(πn) 的比例。"},{"label":"2ⁿ","why":"太小了：C(2n, n) 是 2n + 1 個加起來等於 4ⁿ 的數裡最大的，至少 4ⁿ/(2n + 1)。"}]}],"practice":[{"id":"lm-nr-005","core":true},{"id":"cx-hl-004","core":true},{"id":"lm-nr-004","core":true},{"id":"world-035","core":true},{"id":"fd-limx-609","core":true},{"id":"dm-seq-004","core":true},{"id":"world-067"},{"id":"world-074","challenge":true,"note":"挑戰：倒數形式，答案是 √π；√n 的位置要看清楚。"}]},"stolz-cesaro":{"id":"stolz-cesaro","prerequisites":["sequence-limit","lhopital","asymptotic-equivalence"],"next":["euler-maclaurin-intro"],"related":[],"objectives":["寫得出 Stolz–Cesàro 的條件：bₙ 嚴格遞增而且 → ∞，差分比的極限存在。","看到「和除以 n 的次方或 ln n」就會用：相減之後和只剩最後一項。","知道反方向不成立：差分比沒有極限時，定理不說任何事。"],"concept":[{"heading":"① 數列版的 L'Hôpital","body":["數列沒有導數，但有差分 aₙ₊₁ − aₙ。Stolz–Cesàro 定理說：若 bₙ 嚴格遞增而且 bₙ → ∞，並且差分比 (aₙ₊₁ − aₙ)/(bₙ₊₁ − bₙ) → L，則 aₙ/bₙ → L。L 是有限數或 ±∞ 都可以。","注意條件全部壓在分母 bₙ 上，分子 aₙ 不需要 → ∞。"],"tex":["\\lim_{n\\to\\infty}\\frac{a_n}{b_n}=\\lim_{n\\to\\infty}\\frac{a_{n+1}-a_n}{b_{n+1}-b_n}\\quad(\\text{右邊存在時})"]},{"heading":"② 為什麼合理（直覺，不是證明）","body":["把 (bₙ, aₙ) 畫成平面上的點，連成折線。差分比是每一小段的斜率；aₙ/bₙ 是從原點看過去的整體斜率。如果從某段以後每一小段的斜率都接近 L，又因為 bₙ → ∞ 讓後面的段數越來越長，前面那些不聽話的段落佔的比重就越來越小，整體斜率也會被拉到 L。","直覺漏掉的是：「比重越來越小」要靠 bₙ → ∞ 才成立；bₙ 有界時定理會錯。"]},{"heading":"③ 最常見的用法：和除以某個東西","body":["aₙ = x₁ + x₂ + … + xₙ 時，aₙ₊₁ − aₙ = xₙ₊₁，整個和只剩最後一項。所以 Σ 除以 n、nᵖ、√n、ln n 的極限，都變成「最後一項除以分母的差分」。","特例 bₙ = n：若 xₙ → L，則 (x₁ + … + xₙ)/n → L。平均值跟著數列走，這叫 Cesàro 平均。"]},{"heading":"④ 反方向不成立","body":["aₙ = n + (−1)ⁿ、bₙ = n：aₙ/bₙ = 1 + (−1)ⁿ/n → 1。但差分 aₙ₊₁ − aₙ = 1 + 2(−1)ⁿ⁺¹ 在 3 和 −1 之間跳，差分比沒有極限。所以差分比不收斂時，不能說原極限不存在，只能換方法。"]},{"heading":"證明（∞ 型、L 有限）","body":["給 ε > 0，取 N 使 n ≥ N 時差分比落在 (L − ε, L + ε)。bₖ₊₁ − bₖ > 0，所以可以把不等式乘上它：(L − ε)(bₖ₊₁ − bₖ) < aₖ₊₁ − aₖ < (L + ε)(bₖ₊₁ − bₖ)。","對 k = N, …, n − 1 相加，中間全部消掉：(L − ε)(bₙ − b_N) < aₙ − a_N < (L + ε)(bₙ − b_N)。除以 bₙ（n 大時 bₙ > 0），再讓 n → ∞：a_N/bₙ 與 b_N/bₙ 都 → 0，所以 aₙ/bₙ 最後落在 [L − ε, L + ε] 裡。ε 任意，得證。","另有 0/0 版本：bₙ 嚴格遞減到 0、aₙ → 0 時結論一樣。"],"collapsible":true}],"workedExamples":[{"title":"和除以 √n","prompt":"lim_{n→∞} (1/√1 + 1/√2 + … + 1/√n)/√n","problemId":"lm-st-001","steps":["bₙ = √n 嚴格遞增到 ∞，條件成立。","分子差分：aₙ₊₁ − aₙ = 1/√(n + 1)。分母差分：√(n + 1) − √n = 1/(√(n + 1) + √n)（乘共軛）。","差分比 = (√(n + 1) + √n)/√(n + 1) = 1 + √(n/(n + 1)) → 1 + 1 = 2。","所以原極限是 2。"],"answer":"2"},{"title":"平方和除以 n³","prompt":"lim_{n→∞} (1² + 2² + … + n²)/n³","steps":["bₙ = n³ 嚴格遞增到 ∞。","分子差分是最後一項 (n + 1)²；分母差分 (n + 1)³ − n³ = 3n² + 3n + 1。","差分比 (n + 1)²/(3n² + 3n + 1)，分子分母同除以 n²，→ 1/3。"],"answer":"1/3","note":"同樣的算法給出 (1ᵖ + … + nᵖ)/n^{p+1} → 1/(p + 1)，跟 ∫₀¹ xᵖ dx 一樣。"},{"title":"分母是 ln n","prompt":"lim_{n→∞} (1 + 1/2 + … + 1/n)/ln n","problemId":"lm-st-003","steps":["bₙ = ln n 嚴格遞增到 ∞。","分子差分 1/(n + 1)；分母差分 ln(n + 1) − ln n = ln(1 + 1/n)。","ln(1 + 1/n) ~ 1/n（〈漸近等價〉），差分比 ~ n/(n + 1) → 1。","所以調和數 Hₙ ~ ln n。"],"answer":"1"}],"pitfalls":["沒檢查 bₙ 嚴格遞增到 ∞ 就用。","差分比沒有極限，就斷定原極限不存在。","分母差分算錯：(n + 1)³ − n³ 不是 3n²，是 3n² + 3n + 1（極限一樣，但中間式子要對）。","把分子的差分寫成整個和，而不是最後一項。"],"checks":[{"ask":"使用 Stolz–Cesàro（∞ 型）需要哪個條件？","options":[{"label":"bₙ 嚴格遞增，而且 bₙ → ∞","correct":true},{"label":"aₙ → ∞","why":"定理對分子沒有要求；條件全部在分母 bₙ 上。"},{"label":"aₙ 與 bₙ 都遞增","why":"aₙ 可以不單調；需要單調而且 → ∞ 的只有 bₙ。"}]},{"ask":"lim (1 + 2 + … + n)/n² 用 Stolz 算，答案是？","options":[{"label":"1/2","correct":true},{"label":"1","why":"分母差分是 (n + 1)² − n² = 2n + 1，不是 n + 1。差分比 (n + 1)/(2n + 1) → 1/2。"},{"label":"0","why":"分子的和也是 n² 階（n(n + 1)/2），兩者同階，比值不會 → 0。"}]},{"ask":"若 xₙ → 3，則 (x₁ + x₂ + … + xₙ)/n 的極限是？","options":[{"label":"3","correct":true},{"label":"0","why":"每一項 xₖ/n → 0 沒錯，但有 n 項，不能逐項取極限。用 Stolz（bₙ = n）差分比是 xₙ₊₁ → 3。"},{"label":"不一定存在","why":"xₙ 收斂時，Cesàro 平均一定收斂到同一個值，這正是 Stolz 在 bₙ = n 的特例。"}]},{"ask":"如果差分比 (aₙ₊₁ − aₙ)/(bₙ₊₁ − bₙ) 沒有極限，那麼 aₙ/bₙ：","options":[{"label":"可能有極限，也可能沒有，要換方法","correct":true},{"label":"一定沒有極限","why":"反例 aₙ = n + (−1)ⁿ、bₙ = n：差分比在 3 與 −1 之間跳，aₙ/bₙ 卻 → 1。"},{"label":"一定是 0","why":"沒有任何根據；定理在這個情況下什麼都沒說。"}]}],"practice":[{"id":"lm-st-001","core":true},{"id":"dm-seq-006","core":true},{"id":"lm-st-004","core":true},{"id":"lm-st-006","core":true},{"id":"lm-st-003"},{"id":"dm-seq-001"},{"id":"lx-seq-005","challenge":true,"note":"挑戰：對 1/xₙ² 用 Stolz，先算 1/xₙ₊₁² − 1/xₙ² → 1/3。"},{"id":"dm-seq-002","challenge":true,"note":"挑戰：同一招，題目已經把差分的極限給你，最後開根號。"}]},"euler-maclaurin-intro":{"id":"euler-maclaurin-intro","prerequisites":["integral-test","riemann-sum-intuition","integration-by-parts","big-o-little-o"],"next":["improper-infinite"],"related":["stirling","basel-problem"],"objectives":["說得出「和 ≈ 積分 + 端點平均 + 導數修正」三層，以及每一層修正的是什麼。","用前兩、三項估計和或級數的尾巴，例如 Hₙ ≈ ln n + γ + 1/(2n)、Σ_{k≥N} 1/k² ≈ 1/N + 1/(2N²) + 1/(6N³)。","知道這是漸近展開：取前幾項配合誤差估計，不是越多項越準。"],"concept":[{"heading":"① 和與積分差多少","body":["〈積分判別〉用 ∫ f dx 夾住 Σ f(k)，只知道兩者同階。Euler–Maclaurin 公式把差距一層一層算出來（f 夠光滑、a < b 是整數）："],"tex":["\\sum_{k=a}^{b}f(k)=\\int_a^b f(x)\\,dx+\\frac{f(a)+f(b)}{2}+\\frac{f'(b)-f'(a)}{12}-\\frac{f'''(b)-f'''(a)}{720}+\\cdots"]},{"heading":"② 每一層在修正什麼（圖像）","body":["積分：曲線下的面積。端點平均：把長條換成梯形時，頭尾各多算了半個長條。f′ 項：梯形的斜邊與曲線之間還有一點彎曲造成的縫，總量跟 f′ 從頭到尾的變化有關，係數 1/12。再下一層 1/720 修正更細的彎曲。","f 是多項式時，高階導數最後全是 0，公式在有限項就停住，是精確等式。"]},{"heading":"③ 兩個代表性的結果","body":["調和數：Hₙ = 1 + 1/2 + … + 1/n = ln n + γ + 1/(2n) − 1/(12n²) + …，其中 γ ≈ 0.5772 是 Euler–Mascheroni 常數。所以 Hₙ − ln n → γ，不是 → 0。","級數的尾巴（b → ∞，f 與 f′ 在 ∞ 都 → 0）：Σ_{k=N}^∞ f(k) ≈ ∫_N^∞ f dx + f(N)/2 − f′(N)/12。只加前幾項、尾巴用這條估，就能把收斂很慢的級數算得很準。"]},{"heading":"④ 不是越多項越準","body":["修正項的係數（Bernoulli 數）最後會以階乘速度長大，整條無窮級數通常發散。正確用法：固定取前幾項，誤差由下一項的大小控制。這叫漸近展開——n 越大，取同樣幾項就越準。"]},{"heading":"第一層修正的推導","body":["在 [k, k + 1] 上分部積分，取 u = f、v = x − k − 1/2：∫ₖ^{k+1} f dx = (f(k) + f(k + 1))/2 − ∫ₖ^{k+1} (x − k − 1/2) f′(x) dx。","對 k = a, …, b − 1 相加，用 {x} 表示 x 的小數部分，得到精確等式：Σ_{k=a}^b f(k) = ∫ₐᵇ f + (f(a) + f(b))/2 + ∫ₐᵇ ({x} − 1/2) f′(x) dx。最後一項再分部積分一次，就生出 (f′(b) − f′(a))/12，依此類推。"],"collapsible":true}],"workedExamples":[{"title":"多項式：公式是精確的","prompt":"用 Euler–Maclaurin 求 Σ_{k=1}^n k²。","steps":["f(x) = x²，f′(x) = 2x，f‴ = 0，所以公式在 f′ 那項就停。","∫₁ⁿ x² dx = (n³ − 1)/3；端點平均 (1 + n²)/2；導數修正 (f′(n) − f′(1))/12 = (2n − 2)/12。","相加：n³/3 − 1/3 + 1/2 + n²/2 + n/6 − 1/6 = n³/3 + n²/2 + n/6。","整理成 n(n + 1)(2n + 1)/6，正是熟悉的平方和公式。"],"answer":"n³/3 + n²/2 + n/6"},{"title":"調和數 H₁₀","prompt":"用 Hₙ ≈ ln n + γ + 1/(2n) − 1/(12n²) 估 H₁₀，與真值比較。","steps":["ln 10 ≈ 2.302585，γ ≈ 0.577216，1/20 = 0.05，1/1200 ≈ 0.000833。","相加：2.302585 + 0.577216 + 0.05 − 0.000833 ≈ 2.928967。","真值 H₁₀ = 7381/2520 ≈ 2.928968，誤差不到 10⁻⁶。","只用 ln 10 + γ ≈ 2.879801，誤差約 0.049，差不多就是 1/(2n)。"],"answer":"≈ 2.928967（真值 ≈ 2.928968）"},{"title":"用尾巴估計加速級數","prompt":"只加 Σ_{k=1}^9 1/k²，尾巴用 Euler–Maclaurin 估，求 Σ_{k=1}^∞ 1/k² 的近似值。","steps":["前 9 項和 ≈ 1.5397677。","尾巴 Σ_{k=10}^∞ 1/k²：f(x) = 1/x²，∫₁₀^∞ dx/x² = 1/10，f(10)/2 = 1/200，f′(x) = −2/x³，−f′(10)/12 = 2/(12 · 1000) = 1/6000。","尾巴 ≈ 0.1 + 0.005 + 0.0001667 = 0.1051667。","總和 ≈ 1.6449344；真值 π²/6 ≈ 1.6449341（〈Basel 問題〉）。只加前 9 項的誤差約 0.105，加上尾巴估計後誤差約 3 × 10⁻⁷。"],"answer":"≈ 1.6449344"}],"pitfalls":["漏掉端點平均，只寫「和 ≈ 積分」，誤差是 f 本身的大小。","以為 Hₙ ~ ln n 代表 Hₙ − ln n → 0；其實 → γ。","導數修正的符號：尾巴公式是 −f′(N)/12，遞減函數的 f′ < 0，這一項是正的。","以為取越多修正項越準。"],"checks":[{"ask":"用 ∫₁ⁿ f dx + (f(1) + f(n))/2 計算 Σ_{k=1}^n k（f(x) = x），得到？","options":[{"label":"n(n + 1)/2","correct":true},{"label":"(n² − 1)/2","why":"那只是積分，漏了端點平均 (1 + n)/2。"},{"label":"n²/2","why":"積分算錯了下限：∫₁ⁿ x dx = (n² − 1)/2，再加 (1 + n)/2 才是 n(n + 1)/2。"}]},{"ask":"為什麼 Σ k² 用到 f′ 那一項就完全正確？","options":[{"label":"f(x) = x² 的三階以上導數都是 0，後面的修正項全部消失","correct":true},{"label":"因為 x² 是遞增函數","why":"遞增只保證和與積分的大小關係，跟修正項會不會停沒有關係。"},{"label":"因為後面的修正項正負抵銷","why":"不是抵銷，是每一項本身就是 0：它們都含 f‴、f⁽⁵⁾……"}]},{"ask":"n → ∞ 時，Hₙ − ln n 趨近？","options":[{"label":"γ ≈ 0.5772","correct":true},{"label":"0","why":"Hₙ ~ ln n 只說比值 → 1，差可以趨近非零常數。"},{"label":"1/2","why":"1/2 出現在 1/(2n) 這一項，它會 → 0；留下的常數是 γ。"}]},{"ask":"Euler–Maclaurin 的修正項應該怎麼用？","options":[{"label":"取前幾項，用下一項的大小估計誤差","correct":true},{"label":"取越多項越準，取到無窮多項就是精確值","why":"修正項的係數最後以階乘速度長大，無窮級數通常發散；它是漸近展開。"},{"label":"只能用在多項式","why":"任何夠光滑的 f 都能用；多項式只是剛好在有限項變成精確等式。"}]}],"practice":[{"id":"sg-est-004","core":true},{"id":"lec-12-q2d","core":true},{"id":"lm-st-002","core":true},{"id":"sg-est-003","core":true},{"id":"sg-est-005"},{"id":"an-ca-001"}]},"improper-infinite":{"id":"improper-infinite","prerequisites":["ftc-part2","limit-at-infinity","integration-by-parts","inverse-trig-derivative"],"next":["improper-singular"],"related":["lhopital","integral-test"],"objectives":["用「先積到 t，再讓 t → ∞」的定義算 ∫ₐ^∞ f dx，並判斷收斂或發散。","處理兩端都是無窮的積分：切成兩半，兩半要各自收斂。","分部積分時，把邊界項寫成極限來算，不直接「代入 ∞」。"],"concept":[{"heading":"① 區間無限長，面積還可能有限","body":["∫₁^∞ dx/x² 問的是「y = 1/x² 從 1 一路到無窮遠，底下的面積」。區間無限長，但曲線降得夠快，面積可能是有限的數。我們不能直接把 ∞ 代進反導函數，要用極限來定義。"]},{"heading":"② 定義：先積到 t，再讓 t → ∞","body":["若 f 在每一個 [a, t] 上都可積，定義 ∫ₐ^∞ f dx = lim_{t→∞} ∫ₐᵗ f dx。極限存在（是有限數）叫收斂；極限是 ±∞ 或不存在叫發散。∫_{−∞}^b 同理。","∫₁ᵗ dx/x² = 1 − 1/t → 1，收斂；∫₁ᵗ dx/x = ln t → ∞，發散。兩條曲線都 → 0，但 1/x 降得不夠快。被積函數 → 0 不是收斂的保證。"],"tex":["\\int_a^{\\infty}f(x)\\,dx=\\lim_{t\\to\\infty}\\int_a^{t}f(x)\\,dx"]},{"heading":"③ 兩端都無窮：切開，兩半各自收斂","body":["∫_{−∞}^∞ f dx 的定義是任選一點 c，∫_{−∞}^c f + ∫_c^∞ f，而且兩半都要收斂才算收斂（選哪個 c 結果都一樣）。","不能用 lim_{t→∞} ∫_{−t}^t 代替：∫_{−t}^t x dx = 0，但 ∫₀^∞ x dx 發散，所以 ∫_{−∞}^∞ x dx 發散。對稱地一起取極限會把兩個 ∞ 互相抵銷，掩蓋發散。"]},{"heading":"④ 分部積分：邊界項要取極限","body":["[uv]₁^∞ 的意思是 lim_{t→∞} u(t)v(t) − u(1)v(1)。像 ln t/t 這種 ∞/∞ 的極限，用 〈L'Hôpital 法則〉或成長階梯（對數 ≪ 冪次）處理。"]},{"heading":"為什麼「被積函數 → 0」不夠，反過來呢？","body":["1/x → 0 但積分發散，所以 f → 0 不是充分條件。反過來，積分收斂也不保證 f → 0：可以在每個整數 n 附近放一個高度 1、寬度 1/n² 的窄三角形，其餘地方是 0，面積總和 Σ 1/(2n²) 收斂，但 f 不 → 0。這跟級數「aₙ → 0 是必要條件」不一樣（〈積分判別〉要求 f 遞減，就是為了避開這種情況）。"],"collapsible":true}],"workedExamples":[{"title":"收斂與發散的分界","prompt":"∫₁^∞ dx/x² 與 ∫₁^∞ dx/x","steps":["∫₁ᵗ x⁻² dx = [−1/x]₁ᵗ = 1 − 1/t。t → ∞ 時 → 1，收斂，值是 1。","∫₁ᵗ x⁻¹ dx = ln t − ln 1 = ln t。t → ∞ 時 → ∞，發散。"],"answer":"第一個是 1；第二個發散"},{"title":"分部積分，邊界項用極限","prompt":"∫₁^∞ (ln x)/x² dx","problemId":"lec-08-q2a","steps":["令 u = ln x、dv = x⁻² dx，du = dx/x、v = −1/x。∫ (ln x)/x² dx = −(ln x)/x + ∫ dx/x² = −(ln x)/x − 1/x + C。","從 1 積到 t：( −(ln t)/t − 1/t ) − ( 0 − 1 ) = 1 − (ln t + 1)/t。","t → ∞ 時 (ln t + 1)/t → 0（L'Hôpital：(1/t)/1 → 0）。","所以積分收斂，值是 1。"],"answer":"1"},{"title":"兩端都無窮","prompt":"∫_{−∞}^∞ dx/(1 + x²)","problemId":"lec-08-q2c","steps":["在 0 切開：∫_{−∞}^0 + ∫₀^∞。","∫₀ᵗ dx/(1 + x²) = arctan t → π/2（t → ∞），右半收斂到 π/2。","∫_s^0 dx/(1 + x²) = −arctan s → π/2（s → −∞），左半也收斂到 π/2。","兩半都收斂，總和 π。"],"answer":"π"}],"pitfalls":["直接把 ∞ 代進反導函數，寫出「−1/∞ = 0」這種沒有定義的式子；要寫成 t → ∞ 的極限。","看到被積函數 → 0 就說收斂（1/x 是反例）。","∫_{−∞}^∞ 用對稱極限 lim ∫_{−t}^t，把發散的積分算成 0。","分部積分後忘了檢查邊界項的極限存不存在。"],"checks":[{"ask":"∫₀^∞ e^{−3x} dx 是？","options":[{"label":"1/3","correct":true},{"label":"3","why":"反導函數是 −e^{−3x}/3，要除以 3，不是乘。"},{"label":"發散，因為區間是無限長","why":"區間無限長不代表發散：∫₀ᵗ e^{−3x} dx = (1 − e^{−3t})/3 → 1/3。"}]},{"ask":"∫_{−∞}^∞ x dx：","options":[{"label":"發散","correct":true},{"label":"0，因為 x 是奇函數","why":"要切成兩半各自收斂；∫₀^∞ x dx 已經發散。lim ∫_{−t}^t x dx = 0 是對稱抵銷，不是定義。"},{"label":"∞","why":"左半是 −∞、右半是 +∞，加起來不是 ∞，而是沒有定義；結論是發散。"}]},{"ask":"∫₁^∞ dx/x：","options":[{"label":"發散","correct":true},{"label":"收斂，因為 1/x → 0","why":"1/x 降得不夠快：∫₁ᵗ dx/x = ln t → ∞。"},{"label":"收斂到 1","why":"1 是 ∫₁^∞ dx/x² 的值；1/x 的面積沒有上限。"}]},{"ask":"∫ₐ^∞ f dx 的定義是？","options":[{"label":"lim_{t→∞} ∫ₐᵗ f dx","correct":true},{"label":"F(∞) − F(a)","why":"F(∞) 不是一個數；要寫成 lim_{t→∞} F(t) − F(a)，而且這個極限可能不存在。"},{"label":"lim_{x→∞} f(x)","why":"那是被積函數的極限，不是面積。1/x → 0 但面積發散。"}]}],"practice":[{"id":"exam-int-026","core":true},{"id":"uni-int-025","core":true},{"id":"uni-int-018","core":true},{"id":"depth-int-019","core":true},{"id":"lec-08-q2a","core":true},{"id":"lec-08-q2c","core":true},{"id":"int-040"},{"id":"uni-int-014"},{"id":"depth-int-020"},{"id":"cx-hi-007","challenge":true,"note":"挑戰：先部分分式成兩個 arctan，再各自取極限。"}]},"improper-singular":{"id":"improper-singular","prerequisites":["improper-infinite","lhopital","u-sub-definite"],"next":["improper-p-test"],"related":["discontinuity-types"],"objectives":["被積函數在端點附近無界時，用「從瑕點旁邊積起，再取極限」的定義計算。","瑕點在區間內部時，先在瑕點切開，兩邊各自收斂才算收斂。","一個積分同時有好幾個問題點（端點無界、區間無限）時，切成每段只有一個問題。"],"concept":[{"heading":"① 另一種瑕：函數衝到無窮高","body":["∫₀¹ dx/√x 的區間有限，但 1/√x 在 x → 0⁺ 時 → ∞，曲線底下是一根無限高的尖刺。上一課是「區間無限長」，這一課是「函數無界」，處理方法一樣：先避開問題點，再取極限。"]},{"heading":"② 定義：從瑕點旁邊積起","body":["f 在 (a, b] 上連續、在 a 附近無界：∫ₐᵇ f dx = lim_{s→a⁺} ∫ₛᵇ f dx。瑕點在右端點 b 時用 t → b⁻。極限是有限數叫收斂。","∫ₛ¹ dx/√x = 2 − 2√s → 2，收斂；∫ₛ¹ dx/x = −ln s → ∞，發散。"],"tex":["\\int_a^{b}f(x)\\,dx=\\lim_{s\\to a^{+}}\\int_s^{b}f(x)\\,dx"]},{"heading":"③ 瑕點在中間：一定要先切開","body":["∫_{−1}^1 dx/x²：1/x² 在 x = 0 無界。直接套微積分基本定理得 [−1/x]_{−1}^1 = −2，一個正函數積出負數，顯然不對——基本定理要求 f 在整個區間連續，這裡不成立。","正確做法：切成 ∫_{−1}^0 + ∫_0^1，兩半各自收斂才算收斂。∫ₛ¹ dx/x² = 1/s − 1 → ∞，所以整個積分發散。"]},{"heading":"④ 好幾個問題點：每段只留一個","body":["∫₀^∞ dx/(√x(1 + x)) 在 x = 0 無界、區間又無限長。在中間任一點（例如 1）切開，每一段只處理一個問題；兩段都收斂才算收斂。","也要分辨「假的瑕點」：sin x/x 在 x = 0 沒定義，但極限是 1，補上 f(0) = 1 就是連續函數（可去不連續，見〈不連續的種類〉），∫₀¹ sin x/x dx 是普通的定積分。"]}],"workedExamples":[{"title":"端點的尖刺","prompt":"∫₀¹ dx/√x","problemId":"lec-08-m2","steps":["1/√x 在 x → 0⁺ 時 → ∞，0 是瑕點。從 s > 0 積起。","∫ₛ¹ x^{−1/2} dx = [2√x]ₛ¹ = 2 − 2√s。","s → 0⁺ 時 √s → 0，極限是 2。收斂。"],"answer":"2"},{"title":"瑕點在中間的陷阱","prompt":"∫_{−1}^1 dx/x²","problemId":"lec-08-m3","steps":["1/x² 在 x = 0 無界，0 在區間內部。不能直接用基本定理（那樣會得到錯的 −2）。","切成 ∫_{−1}^0 + ∫₀¹，先看右半：∫ₛ¹ x⁻² dx = 1/s − 1。","s → 0⁺ 時 1/s → ∞，右半發散。只要有一半發散，整個積分就發散。"],"answer":"發散"},{"title":"兩個問題點：先切開","prompt":"∫₀^∞ dx/(√x(1 + x))","steps":["x = 0 無界、上限無限。在 1 切開：∫₀¹ + ∫₁^∞，兩段都要收斂（下一課的 p 判別可以馬上看出來；這裡直接算）。","令 u = √x，x = u²，dx = 2u du，√x = u。被積函數變成 2u du/(u(1 + u²)) = 2 du/(1 + u²)；x 從 0 到 ∞ 對應 u 從 0 到 ∞。","∫₀^∞ 2 du/(1 + u²) = 2 · lim_{t→∞} arctan t = 2 · π/2 = π。換元後的積分收斂，原積分也收斂（兩邊的部分積分逐段相等）。"],"answer":"π"}],"pitfalls":["沒發現區間內部有瑕點，直接用基本定理（∫_{−1}^1 dx/x² 算成 −2）。","兩半只要有一半發散，整個就發散；不能用另一半的 −∞ 去「抵銷」。","把 ln 0、1/0 直接當成數代進去；要寫成 s → 0⁺ 的極限。","把 sin x/x 在 0 這種可去的點也當成瑕點，還去判斷它「發散」。"],"checks":[{"ask":"∫₀¹ ln x dx 是？","options":[{"label":"−1","correct":true},{"label":"發散，因為 ln 0 沒有定義","why":"ln x 在 0 無界，但無界不等於發散：∫ₛ¹ ln x dx = −1 − s ln s + s → −1（s ln s → 0）。"},{"label":"1","why":"ln x 在 (0, 1) 是負的，面積帶負號。"}]},{"ask":"∫_{−1}^1 dx/x² 是？","options":[{"label":"發散","correct":true},{"label":"−2","why":"那是直接套 [−1/x]_{−1}^1 的結果；1/x² 在 0 無界，基本定理不能跨過瑕點。正函數也不可能積出負數。"},{"label":"2","why":"切開後 ∫ₛ¹ dx/x² = 1/s − 1 → ∞，每一半都發散。"}]},{"ask":"∫₀¹ (sin x)/x dx 需要當瑕積分處理嗎？","options":[{"label":"不需要：x → 0 時 sin x/x → 1，補上 f(0) = 1 就是連續函數","correct":true},{"label":"需要，而且發散，因為分母在 0 是 0","why":"分母是 0 不代表無界；sin x/x 在 0 附近有界（→ 1）。"},{"label":"需要，用 p 判別 p = 1 所以發散","why":"p 判別比的是 1/xᵖ，但 sin x/x 在 0 附近像 1，不像 1/x。"}]},{"ask":"∫₀^∞ dx/(√x(1 + x)) 有幾個問題點？","options":[{"label":"兩個：x → 0⁺ 無界、x → ∞ 區間無限，要切開分別處理","correct":true},{"label":"只有 x → ∞","why":"x → 0⁺ 時 1/√x → ∞，這一端也是瑕點。"},{"label":"只有 x = 0","why":"上限是 ∞，那一端也要取極限。"}]}],"practice":[{"id":"lec-08-m2","core":true},{"id":"exam-int-025","core":true},{"id":"depth-int-028","core":true},{"id":"rel-hard-int-015","core":true},{"id":"rel-boss-017","core":true},{"id":"lec-08-m3"},{"id":"lec-08-q2d","challenge":true,"note":"挑戰：瑕點 x = 1 在區間內部，切成兩段，兩段都收斂。"}]},"improper-p-test":{"id":"improper-p-test","prerequisites":["improper-infinite","improper-singular"],"next":["improper-comparison"],"related":["p-series","integral-test"],"objectives":["背得出兩個方向相反的條件：∫₁^∞ dx/xᵖ 收斂 ⇔ p > 1；∫₀¹ dx/xᵖ 收斂 ⇔ p < 1。","會從反導函數推出這兩個條件，並算出收斂時的值 1/(p − 1) 與 1/(1 − p)。","會把同一個想法用在 (x − a)ᵖ 與 x(ln x)ᵖ 這類變形上。"],"concept":[{"heading":"① 兩把最基本的尺","body":["判斷瑕積分收不收斂，最常拿來比較的就是 1/xᵖ。它在兩個地方會出問題：x → ∞（區間無限）與 x → 0⁺（p > 0 時函數無界）。兩個地方的條件剛好相反。"]},{"heading":"② 直接算出來","body":["p ≠ 1 時反導函數是 x^{1−p}/(1 − p)。","∞ 那端：∫₁ᵗ x^{−p} dx = (t^{1−p} − 1)/(1 − p)。p > 1 時 t^{1−p} → 0，積分 → 1/(p − 1)；p < 1 時 t^{1−p} → ∞，發散。","0 那端：∫ₛ¹ x^{−p} dx = (1 − s^{1−p})/(1 − p)。p < 1 時 s^{1−p} → 0，積分 → 1/(1 − p)；p > 1 時 s^{1−p} → ∞，發散。","p = 1 時反導函數是 ln x，兩端都發散（ln t → ∞、−ln s → ∞）。"],"tex":["\\int_1^{\\infty}\\frac{dx}{x^{p}}\\ \\text{收斂}\\iff p>1,\\qquad \\int_0^{1}\\frac{dx}{x^{p}}\\ \\text{收斂}\\iff p<1"]},{"heading":"③ 怎麼記：遠方要瘦，近處不能太尖","body":["在 ∞ 那端，1/xᵖ 要降得比 1/x 快（p > 1）面積才有限；在 0 那端，1/xᵖ 要衝得比 1/x 慢（p < 1）尖刺才有限。1/x 剛好卡在兩邊的分界，兩邊都發散。所以 ∫₀^∞ dx/xᵖ 對任何 p 都發散：一端要 p > 1，另一端要 p < 1，不可能同時成立。"]},{"heading":"④ 平移與對數的變形","body":["瑕點在 a 而不是 0：∫ₐᵇ dx/(x − a)ᵖ 收斂 ⇔ p < 1（令 u = x − a）。","差一點點的情況要看對數：∫₂^∞ dx/(x (ln x)ᵖ) 令 u = ln x 變成 ∫_{ln 2}^∞ du/uᵖ，收斂 ⇔ p > 1。這跟〈p 級數〉與〈積分判別〉的結論一模一樣。"]}],"workedExamples":[{"title":"∞ 那端：p = 3 與 p = 3/2","prompt":"∫₁^∞ dx/x³ 與 ∫₁^∞ dx/x^{3/2}","steps":["兩個都是 p > 1，收斂，值是 1/(p − 1)。","p = 3：1/(3 − 1) = 1/2。","p = 3/2：1/(3/2 − 1) = 2。"],"answer":"1/2 與 2"},{"title":"0 那端：p = 2/3","prompt":"∫₀¹ dx/x^{2/3}","steps":["x → 0⁺ 無界，p = 2/3 < 1，收斂。","反導函數 x^{1/3}/(1/3) = 3x^{1/3}。∫ₛ¹ = 3 − 3s^{1/3}。","s → 0⁺ 時 s^{1/3} → 0，值是 3，也就是 1/(1 − 2/3)。"],"answer":"3","note":"同一個函數在 [1, ∞) 上發散（p = 2/3 < 1）。"},{"title":"對數的變形","prompt":"∫₂^∞ dx/(x (ln x)²)","steps":["令 u = ln x，du = dx/x；x = 2 對應 u = ln 2，x → ∞ 對應 u → ∞。","積分變成 ∫_{ln 2}^∞ du/u²，是 p = 2 > 1 的情況，收斂。","值：[−1/u]_{ln 2}^∞ = 1/ln 2 ≈ 1.4427。"],"answer":"1/ln 2"}],"pitfalls":["兩端的條件記反：∞ 端是 p > 1，0 端是 p < 1。","以為 p = 1 在某一端會收斂；1/x 兩端都發散。","收斂值寫成 1/p；正確是 1/(p − 1)（∞ 端）或 1/(1 − p)（0 端）。","∫₀^∞ dx/xᵖ 只檢查一端。"],"checks":[{"ask":"∫₁^∞ dx/√x：","options":[{"label":"發散","correct":true},{"label":"收斂到 2","why":"2 是 ∫₀¹ dx/√x 的值。在 [1, ∞) 上 p = 1/2 < 1，反導函數 2√t → ∞。"},{"label":"收斂，因為 1/√x → 0","why":"趨近 0 不夠，要比 1/x 快；1/√x 比 1/x 還慢。"}]},{"ask":"∫₁^∞ dx/x⁴ 是？","options":[{"label":"1/3","correct":true},{"label":"1/4","why":"收斂值是 1/(p − 1)，不是 1/p：反導函數 −1/(3x³) 在 1 的值決定答案。"},{"label":"−1/3","why":"正函數的積分是正的；[−1/(3x³)]₁^∞ = 0 − (−1/3) = 1/3。"}]},{"ask":"∫₀^∞ dx/x²：","options":[{"label":"發散","correct":true},{"label":"1","why":"1 只是 [1, ∞) 那一半。[0, 1] 那一半 p = 2 > 1 會發散，所以整個發散。"},{"label":"收斂，因為 p = 2 > 1","why":"p > 1 只保證 ∞ 那端；0 那端要 p < 1，兩端條件相反。"}]},{"ask":"∫₂^∞ dx/(x (ln x)ᵖ) 在什麼條件下收斂？","options":[{"label":"p > 1","correct":true},{"label":"p ≥ 1","why":"p = 1 時令 u = ln x 得 ∫ du/u，發散。"},{"label":"對所有 p 都收斂，因為多了 1/x","why":"1/x 已經被 du = dx/x 吃掉，剩下的是 ∫ du/uᵖ，還是要 p > 1。"}]}],"practice":[{"id":"lec-08-m2","core":true},{"id":"lec-12-q2b","core":true},{"id":"cx-smid-012","core":true},{"id":"lec-08-q3d"}]},"improper-comparison":{"id":"improper-comparison","prerequisites":["improper-p-test","asymptotic-equivalence","comparison-test","limit-comparison-test"],"next":["improper-conditional"],"related":["improper-singular"],"objectives":["用直接比較判斷非負函數的瑕積分：被收斂的壓住就收斂、壓住發散的就發散。","用極限比較（f ~ c·g）只看主項，跟 1/xᵖ 或 e^{−x} 比。","知道比較判別要求非負；會變號的函數先看 |f|（絕對收斂）。"],"concept":[{"heading":"① 算不出來，也能判斷收不收斂","body":["∫₁^∞ dx/(x³ + x + 1) 的反導函數很難寫，但要問的只是收不收斂。想法跟〈比較判別〉（級數）一樣：拿一個已經知道答案的函數來壓它。"]},{"heading":"② 直接比較（f、g ≥ 0）","body":["在 [a, ∞) 上 0 ≤ f(x) ≤ g(x)：∫ₐ^∞ g 收斂 ⇒ ∫ₐ^∞ f 收斂；∫ₐ^∞ f 發散 ⇒ ∫ₐ^∞ g 發散。","反方向沒有結論：被發散的壓住、或壓住收斂的，什麼都說不出來。","瑕點在有限端點時一樣成立，只是比較對象換成 0 端的 1/xᵖ（p < 1 收斂）。"]},{"heading":"③ 極限比較：只看主項","body":["f、g > 0，x → ∞ 時 f/g → L，而且 0 < L < ∞：兩個積分同時收斂或同時發散。換成上一課的話就是 f ~ L·g，主項決定命運。","做法：找出 f 在問題點附近的主項，寫成 c/xᵖ，再用 p 判別。例如 (x + 1)/(x³ + 2) ~ 1/x²（x → ∞），收斂；x/(x² + 1) ~ 1/x，發散。"]},{"heading":"④ 常用的比較對象","body":["x → ∞：1/xᵖ；指數衰減比任何冪次快，所以 xⁿe^{−x} ≤ C/x² 在 x 夠大時成立（成長階梯）。例如 x ≥ 1 時 e^{−x²} ≤ e^{−x}，所以 ∫₀^∞ e^{−x²} dx 收斂。","會變號的函數不能直接比，但可以看 |f|：若 ∫|f| 收斂（絕對收斂），則 ∫f 也收斂。例如 |sin x/x²| ≤ 1/x²。"]},{"heading":"為什麼直接比較成立","body":["f ≥ 0 時，F(t) = ∫ₐᵗ f dx 隨 t 遞增。f ≤ g 給出 F(t) ≤ ∫ₐ^∞ g，所以 F 遞增又有上界，t → ∞ 時一定有極限（實數的完備性，跟單調收斂定理同一個道理）。","絕對收斂 ⇒ 收斂：0 ≤ f + |f| ≤ 2|f|，由直接比較 ∫(f + |f|) 收斂，再減掉收斂的 ∫|f|。"],"collapsible":true}],"workedExamples":[{"title":"壓在收斂的底下","prompt":"判斷 ∫₁^∞ dx/(x³ + x + 1)","problemId":"lec-08-q3b","steps":["x ≥ 1 時分母 x³ + x + 1 > x³ > 0，所以 0 < 1/(x³ + x + 1) < 1/x³。","∫₁^∞ dx/x³ 是 p = 3 > 1，收斂（值 1/2）。","由直接比較，原積分收斂，而且值小於 1/2。"],"answer":"收斂（值 < 1/2）"},{"title":"壓住發散的","prompt":"判斷 ∫₁^∞ (2 + cos x)/x dx","problemId":"lec-08-q3a","steps":["cos x ≥ −1，所以 2 + cos x ≥ 1，被積函數 ≥ 1/x > 0。","∫₁^∞ dx/x 發散（p = 1）。","原積分壓在發散的上面，所以發散。cos x 的振盪不影響結論。"],"answer":"發散"},{"title":"兩個問題點、各用一次極限比較","prompt":"判斷 ∫₀^∞ dx/(√x(1 + x))","steps":["在 1 切開。被積函數處處為正。","x → 0⁺：1 + x → 1，所以被積函數 ~ 1/√x = 1/x^{1/2}。p = 1/2 < 1，[0, 1] 那段收斂。","x → ∞：1 + x ~ x，所以被積函數 ~ 1/(√x · x) = 1/x^{3/2}。p = 3/2 > 1，[1, ∞) 那段收斂。","兩段都收斂，整個收斂（〈瑕積分 II：奇異點〉算出它等於 π）。"],"answer":"收斂"}],"pitfalls":["方向用反：被發散的函數壓住，就說發散。","對會變號的函數直接比較，例如用 −x ≤ 1/x² 推出 ∫₁^∞ (−x) dx 收斂。","極限比較只看一端，忘了另一個問題點。","主項抓錯：x/(x² + 1) 的主項是 1/x，不是 1/x²。"],"checks":[{"ask":"在 [1, ∞) 上 0 ≤ f ≤ g，而且 ∫₁^∞ g 發散。可以得到什麼？","options":[{"label":"沒有結論","correct":true},{"label":"∫₁^∞ f 發散","why":"f 比 g 小，g 的面積無限大不代表 f 的也是；例如 f = 1/x²、g = 1/x。"},{"label":"∫₁^∞ f 收斂","why":"也不一定：f = g/2 也滿足條件，而它發散。"}]},{"ask":"∫₁^∞ x/(x³ + 1) dx：","options":[{"label":"收斂：被積函數 ~ 1/x²，p = 2 > 1","correct":true},{"label":"發散：跟 1/x 比","why":"分子 x、分母 x³，主項是 x/x³ = 1/x²，不是 1/x。"},{"label":"要先算出反導函數才能判斷","why":"比較判別的目的就是不用算出值也能判斷。"}]},{"ask":"∫₁^∞ (sin² x)/x² dx：","options":[{"label":"收斂，因為 0 ≤ sin² x/x² ≤ 1/x²","correct":true},{"label":"不能用比較，因為 sin 會振盪","why":"sin² x 不會變號，0 ≤ sin² x ≤ 1，直接比較完全合法。"},{"label":"發散，因為 sin² x 沒有極限","why":"被積函數是否有極限不重要；它被 1/x² 壓住，面積有限。"}]},{"ask":"直接比較判別一定要求什麼？","options":[{"label":"f、g 在問題點附近非負","correct":true},{"label":"只要 f ≤ g 就好，不用管正負","why":"反例：−x ≤ 1/x²，∫₁^∞ dx/x² 收斂，但 ∫₁^∞ (−x) dx 發散到 −∞。"},{"label":"f 與 g 都要有初等反導函數","why":"比較判別完全不用反導函數；這正是它有用的原因。"}]}],"practice":[{"id":"lec-08-q3b","core":true},{"id":"lec-08-q3a","core":true},{"id":"lec-08-q3c","core":true},{"id":"lec-08-m5","core":true}]},"improper-conditional":{"id":"improper-conditional","prerequisites":["improper-comparison","integration-by-parts","alternating-series-test","conditional-convergence"],"next":["reduction-formula"],"related":["dirichlet-integral"],"objectives":["用分部積分證明 ∫₁^∞ sin x/x dx 收斂，說得出為什麼比較判別在這裡失效。","證明 ∫₁^∞ |sin x|/x dx 發散，分清楚條件收斂與絕對收斂。","判斷 ∫ sin x/xᵖ、∫ sin(x²) 這類振盪積分是絕對收斂、條件收斂還是發散。"],"concept":[{"heading":"① 比較判別在這裡失靈","body":["∫₀^∞ sin x/x dx：在 0 附近 sin x/x → 1，沒有問題；麻煩在 ∞ 那端。","想用比較：|sin x/x| ≤ 1/x，可是 ∫₁^∞ dx/x 發散，被發散的壓住什麼都說不出來。sin x/x 會變號，比較判別本來就不能直接用。"]},{"heading":"② 圖像：一正一負、越來越小的拱","body":["sin x/x 的圖形是一串拱：[0, π] 正、[π, 2π] 負、[2π, 3π] 正……[kπ, (k + 1)π] 那個拱的面積大約 ±2/((k + 1/2)π)（k ≥ 1），一直變小、正負交替。這就像交錯級數 1 − 1/2 + 1/3 − …（〈交錯級數判別〉），所以有理由相信它收斂。","直覺，不是證明：拱的面積不是剛好 2/((k + 1/2)π)，而且 t 停在拱的中間時也要處理。下面用分部積分給出嚴格的論證。"]},{"heading":"③ 嚴格證明：分部積分把 1/x 變成 1/x²","body":["令 u = 1/x、dv = sin x dx：∫₁ᵗ sin x/x dx = [−cos x/x]₁ᵗ − ∫₁ᵗ cos x/x² dx。","邊界項：|cos t/t| ≤ 1/t → 0，所以 → cos 1。剩下的積分：|cos x/x²| ≤ 1/x²，絕對收斂。兩項都有極限，所以 ∫₁^∞ sin x/x dx 收斂。關鍵是分部積分把衰減從 1/x 提升到 1/x²。"],"tex":["\\int_1^{t}\\frac{\\sin x}{x}\\,dx=\\cos 1-\\frac{\\cos t}{t}-\\int_1^{t}\\frac{\\cos x}{x^{2}}\\,dx"]},{"heading":"④ 但不是絕對收斂","body":["∫₁^∞ |sin x|/x dx 發散。所以 sin x/x 是條件收斂：∫ f 收斂、∫ |f| 發散，跟 Σ(−1)ⁿ/n 是同一類。","後果：正負面積互相抵銷才收斂，不能隨意拆成正部與負部分開算；值 π/2 在〈Dirichlet 積分〉裡算。"]},{"heading":"一般的 Dirichlet 判別法","body":["若 f 在 [a, ∞) 上單調遞減到 0、f′ 連續，而 G(t) = ∫ₐᵗ g 有界，則 ∫ₐ^∞ f g dx 收斂。證明就是上面的分部積分：∫ f g = [fG] − ∫ f′G，而 |f′G| ≤ M|f′| = −M f′ 可積。","例：∫₁^∞ sin x/xᵖ dx 對 p > 0 收斂；p > 1 時絕對收斂，0 < p ≤ 1 時條件收斂。"],"collapsible":true}],"workedExamples":[{"title":"分部積分證明收斂","prompt":"證明 ∫₁^∞ sin x/x dx 收斂。","steps":["u = 1/x、dv = sin x dx，du = −dx/x²、v = −cos x。","∫₁ᵗ sin x/x dx = [−cos x/x]₁ᵗ − ∫₁ᵗ cos x/x² dx = cos 1 − cos t/t − ∫₁ᵗ cos x/x² dx。","t → ∞：|cos t/t| ≤ 1/t → 0。|cos x/x²| ≤ 1/x² 而 ∫₁^∞ dx/x² 收斂，所以 ∫₁^∞ cos x/x² dx 絕對收斂。","右邊每一項都有極限，所以左邊收斂，而且 ∫₁^∞ sin x/x dx = cos 1 − ∫₁^∞ cos x/x² dx。"],"answer":"收斂"},{"title":"絕對值版本發散","prompt":"證明 ∫_π^∞ |sin x|/x dx 發散。","steps":["在 [kπ, (k + 1)π] 上，x ≤ (k + 1)π，所以 |sin x|/x ≥ |sin x|/((k + 1)π)。","|sin x| 在任何一個長度 π 的區間 [kπ, (k + 1)π] 上積分都是 2，所以這一段的積分 ≥ 2/((k + 1)π)。","把 k = 1 到 N 加起來：∫_π^{(N+1)π} |sin x|/x dx ≥ (2/π)(1/2 + 1/3 + … + 1/(N + 1))。","右邊是調和級數的部分和，N → ∞ 時 → ∞，所以積分發散。"],"answer":"發散"},{"title":"被積函數不趨近 0 也能收斂","prompt":"判斷 ∫₀^∞ sin(x²) dx","steps":["x → ∞ 時 sin(x²) 在 −1 與 1 之間振盪，不 → 0。但振盪越來越快，正負抵銷得越來越好。","令 u = x²，x = √u，dx = du/(2√u)：積分變成 ∫₀^∞ sin u/(2√u) du。","0 端：sin u/(2√u) ~ √u/2 → 0，沒有問題。∞ 端：1/(2√u) 遞減到 0、∫ sin u 有界，跟範例 1 一樣分部積分（或用 Dirichlet 判別法），收斂。","所以原積分收斂（它的值是 √(π/8)，要用複變或 Gamma 函數才算得出來）。"],"answer":"收斂（條件收斂）","note":"這是瑕積分跟級數不同的地方：級數收斂一定要 aₙ → 0，瑕積分收斂不需要 f(x) → 0。"}],"pitfalls":["用 |sin x/x| ≤ 1/x 推出「收斂」或「發散」：被發散的壓住，沒有結論。","以為收斂一定絕對收斂，把正負部分開積分。","分部積分後忘了證明邊界項的極限存在。","以為被積函數不 → 0 就一定發散（sin(x²) 是反例）。"],"checks":[{"ask":"∫₁^∞ sin x/x dx 是：","options":[{"label":"條件收斂","correct":true},{"label":"絕對收斂，因為 |sin x/x| ≤ 1/x","why":"∫₁^∞ dx/x 發散，被它壓住推不出收斂；而且 ∫ |sin x|/x 確實發散。"},{"label":"發散，因為 sin x 沒有極限","why":"正負的拱互相抵銷，分部積分證明了它收斂。"}]},{"ask":"「∫ f 條件收斂」的意思是？","options":[{"label":"∫ f 收斂，但 ∫ |f| 發散","correct":true},{"label":"∫ |f| 收斂，但 ∫ f 發散","why":"不可能發生：絕對收斂一定收斂。"},{"label":"在某些參數條件下才收斂","why":"「條件」不是指參數，是指收斂要靠正負抵銷，拿掉符號就發散。"}]},{"ask":"∫₁^∞ cos x/x² dx 是：","options":[{"label":"絕對收斂","correct":true},{"label":"條件收斂","why":"|cos x/x²| ≤ 1/x²，而 ∫₁^∞ dx/x² 收斂，所以連絕對值都收斂。"},{"label":"發散","why":"被 1/x² 壓住，面積有限。"}]},{"ask":"∫₁^∞ sin x/x^{1/2} dx 是：","options":[{"label":"條件收斂","correct":true},{"label":"絕對收斂","why":"x ≥ 1 時 |sin x|/√x ≥ |sin x|/x，而後者的積分已經發散。"},{"label":"發散","why":"1/√x 遞減到 0，跟 sin x/x 一樣分部積分就收斂；p > 0 都收斂。"}]}],"practice":[{"id":"lb-cmp-002","core":true},{"id":"dm-int-001","challenge":true,"note":"挑戰：sin² x/x² 絕對收斂，分部積分後變成條件收斂的 ∫ sin 2x/x，再用 Dirichlet 積分的值。"}]},"reduction-formula":{"id":"reduction-formula","prerequisites":["integration-by-parts","ibp-cyclic","trig-integral-tan-sec","improper-singular"],"next":["wallis-integral"],"related":["gamma-definition"],"objectives":["把一整族積分 Iₙ 寫成 n 的函數，用分部積分（或恆等式）建立 Iₙ 與 Iₙ₋₁、Iₙ₋₂ 的關係。","從起點一路代回去求出 I₃、I₄，並且知道步長 2 時要準備兩個起點。","處理瑕積分的遞迴時，確認邊界項真的是 0。"],"concept":[{"heading":"① 不要每一題都重做一次分部積分","body":["∫₀¹ x³ eˣ dx 要分部積分三次，∫₀¹ x¹⁰ eˣ dx 要十次。其實每一次做的事都一樣：把 x 的次數降一。與其一次一次做，不如把 n 當成變數，做一次分部積分就得到一條「降一階」的規則，之後只要代數字。"]},{"heading":"② 建立遞迴：分部積分讓次數下降","body":["令 Jₙ = ∫₀¹ xⁿ eˣ dx（n ≥ 1）。取 u = xⁿ（微分後次數降一）、dv = eˣ dx：","Jₙ = [xⁿ eˣ]₀¹ − n ∫₀¹ x^{n−1} eˣ dx = e − n Jₙ₋₁。","再算起點 J₀ = ∫₀¹ eˣ dx = e − 1，就能一路往上推。u 的選擇原則跟〈分部積分推導〉一樣：讓「麻煩的那一塊」微分之後變簡單。"],"tex":["J_n=e-n\\,J_{n-1},\\qquad J_0=e-1"]},{"heading":"③ 不一定要分部積分：恆等式也能降次","body":["Tₙ = ∫₀^{π/4} tanⁿ x dx：把 tan² x 換成 sec² x − 1，tanⁿ x = tan^{n−2} x sec² x − tan^{n−2} x。前一項令 u = tan x、du = sec² x dx，積出 1/(n − 1)。所以 Tₙ = 1/(n − 1) − Tₙ₋₂（n ≥ 2）。","步長是 2：偶數一路降到 T₀ = π/4，奇數降到 T₁ = (ln 2)/2。兩個起點都要先算好。"]},{"heading":"④ 瑕積分的遞迴：邊界項要用極限確認","body":["Lₙ = ∫₀¹ (ln x)ⁿ dx 在 x = 0 是瑕點。取 u = (ln x)ⁿ、dv = dx：Lₙ = [x (ln x)ⁿ]₀¹ − n Lₙ₋₁。邊界項在 x = 1 是 0，在 x → 0⁺ 是 lim x (ln x)ⁿ = 0（對數 ≪ 冪次），所以 Lₙ = −n Lₙ₋₁，L₀ = 1，得 Lₙ = (−1)ⁿ n!。","同樣的想法用在 ∫₀^∞ xⁿ e^{−x} dx 就得到〈Gamma 函數：定義與遞迴〉的 Γ(n + 1) = nΓ(n)。"]}],"workedExamples":[{"title":"∫₀¹ x³ eˣ dx","prompt":"用 Jₙ = e − n Jₙ₋₁ 求 J₃ = ∫₀¹ x³ eˣ dx。","steps":["起點 J₀ = e − 1。","J₁ = e − 1 · J₀ = e − (e − 1) = 1。","J₂ = e − 2J₁ = e − 2。","J₃ = e − 3J₂ = e − 3(e − 2) = 6 − 2e ≈ 0.5634。"],"answer":"6 − 2e"},{"title":"瑕積分的遞迴","prompt":"∫₀¹ (ln x)³ dx","problemId":"world-079","steps":["Lₙ = −n Lₙ₋₁（邊界項 x (ln x)ⁿ 在 0⁺ 的極限是 0），L₀ = ∫₀¹ 1 dx = 1。","L₁ = −1，L₂ = −2 · (−1) = 2，L₃ = −3 · 2 = −6。","符號檢查：0 < x < 1 時 ln x < 0，(ln x)³ < 0，積分是負的，合理。"],"answer":"−6"},{"title":"步長 2 的遞迴","prompt":"∫₀^{π/4} tan⁴ x dx","steps":["Tₙ = 1/(n − 1) − Tₙ₋₂，n = 4 是偶數，要用 T₀ = ∫₀^{π/4} 1 dx = π/4。","T₂ = 1/1 − T₀ = 1 − π/4。","T₄ = 1/3 − T₂ = 1/3 − 1 + π/4 = π/4 − 2/3 ≈ 0.1187。","符號檢查：被積函數非負，答案是正的。"],"answer":"π/4 − 2/3"}],"pitfalls":["u 選錯（u = eˣ），次數不降反升。","步長 2 的遞迴只準備一個起點，奇數項接不下去。","遞迴的係數符號弄錯：Jₙ = e − nJₙ₋₁ 是減號，連續代入時正負交錯。","瑕積分的邊界項直接寫 0，沒有用極限確認。"],"checks":[{"ask":"要替 ∫ xⁿ eˣ dx 建立降次的遞迴，u 應該選？","options":[{"label":"u = xⁿ","correct":true},{"label":"u = eˣ","why":"那樣 dv = xⁿ dx，v = x^{n+1}/(n + 1)，次數反而升高。"},{"label":"u = xⁿ eˣ","why":"dv 只剩 dx，v = x，積分變得更複雜，次數也沒有下降。"}]},{"ask":"Lₙ = ∫₀¹ (ln x)ⁿ dx 滿足 Lₙ = −n Lₙ₋₁，L₀ = 1。L₂ 是？","options":[{"label":"2","correct":true},{"label":"−2","why":"L₁ = −1，L₂ = −2 · (−1) = 2，負負得正。(ln x)² ≥ 0，積分也該是正的。"},{"label":"1/2","why":"遞迴是乘以 −n，不是除以 n。"}]},{"ask":"Tₙ = ∫₀^{π/4} tanⁿ x dx 滿足 Tₙ + Tₙ₋₂ = 1/(n − 1)。T₂ 是？","options":[{"label":"1 − π/4","correct":true},{"label":"π/4 − 1","why":"這是負數，但 tan² x ≥ 0，積分不可能是負的。T₂ = 1 − T₀ = 1 − π/4。"},{"label":"1","why":"漏了減掉 T₀ = π/4。"}]},{"ask":"用 Tₙ 的遞迴求 T₅，需要先知道哪一個？","options":[{"label":"T₁ = (ln 2)/2","correct":true},{"label":"T₀ = π/4","why":"步長是 2，奇數項 5 → 3 → 1，會停在 T₁，不會碰到 T₀。"},{"label":"T₄","why":"遞迴連的是 Tₙ 與 Tₙ₋₂，T₅ 跟 T₃ 有關，跟 T₄ 無關。"}]}],"practice":[{"id":"lec-08-q4b","core":true},{"id":"lec-08-q4d","core":true},{"id":"burst-rec-010","core":true},{"id":"burst-rec-001","core":true},{"id":"rel-boss-017","core":true},{"id":"world-079","core":true},{"id":"burst-rec-002"},{"id":"burst-rec-007"},{"id":"burst-rec-008"},{"id":"burst-boss-int-011"},{"id":"dm-seq-009","challenge":true,"note":"挑戰：建立 Tₙ + Tₙ₋₂ = 1/(n − 1)，再用 Tₙ 遞減夾出 n Tₙ → 1/2。"}]},"wallis-integral":{"id":"wallis-integral","prerequisites":["reduction-formula","trig-integral-sin-cos","u-sub-definite"],"next":["wallis-product"],"related":["wallis-beta","ibp-cyclic"],"objectives":["推出 Wₙ = ∫₀^{π/2} sinⁿ x dx 的遞迴 Wₙ = ((n − 1)/n) Wₙ₋₂，以及 W₀ = π/2、W₁ = 1。","看 n 的奇偶直接寫出值：偶數最後乘 π/2，奇數最後乘 1。","用對稱性處理 cosⁿ、[0, π] 的區間，以及 sinᵐ cosⁿ（偶數次方）的乘積。"],"concept":[{"heading":"① 遞迴從哪裡來","body":["把 sinⁿ x 拆成 sin^{n−1} x · sin x，令 u = sin^{n−1} x、dv = sin x dx，du = (n − 1) sin^{n−2} x cos x dx、v = −cos x。","邊界項 [−sin^{n−1} x cos x]₀^{π/2}：x = π/2 時 cos = 0，x = 0 時 sin = 0（n ≥ 2），所以是 0。剩下 (n − 1)∫₀^{π/2} sin^{n−2} x cos² x dx。","把 cos² x 換成 1 − sin² x：Wₙ = (n − 1)(Wₙ₋₂ − Wₙ)。Wₙ 出現在兩邊，移項（〈重複分部與循環積分〉的手法）得到遞迴。"],"tex":["W_n=\\frac{n-1}{n}\\,W_{n-2},\\qquad W_0=\\frac{\\pi}{2},\\quad W_1=1"]},{"heading":"② 一路降下去：奇偶決定有沒有 π","body":["偶數：W₆ = (5/6)(3/4)(1/2) · π/2 = 5π/32。奇數：W₇ = (6/7)(4/5)(2/3) · 1 = 16/35。","規律：分子是比 n 小的、跟 n − 1 同奇偶的數，分母是跟 n 同奇偶的數。偶數時最後乘 W₀ = π/2，奇數時最後乘 W₁ = 1，所以奇數次方的答案沒有 π。"]},{"heading":"③ 對稱性：cos、[0, π]","body":["令 x = π/2 − t：sin 變 cos，區間 [0, π/2] 不變，所以 ∫₀^{π/2} cosⁿ x dx = Wₙ。","[0, π] 上：sinⁿ 對 x = π/2 對稱，∫₀^π sinⁿ x dx = 2Wₙ。cosⁿ 在 n 偶數時也是 2Wₙ；n 奇數時 cos(π − x) = −cos x，前後兩半抵銷，積分是 0。"]},{"heading":"④ 乘積：偶數次方的 cos 換成 sin","body":["∫₀^{π/2} sin⁴ x cos² x dx：cos² x = 1 − sin² x，變成 W₄ − W₆。一般的 sinᵐ cosⁿ（不一定是偶數，甚至不是整數）在〈Wallis 與 Beta〉用 Beta 函數一次處理。","另一個之後會用到的事實：0 ≤ sin x ≤ 1，所以 sin^{n+1} x ≤ sinⁿ x，Wₙ 隨 n 遞減。"]}],"workedExamples":[{"title":"偶數次方","prompt":"∫₀^{π/2} sin⁶ x dx","steps":["n = 6 偶數，降到 W₀ = π/2。","W₆ = (5/6) W₄ = (5/6)(3/4) W₂ = (5/6)(3/4)(1/2) W₀。","(5 · 3 · 1)/(6 · 4 · 2) = 15/48 = 5/16，乘 π/2 得 5π/32。"],"answer":"5π/32"},{"title":"區間換成 [0, π]","prompt":"∫₀^π cos⁴ x dx","problemId":"world-010","steps":["n = 4 偶數，cos⁴ 對 x = π/2 對稱（cos(π − x)⁴ = cos⁴ x），所以等於 2 ∫₀^{π/2} cos⁴ x dx = 2W₄。","W₄ = (3/4)(1/2)(π/2) = 3π/16。","答案 2 · 3π/16 = 3π/8。"],"answer":"3π/8","note":"若是 cos³，前後兩半正負相反，∫₀^π cos³ x dx = 0。"},{"title":"乘積化成兩個 Wallis","prompt":"∫₀^{π/2} sin⁴ x cos² x dx","problemId":"rel-hard-int-007","steps":["cos² x = 1 − sin² x，被積函數 = sin⁴ x − sin⁶ x。","積分 = W₄ − W₆ = 3π/16 − 5π/32。","通分：6π/32 − 5π/32 = π/32。"],"answer":"π/32"}],"pitfalls":["奇數次方也乘了 π/2（奇數的起點是 W₁ = 1）。","遞迴寫成 Wₙ = (n/(n − 1)) Wₙ₋₂，分子分母顛倒；檢查：Wₙ 應該越來越小。","[0, π] 上的 cosⁿ 不分奇偶都乘 2；奇數次方是 0。","把 Wallis 用在 [0, π/2] 以外的區間，沒有先用對稱性換回來。"],"checks":[{"ask":"∫₀^{π/2} sin⁵ x dx 是？","options":[{"label":"8/15","correct":true},{"label":"8π/15","why":"5 是奇數，遞迴停在 W₁ = 1，答案沒有 π。"},{"label":"4/5","why":"只乘了第一個因子；還要乘 2/3：(4/5)(2/3) = 8/15。"}]},{"ask":"∫₀^{π/2} cos⁴ x dx 是？","options":[{"label":"3π/16","correct":true},{"label":"3π/8","why":"那是 [0, π] 上的值，多乘了 2。"},{"label":"3/8","why":"偶數次方最後要乘 W₀ = π/2：(3/4)(1/2)(π/2) = 3π/16。"}]},{"ask":"∫₀^π cos³ x dx 是？","options":[{"label":"0","correct":true},{"label":"4/3","why":"那是 2W₃。但 cos(π − x) = −cos x，奇數次方前後兩半正負抵銷。"},{"label":"2/3","why":"W₃ = 2/3 是 [0, π/2] 上的值；在 [0, π] 上後半段是負的，抵銷成 0。"}]},{"ask":"為什麼 ∫₀^{π/2} cosⁿ x dx = ∫₀^{π/2} sinⁿ x dx？","options":[{"label":"換元 x = π/2 − t，sin 變 cos，區間不變","correct":true},{"label":"因為 sin x 和 cos x 在 [0, π/2] 上相等","why":"兩者只在 π/4 相等；是整段積分相等，不是函數相等。"},{"label":"因為兩者週期都是 2π","why":"週期相同不夠；關鍵是 [0, π/2] 這個區間在 x ↦ π/2 − x 下對調了 sin 與 cos。"}]}],"practice":[{"id":"lec-07-q2a","core":true},{"id":"lec-07-q2c","core":true},{"id":"mob-wallis-003","core":true},{"id":"mob-wallis-004","core":true},{"id":"mob-wallis-006","core":true},{"id":"world-010","core":true},{"id":"mob-wallis-007","core":true},{"id":"rel-hard-int-005"},{"id":"burst-int-015"},{"id":"burst-int-020"},{"id":"rel-hard-int-007"},{"id":"burst-rec-004"},{"id":"burst-int-013","challenge":true,"note":"挑戰：先用 x ↦ π − x 把 x 換成 π/2，再用 [0, π] 上的 Wallis。"}]},"wallis-product":{"id":"wallis-product","prerequisites":["wallis-integral","squeeze-theorem","asymptotic-equivalence"],"next":["gamma-definition"],"related":["stirling"],"objectives":["寫得出 π/2 = (2/1)(2/3)(4/3)(4/5)(6/5)(6/7)⋯，並認得它的另一個樣子 Π(1 − 1/(4k²)) = 2/π。","用 Wₙ 遞減與夾擠定理，從 Wallis 積分推出 Wallis 乘積。","用 nWₙWₙ₋₁ = π/2 推出 C(2n, n) ~ 4ⁿ/√(πn)，不需要 Stirling。"],"concept":[{"heading":"① 一個用整數乘出 π 的公式","body":["把偶數平方除以左右兩個奇數，一直乘下去：(2·2)/(1·3) · (4·4)/(3·5) · (6·6)/(5·7) ⋯ 會收斂到 π/2。每個因子 (2k)²/((2k − 1)(2k + 1)) = 4k²/(4k² − 1) 都比 1 大一點點，乘起來剛好停在 π/2。","等價的寫法：取倒數，Π_{k=1}^∞ (1 − 1/(4k²)) = 2/π。"],"tex":["\\frac{\\pi}{2}=\\prod_{k=1}^{\\infty}\\frac{(2k)^2}{(2k-1)(2k+1)}"]},{"heading":"② 證明的關鍵：Wₙ 遞減","body":["上一課：Wₙ = ∫₀^{π/2} sinⁿ x dx 隨 n 遞減，所以 W_{2m+1} ≤ W_{2m} ≤ W_{2m−1}。","全部除以 W_{2m+1}：1 ≤ W_{2m}/W_{2m+1} ≤ W_{2m−1}/W_{2m+1} = (2m + 1)/(2m)（遞迴 W_{2m+1} = (2m/(2m + 1)) W_{2m−1}）。右邊 → 1，由夾擠定理 W_{2m}/W_{2m+1} → 1。","最後把兩個 Wallis 的值代進去：W_{2m}/W_{2m+1} = (π/2) · [1·3·3·5⋯(2m − 1)(2m + 1)]/[2·2·4·4⋯(2m)(2m)]，它 → 1，也就是 π/2 等於那個乘積的極限。"]},{"heading":"③ 一個漂亮的不變量：nWₙWₙ₋₁ = π/2","body":["由 Wₙ = ((n − 1)/n)Wₙ₋₂，兩邊乘 nWₙ₋₁：nWₙWₙ₋₁ = (n − 1)Wₙ₋₁Wₙ₋₂。這個量不隨 n 改變，等於 1 · W₁W₀ = π/2。","配合 Wₙ ~ Wₙ₋₁（上面證的），得到 Wₙ² ~ π/(2n)，也就是 Wₙ ~ √(π/(2n))。"]},{"heading":"④ 收斂得很慢，但很有用","body":["部分乘積的相對誤差大約是 1/(4m)，拿來算 π 並不實際。它真正的用途是當橋樑：中央二項式係數、Stirling 公式裡的 √(2π)、Γ(1/2) = √π，都靠它定出常數。"]}],"workedExamples":[{"title":"另一種寫法","prompt":"Π_{k=1}^∞ (1 − 1/(4k²))","problemId":"putnam-006","steps":["1 − 1/(4k²) = (4k² − 1)/(4k²) = (2k − 1)(2k + 1)/(2k)²，正好是 Wallis 因子的倒數。","部分乘積互為倒數，Wallis 乘積 → π/2，所以這個乘積 → 2/π。","數值檢查：取對數變成級數 Σ ln(1 − 1/(4k²))，它收斂到 ln(2/π)。"],"answer":"2/π"},{"title":"部分乘積有多準","prompt":"算 P₁、P₂ 與 P₁₀，跟 π/2 ≈ 1.5708 比較。","steps":["P₁ = 4/3 ≈ 1.3333。","P₂ = (4/3)(16/15) = 64/45 ≈ 1.4222。","P₁₀ ≈ 1.5339，還差約 2.4%；相對誤差大約 1/(4m)，m = 10 時是 1/40。"],"answer":"P₁₀ ≈ 1.5339"},{"title":"不用 Stirling 的中央二項式係數","prompt":"用 Wallis 證明 C(2n, n) ~ 4ⁿ/√(πn)。","problemId":"dm-seq-004","steps":["W_{2n} = ((2n − 1)/(2n))((2n − 3)/(2n − 2))⋯(1/2) · π/2。分子分母同乘 2·4⋯(2n)：這個分數等於 (2n)!/(2ⁿ n!)² = C(2n, n)/4ⁿ。所以 C(2n, n)/4ⁿ = (2/π) W_{2n}。","由不變量 2n W_{2n} W_{2n−1} = π/2，以及 W_{2n} ~ W_{2n−1}：W_{2n}² ~ π/(4n)，W_{2n} ~ (1/2)√(π/n)。","代回：C(2n, n)/4ⁿ ~ (2/π)(1/2)√(π/n) = 1/√(πn)。","所以 √n · C(2n, n)/4ⁿ → 1/√π，跟〈Stirling 公式〉的結果一致。"],"answer":"C(2n, n) ~ 4ⁿ/√(πn)"}],"pitfalls":["記成 π/4 或 2/π：(2/1)(2/3)(4/3)⋯ 的值是 π/2，倒數形式 Π(1 − 1/(4k²)) 才是 2/π。","夾擠時把不等式方向弄反：次方越高，Wₙ 越小。","以為部分乘積收斂得很快；誤差大約 1/(4m)。","因子寫成 (2k)²/((2k − 1)²)，少了 (2k + 1)。"],"checks":[{"ask":"(2/1)(2/3)(4/3)(4/5)(6/5)(6/7)⋯ 的值是？","options":[{"label":"π/2","correct":true},{"label":"π/4","why":"π/4 是 Leibniz 級數 1 − 1/3 + 1/5 − ⋯ 的值，不是這個乘積。"},{"label":"2/π","why":"那是倒數 Π(1 − 1/(4k²)) 的值；每個因子都大於 1，乘積應該大於 1。"}]},{"ask":"證明 W_{2m}/W_{2m+1} → 1 用到的關鍵事實是？","options":[{"label":"Wₙ 隨 n 遞減，再配上 W_{2m−1}/W_{2m+1} = (2m + 1)/(2m) → 1","correct":true},{"label":"Wₙ 隨 n 遞增","why":"方向反了：0 ≤ sin x ≤ 1，次方越高越小，Wₙ 遞減。"},{"label":"sin x 的 Taylor 展開","why":"證明只用了遞迴、單調性與夾擠定理，沒有用到展開。"}]},{"ask":"Π_{k=1}^∞ (1 − 1/(4k²)) 是？","options":[{"label":"2/π","correct":true},{"label":"π/2","why":"每個因子都小於 1，乘積小於 1；π/2 是它的倒數。"},{"label":"1/2","why":"1/2 是 Π_{k≥2} (1 − 1/k²) 的值（望遠鏡乘積），分母是 k² 不是 4k²。"}]},{"ask":"nWₙWₙ₋₁ 對所有 n ≥ 1 都等於？","options":[{"label":"π/2","correct":true},{"label":"1","why":"n = 1 時是 1 · W₁ · W₀ = 1 · 1 · π/2 = π/2。"},{"label":"隨 n 遞減到 0","why":"遞迴 Wₙ = ((n − 1)/n)Wₙ₋₂ 正好讓這個量不變：nWₙWₙ₋₁ = (n − 1)Wₙ₋₁Wₙ₋₂。"}]}],"practice":[{"id":"putnam-006","core":true},{"id":"burst-rec-005","core":true},{"id":"burst-rec-006","core":true},{"id":"dm-seq-004","core":true},{"id":"world-074","challenge":true,"note":"挑戰：倒數形式，答案是 √π。"}]},"gamma-definition":{"id":"gamma-definition","prerequisites":["integration-by-parts","u-sub-basic","u-sub-definite","improper-infinite","improper-singular","improper-p-test"],"next":["gamma-recurrence-apps","gamma-half"],"related":[],"objectives":["寫得出 Γ(s) 的積分定義，說得出這個積分什麼時候收斂。","用分部積分推出 Γ(s + 1) = sΓ(s)，以及 Γ(n + 1) = n!。","把 ∫₀^∞ xᵏ e^{−x} dx 這類積分直接讀成 Gamma 函數的值。"],"concept":[{"heading":"① 為什麼要學它：一整族積分其實是同一個函數","body":["前面分部積分時會反覆遇到 ∫₀^∞ x e^{−x} dx、∫₀^∞ x² e^{−x} dx、∫₀^∞ x³ e^{−x} dx……每一個都要分部積分好幾次。","Gamma 函數把這一整族積分統一成一個函數。之後看到這種形狀，就不用再算，直接讀值。而它在整數點剛好是階乘，等於把 n! 延伸成一條平滑曲線。"],"tex":["\\Gamma(s)=\\int_0^{\\infty}x^{s-1}e^{-x}\\,dx"]},{"heading":"② 這個積分什麼時候收斂","body":["這是兩端都要檢查的瑕積分：","x → ∞：e^{−x} 衰減得比任何 x 的次方增長都快，尾巴收斂。","x → 0⁺：e^{−x} → 1，被積函數像 x^{s−1}。由 p 判別，∫₀¹ x^{s−1} dx 收斂若且唯若 s − 1 > −1，也就是 s > 0。","所以：此積分表示式在 s > 0 時收斂。"]},{"heading":"預告：s ≤ 0 呢？","body":["積分在 s ≤ 0 發散，但 Gamma 函數可以用別的方法延伸到負的非整數（例如用遞迴 Γ(s) = Γ(s + 1)/s 往左推）。這叫解析延拓。在 0、−1、−2、……仍然沒有定義。"],"collapsible":true},{"heading":"③ 第一個值：Γ(1) = 1","body":["s = 1 時 x⁰ = 1，Γ(1) = ∫₀^∞ e^{−x} dx = 1。"]},{"heading":"④ 遞迴：Γ(s + 1) = sΓ(s)","body":["對 Γ(s + 1) = ∫₀^∞ xˢ e^{−x} dx 做分部積分，令 u = xˢ、dv = e^{−x} dx。","邊界項：x → ∞ 時 e^{−x} 贏過 xˢ，趨近 0；x = 0 時 xˢ = 0（s > 0）。所以邊界項是 0，剩下 Γ(s + 1) = sΓ(s)。"],"tex":["\\Gamma(s+1)=\\Bigl[-x^{s}e^{-x}\\Bigr]_0^{\\infty}+s\\int_0^{\\infty}x^{s-1}e^{-x}\\,dx=s\\,\\Gamma(s)"]},{"heading":"⑤ 在整數點就是階乘","body":["從 Γ(1) = 1 開始：Γ(2) = 1，Γ(3) = 2，Γ(4) = 6，……一般地 Γ(n + 1) = n!。","注意差一：Γ(n) = (n − 1)!，不是 n!。"]},{"heading":"⑥ 讀積分：看到 xᵏ e^{−x} 就是 Gamma","body":["∫₀^∞ xᵏ e^{−x} dx = Γ(k + 1)。指數裡有常數 a > 0 時，換元 u = ax，得到下面的公式。"],"tex":["\\int_0^{\\infty}x^{k}e^{-ax}\\,dx=\\frac{\\Gamma(k+1)}{a^{k+1}}"]}],"workedExamples":[{"title":"直接讀成 Gamma","prompt":"∫₀^∞ x² e^{−x} dx","problemId":"mob-gamma-006","steps":["形狀是 xᵏ e^{−x}，k = 2，所以是 Γ(3)。","Γ(3) = 2! = 2。"],"answer":"2","note":"分部積分兩次也會得到 2，但要寫半頁。"},{"title":"整數點的值","prompt":"Γ(6) 與 Γ(4)","steps":["Γ(n + 1) = n!，所以 Γ(6) = 5! = 120。","Γ(4) = 3! = 6。"],"answer":"Γ(6) = 120，Γ(4) = 6","note":"不要寫成 Γ(6) = 6! = 720，那是差一的錯。"},{"title":"指數裡有常數","prompt":"∫₀^∞ x⁴ e^{−3x} dx","problemId":"burst-int-001","steps":["令 u = 3x，x = u/3，dx = du/3。x⁴ = u⁴/3⁴。","積分變成 (1/3⁵) ∫₀^∞ u⁴ e^{−u} du = Γ(5)/3⁵。","Γ(5) = 4! = 24，3⁵ = 243，答案是 24/243 = 8/81。"],"answer":"8/81"},{"title":"先換元才看得出來","prompt":"∫₀^∞ x³ e^{−x²} dx","problemId":"depth-int-026","steps":["指數是 −x²，不是標準形狀。令 u = x²，du = 2x dx。","把 x³ dx 拆成 x² · x dx = u · (du/2)。","積分變成 (1/2) ∫₀^∞ u e^{−u} du = (1/2) Γ(2) = 1/2。"],"answer":"1/2"}],"pitfalls":["差一：Γ(n) 寫成 n!。","換元時漏了 du 的係數，或 a^{k+1} 寫成 aᵏ。","以為 Γ(0) = 0! = 1。Γ(0) 的積分在 x → 0 發散，Γ 在 0 沒有定義。"],"figures":[{"caption":"s 是整數時，面積是 (s − 1)!","after":0,"widget":{"type":"family","f":"x^(s-1)*exp(-x)","param":"s","range":[1,4],"step":0.05,"value":3,"area":[0,60],"window":[0,12,0,1.5]}}],"checks":[{"ask":"Γ(5) 是多少？","options":[{"label":"24","correct":true},{"label":"120","why":"那是 5! = Γ(6)。Γ(5) = 4! = 24。"},{"label":"5","why":"Γ 不是把參數直接拿出來，是階乘。"}]},{"ask":"∫₀^∞ x³ e^{−x} dx 是？","options":[{"label":"6","correct":true},{"label":"24","why":"x³ 對應 Γ(4) = 3! = 6，不是 4!。"},{"label":"3","why":"那只是指數，還要做階乘。"}]},{"ask":"積分 ∫₀^∞ x^{s−1} e^{−x} dx 為什麼要 s > 0 才收斂？","options":[{"label":"x → 0 時被積函數像 x^{s−1}，s ≤ 0 時那一端發散","correct":true},{"label":"因為 e^{−x} 在 s ≤ 0 時不收斂","why":"e^{−x} 跟 s 無關，問題出在 x → 0 那一端。"},{"label":"因為負數沒有階乘","why":"這是結果不是原因；限制來自積分收斂。"}]},{"ask":"Γ(s + 1) = sΓ(s) 是用什麼推出來的？","options":[{"label":"分部積分，而且邊界項是 0","correct":true},{"label":"換元 u = x + 1","why":"遞迴來自分部積分，不是平移。"},{"label":"定義直接代入","why":"定義裡沒有 s 這個係數，要靠分部積分「生出來」。"}]}],"practice":[{"id":"mob-gamma-001","core":true},{"id":"mob-gamma-008","core":true},{"id":"mob-gamma-005","core":true},{"id":"mob-gamma-006","core":true},{"id":"depth-int-026","core":true},{"id":"int-040","core":true},{"id":"rel-adv-011"},{"id":"world-079","challenge":true,"note":"挑戰：令 x = e^{−t}，看出是 −Γ(4)。"}]},"gamma-recurrence-apps":{"id":"gamma-recurrence-apps","prerequisites":["gamma-definition","u-sub-definite","improper-singular"],"next":["gamma-half"],"related":["reduction-formula","holomorphic"],"objectives":["用 Γ(s + 1) = sΓ(s) 處理非整數：把 Γ(s + n) 寫成 s(s + 1)⋯(s + n − 1)Γ(s)，算 Gamma 的比值。","用 x = e^{−t} 把 ∫₀¹ xᵐ (ln x)ⁿ dx 變成 Gamma 積分，直接得到 (−1)ⁿ n!/(m + 1)^{n+1}。","用 Γ(s) = Γ(s + 1)/s 把 Gamma 往左推到負的非整數，並判斷正負號。"],"concept":[{"heading":"① 遞迴不只用在整數","body":["〈Gamma 函數：定義與遞迴〉的 Γ(s + 1) = sΓ(s) 對所有 s > 0 都成立，不只整數。連用 n 次：","所以 Gamma 的比值永遠可以化成一串乘法：Γ(7/2)/Γ(3/2) = (5/2)(3/2) = 15/4，不需要知道 Γ(3/2) 本身是多少。"],"tex":["\\Gamma(s+n)=(s+n-1)(s+n-2)\\cdots(s+1)\\,s\\,\\Gamma(s)"]},{"heading":"② 對數的次方：令 x = e^{−t}","body":["∫₀¹ xᵐ (ln x)ⁿ dx 看起來跟 Gamma 無關。令 x = e^{−t}：ln x = −t，dx = −e^{−t} dt，x 從 0 到 1 對應 t 從 ∞ 到 0。","xᵐ dx = −e^{−(m+1)t} dt，把上下限翻回來吃掉負號，積分變成 (−1)ⁿ ∫₀^∞ tⁿ e^{−(m+1)t} dt = (−1)ⁿ Γ(n + 1)/(m + 1)^{n+1}（m > −1）。","這等於把〈遞迴公式〉裡 n 次分部積分一口氣做完。"],"tex":["\\int_0^1 x^{m}(\\ln x)^{n}\\,dx=\\frac{(-1)^{n}\\,n!}{(m+1)^{n+1}}\\qquad(m>-1)"]},{"heading":"③ 往左推：負的非整數","body":["積分定義只在 s > 0 收斂，但遞迴倒過來寫 Γ(s) = Γ(s + 1)/s 的右邊在 −1 < s < 0 時有意義（s + 1 > 0）。用它定義 Γ(s)，再一步一步推到 (−2, −1)、(−3, −2)……","正負號：−1 < s < 0 時 Γ(s + 1) > 0、s < 0，所以 Γ(s) < 0；再往左一段又變正，交替變號。s = 0, −1, −2, … 時要除以 0，Γ 在這些點沒有定義（函數值往 ±∞ 衝）。"]},{"heading":"為什麼往左推是「唯一合理」的延伸","body":["這個延伸跟積分定義在 s > 0 吻合，而且保持 Γ(s + 1) = sΓ(s) 對所有非整數的 s 成立。複變裡可以證明：在去掉 0, −1, −2, … 的複平面上，只有一個全純函數（〈全純函數〉）跟 s > 0 的 Gamma 一致，所以這個延伸是唯一的。這叫解析延拓。"],"collapsible":true}],"workedExamples":[{"title":"非整數的比值","prompt":"Γ(7/2)/Γ(3/2)","steps":["Γ(7/2) = (5/2)Γ(5/2) = (5/2)(3/2)Γ(3/2)。","Γ(3/2) 約掉：比值 = (5/2)(3/2) = 15/4。","換成積分的語言：∫₀^∞ x^{5/2} e^{−x} dx 是 ∫₀^∞ x^{1/2} e^{−x} dx 的 15/4 倍。"],"answer":"15/4"},{"title":"對數次方變 Gamma","prompt":"∫₀¹ x³ (ln x)² dx","problemId":"rel-hard-int-004","steps":["令 x = e^{−t}：x³ = e^{−3t}，(ln x)² = t²，dx = −e^{−t} dt，上下限 x: 0 → 1 變成 t: ∞ → 0。","積分 = ∫_∞^0 e^{−3t} t² (−e^{−t}) dt = ∫₀^∞ t² e^{−4t} dt。","這是 Γ(3)/4³ = 2/64 = 1/32（指數有常數 4：用〈Gamma 函數：定義與遞迴〉的 ∫₀^∞ xᵏ e^{−ax} dx = Γ(k + 1)/a^{k+1}）。","符號檢查：被積函數 ≥ 0，答案正，合理。"],"answer":"1/32"},{"title":"用一個不知道值的 Gamma 表示另一個","prompt":"把 Γ(10/3) 寫成 Γ(1/3) 的倍數。","steps":["10/3 = 1/3 + 3，連用三次遞迴。","Γ(10/3) = (7/3)Γ(7/3) = (7/3)(4/3)Γ(4/3) = (7/3)(4/3)(1/3)Γ(1/3)。","(7 · 4 · 1)/(3 · 3 · 3) = 28/27，所以 Γ(10/3) = (28/27)Γ(1/3)。Γ(1/3) ≈ 2.6789 沒有簡單的閉式，但比值是精確的。"],"answer":"Γ(10/3) = (28/27)Γ(1/3)"}],"pitfalls":["遞迴往上推時乘錯數：Γ(9/2) = (7/2)Γ(7/2)，乘的是 s，不是 s + 1。","x = e^{−t} 換元時漏了 dx = −e^{−t} dt 帶來的那一個 e^{−t}，分母變成 mⁿ⁺¹ 而不是 (m + 1)^{n+1}。","忘了 (ln x)ⁿ 在 n 為奇數時是負的，答案少了負號。","以為 Γ 在負數全都沒有定義；只有 0、−1、−2、…… 沒有定義。"],"checks":[{"ask":"Γ(9/2)/Γ(5/2) 是？","options":[{"label":"35/4","correct":true},{"label":"63/4","why":"乘錯了：Γ(9/2) = (7/2)Γ(7/2)、Γ(7/2) = (5/2)Γ(5/2)，乘的是 7/2 和 5/2，不是 9/2 和 7/2。"},{"label":"2","why":"Gamma 的比值不是參數相減；要把遞迴的因子乘起來。"}]},{"ask":"∫₀¹ x (ln x)² dx 是？","options":[{"label":"1/4","correct":true},{"label":"1/8","why":"公式是 n!/(m + 1)^{n+1} = 2!/2³ = 2/8；漏了 2! = 2。"},{"label":"−1/4","why":"(ln x)² ≥ 0，積分是正的；負號只在 n 是奇數時出現。"}]},{"ask":"−1 < s < 0 時，Γ(s) 的正負是？","options":[{"label":"負的","correct":true},{"label":"正的","why":"Γ(s) = Γ(s + 1)/s，Γ(s + 1) > 0 但 s < 0，所以是負的。"},{"label":"沒有定義","why":"積分定義不收斂，但用 Γ(s) = Γ(s + 1)/s 可以定義；只有 0、−1、−2、…… 沒有定義。"}]},{"ask":"令 x = e^{−t}，∫₀¹ xᵐ (−ln x)ⁿ dx 變成？","options":[{"label":"∫₀^∞ tⁿ e^{−(m+1)t} dt","correct":true},{"label":"∫₀^∞ tⁿ e^{−mt} dt","why":"漏了 dx = −e^{−t} dt 裡的 e^{−t}，它讓指數多一個 1。"},{"label":"∫₀¹ tⁿ e^{−(m+1)t} dt","why":"x 從 0 到 1 時 t = −ln x 從 ∞ 到 0，區間變成 [0, ∞)。"}]}],"practice":[{"id":"burst-rec-007","core":true},{"id":"burst-int-004","core":true},{"id":"rel-hard-int-004","core":true},{"id":"burst-int-005","core":true},{"id":"burst-int-006","core":true},{"id":"burst-rec-002"},{"id":"burst-boss-int-012"},{"id":"burst-boss-int-013"},{"id":"burst-boss-param-006","challenge":true,"note":"挑戰：答案要寫成 n 的式子：−6/(n + 1)⁴。"}]},"gamma-half":{"id":"gamma-half","prerequisites":["gamma-recurrence-apps","polar-double-integral","improper-infinite","u-sub-definite"],"next":["gamma-half-integer"],"related":["gaussian-integral","beta-gamma-relation"],"objectives":["用換元 x = u² 把 Γ(1/2) 變成 2∫₀^∞ e^{−u²} du。","用「平方之後換極座標」算出 ∫₀^∞ e^{−u²} du = √π/2，並說得出多出來的 r 為什麼是關鍵。","用縮放算 ∫₀^∞ e^{−ax²} dx = (1/2)√(π/a)。"],"concept":[{"heading":"① 從 Gamma 到鐘形曲線","body":["Γ(1/2) = ∫₀^∞ x^{−1/2} e^{−x} dx。令 x = u²（u ≥ 0），dx = 2u du，x^{−1/2} = 1/u：","Γ(1/2) = ∫₀^∞ (1/u) e^{−u²} 2u du = 2∫₀^∞ e^{−u²} du。","問題變成鐘形曲線 e^{−u²} 底下的面積。e^{−u²} 有反導函數，但寫不成常見初等函數的有限組合，所以要換個方法。"]},{"heading":"② 一維算不動，就算它的平方","body":["令 I = ∫₀^∞ e^{−x²} dx。I² 是兩個一樣的積分相乘，可以寫成第一象限上的二重積分：I² = ∫₀^∞∫₀^∞ e^{−(x²+y²)} dx dy。","被積函數只跟 x² + y² = r² 有關，換極座標：第一象限是 0 ≤ θ ≤ π/2、0 ≤ r < ∞，面積元素 dx dy = r dr dθ（〈極座標二重積分〉）。","多出來的 r 是關鍵：∫ e^{−r²} r dr 用 u = r² 一行就積出來。"],"tex":["I^{2}=\\int_0^{\\pi/2}\\!\\!\\int_0^{\\infty}e^{-r^{2}}\\,r\\,dr\\,d\\theta=\\frac{\\pi}{2}\\cdot\\frac12=\\frac{\\pi}{4}"]},{"heading":"③ 結果","body":["I > 0，所以 I = √π/2，Γ(1/2) = 2I = √π。由對稱，∫_{−∞}^∞ e^{−x²} dx = √π。","一個 π 出現在沒有圓的積分裡，是因為平方之後的被積函數 e^{−(x²+y²)} 有旋轉對稱，圓是藏在裡面的。"]},{"heading":"這個計算為什麼嚴格","body":["I² = (∫₀^∞ e^{−x²} dx)² 寫成整個第一象限的二重積分，需要先在有限區域上做、再取極限。令 S_R = [0, R]²，D_R 是半徑 R 的四分之一圓盤。被積函數為正，而且 D_R ⊂ S_R ⊂ D_{R√2}，所以","∬_{D_R} ≤ (∫₀^R e^{−x²} dx)² ≤ ∬_{D_{R√2}}。左右兩邊用極座標算出來是 (π/4)(1 − e^{−R²}) 與 (π/4)(1 − e^{−2R²})，R → ∞ 都 → π/4，夾擠得 I² = π/4。"],"collapsible":true}],"workedExamples":[{"title":"完整推導","prompt":"證明 Γ(1/2) = √π。","problemId":"mob-gamma-002","steps":["x = u²：Γ(1/2) = 2∫₀^∞ e^{−u²} du = 2I。","I² = ∫₀^{π/2}∫₀^∞ e^{−r²} r dr dθ。","內層：∫₀^∞ e^{−r²} r dr = [−e^{−r²}/2]₀^∞ = 1/2。外層乘上 θ 的範圍 π/2：I² = π/4。","I = √π/2（取正根，因為被積函數為正），Γ(1/2) = √π ≈ 1.7725。"],"answer":"√π"},{"title":"指數有係數","prompt":"∫₀^∞ e^{−3x²} dx","steps":["令 u = √3 x，dx = du/√3，3x² = u²。","積分 = (1/√3) ∫₀^∞ e^{−u²} du = (1/√3)(√π/2)。","一般公式：∫₀^∞ e^{−ax²} dx = (1/2)√(π/a)，a > 0。這裡 a = 3，得 (1/2)√(π/3) ≈ 0.5117。"],"answer":"(1/2)√(π/3)"},{"title":"常態分布的常數","prompt":"∫_{−∞}^∞ e^{−x²/2} dx","steps":["用上面的公式，a = 1/2：∫₀^∞ e^{−x²/2} dx = (1/2)√(π/(1/2)) = (1/2)√(2π)。","被積函數是偶函數，整條實數線是兩倍：√(2π)。","這就是常態分布密度前面為什麼是 1/√(2π)：讓總面積等於 1。"],"answer":"√(2π)"}],"pitfalls":["換元 x = u² 時漏了 dx = 2u du 的 2，得到 Γ(1/2) = √π/2。","極座標忘了 r：沒有 r，∫ e^{−r²} dr 一樣積不出來。","θ 的範圍：只算第一象限是 π/2；整個平面才是 2π（那時得到的是 (∫_{−∞}^∞)² = π）。","∫₀^∞ 與 ∫_{−∞}^∞ 混用，差一個 2。"],"checks":[{"ask":"Γ(1/2) 等於？","options":[{"label":"√π","correct":true},{"label":"π","why":"π 是 I² 那一層的量（整個平面上的 (∫_{−∞}^∞ e^{−x²} dx)²），開根號才是 √π。"},{"label":"√π/2","why":"那是 ∫₀^∞ e^{−x²} dx。Γ(1/2) = 2∫₀^∞ e^{−u²} du，多一個 2。"}]},{"ask":"∫_{−∞}^∞ e^{−x²} dx 等於？","options":[{"label":"√π","correct":true},{"label":"√π/2","why":"那是從 0 積到 ∞ 的一半。"},{"label":"π","why":"π 是它的平方；面積本身要開根號。"}]},{"ask":"換極座標之後為什麼算得出來？","options":[{"label":"面積元素多了一個 r，∫ e^{−r²} r dr 可以用 u = r² 積出來","correct":true},{"label":"因為 e^{−r²} 本身有初等反導函數","why":"e^{−r²} 跟 e^{−x²} 是同一個函數，一樣沒有初等反導函數；靠的是多出來的 r。"},{"label":"因為極座標下積分區域變成有限","why":"r 還是從 0 到 ∞，區域沒有變有限。"}]},{"ask":"∫₀^∞ e^{−4x²} dx 等於？","options":[{"label":"√π/4","correct":true},{"label":"√π/8","why":"令 u = 2x，dx = du/2，只除以 2，不是 4：(1/2)(√π/2) = √π/4。"},{"label":"√π/2","why":"係數 4 會讓曲線變窄、面積變小，不能忽略。"}]}],"practice":[{"id":"mob-gamma-002","core":true},{"id":"world-090","core":true},{"id":"mob-gamma-007"},{"id":"mob-gamma-003"}]},"gamma-half-integer":{"id":"gamma-half-integer","prerequisites":["gamma-half","gamma-recurrence-apps"],"next":["gamma-scaled"],"related":[],"objectives":["從 Γ(1/2) = √π 用遞迴算出 Γ(3/2)、Γ(5/2)、Γ(7/2)，並寫出一般式 Γ(n + 1/2) = (1·3·5⋯(2n − 1))/2ⁿ · √π。","往左推出 Γ(−1/2) = −2√π、Γ(−3/2) = 4√π/3。","用 ∫₀^∞ xᵐ e^{−x²} dx = (1/2)Γ((m + 1)/2) 一次處理所有 xᵐ e^{−x²}：m 奇數得到階乘，m 偶數得到 √π。"],"concept":[{"heading":"① 從 √π 往上爬","body":["每往上一格，乘上「前一格的參數」：Γ(3/2) = (1/2)Γ(1/2) = √π/2；Γ(5/2) = (3/2)Γ(3/2) = 3√π/4；Γ(7/2) = (5/2)Γ(5/2) = 15√π/8。","一般式：分子是連續奇數的乘積，分母是 2 的次方。也可以寫成 Γ(n + 1/2) = (2n)!/(4ⁿ n!) · √π（分子分母同乘 2·4⋯(2n)）。"],"tex":["\\Gamma\\!\\left(n+\\tfrac12\\right)=\\frac{1\\cdot3\\cdot5\\cdots(2n-1)}{2^{n}}\\sqrt{\\pi}"]},{"heading":"② 往下推到負的半整數","body":["用 Γ(s) = Γ(s + 1)/s：Γ(−1/2) = Γ(1/2)/(−1/2) = −2√π；Γ(−3/2) = Γ(−1/2)/(−3/2) = 4√π/3。","往下是「除以」，往上是「乘以」，方向不要搞混。正負號每過一個負整數翻一次。"]},{"heading":"③ 一條公式管所有 xᵐ e^{−x²}","body":["令 u = x²，x = u^{1/2}，dx = du/(2√u)：xᵐ dx = u^{m/2} · du/(2u^{1/2}) = (1/2)u^{(m−1)/2} du。所以 ∫₀^∞ xᵐ e^{−x²} dx = (1/2)Γ((m + 1)/2)（m > −1）。","m 是奇數時 (m + 1)/2 是整數，答案是階乘的一半，沒有 π：例如 m = 3 得 (1/2)Γ(2) = 1/2。m 是偶數時 (m + 1)/2 是半整數，答案帶 √π：例如 m = 4 得 (1/2)Γ(5/2) = 3√π/8。","這解釋了一個常見的現象：x³ e^{−x²} 用換元直接積得出來，x⁴ e^{−x²} 卻怎麼分部積分都會剩下一個 Gaussian。"],"tex":["\\int_0^{\\infty}x^{m}e^{-x^{2}}\\,dx=\\frac12\\,\\Gamma\\!\\left(\\frac{m+1}{2}\\right)"]}],"workedExamples":[{"title":"Γ(7/2)","prompt":"Γ(7/2)","problemId":"mob-gamma-009","steps":["Γ(7/2) = (5/2)Γ(5/2) = (5/2)(3/2)Γ(3/2) = (5/2)(3/2)(1/2)Γ(1/2)。","(5 · 3 · 1)/(2 · 2 · 2) = 15/8。","Γ(7/2) = 15√π/8 ≈ 3.323。"],"answer":"15√π/8"},{"title":"偶數次方乘 Gaussian","prompt":"∫₀^∞ x⁴ e^{−x²} dx","problemId":"burst-int-009","steps":["m = 4，用 ∫₀^∞ xᵐ e^{−x²} dx = (1/2)Γ((m + 1)/2)：(1/2)Γ(5/2)。","Γ(5/2) = (3/2)(1/2)√π = 3√π/4。","答案 (1/2)(3√π/4) = 3√π/8 ≈ 0.6647。"],"answer":"3√π/8"},{"title":"負的半整數","prompt":"Γ(−3/2)","steps":["往下推要除：Γ(−1/2) = Γ(1/2)/(−1/2) = −2√π。","Γ(−3/2) = Γ(−1/2)/(−3/2) = (−2√π) · (−2/3) = 4√π/3 ≈ 2.363。","正負號：(−1, 0) 這段是負的，(−2, −1) 這段又變正，跟答案一致。"],"answer":"4√π/3"}],"pitfalls":["往上乘錯數：Γ(5/2) = (3/2)Γ(3/2)，不是 (5/2)Γ(3/2)。","往下推時用乘的：Γ(−1/2) = Γ(1/2)/(−1/2)，是除以 −1/2，也就是乘 −2。","xᵐ e^{−x²} 換元後漏了 1/2，或把 Γ((m + 1)/2) 寫成 Γ(m/2)。","以為所有 Gamma 值都帶 √π；整數點沒有，半整數點才有。"],"checks":[{"ask":"Γ(5/2) 是？","options":[{"label":"3√π/4","correct":true},{"label":"3√π/2","why":"Γ(5/2) = (3/2)Γ(3/2)，而 Γ(3/2) = √π/2，不是 √π。"},{"label":"15√π/4","why":"多乘了 5/2：遞迴乘的是 s，Γ(5/2) = (3/2)Γ(3/2)。"}]},{"ask":"∫₀^∞ x² e^{−x²} dx 是？","options":[{"label":"√π/4","correct":true},{"label":"√π/2","why":"公式是 (1/2)Γ(3/2) = (1/2)(√π/2)，漏了前面的 1/2。"},{"label":"1/2","why":"那是 m = 3 的答案 (1/2)Γ(2)。m = 2 對應 Γ(3/2)，會帶 √π。"}]},{"ask":"Γ(−1/2) 是？","options":[{"label":"−2√π","correct":true},{"label":"2√π","why":"Γ(−1/2) = Γ(1/2)/(−1/2)，除以負數，結果是負的。"},{"label":"−√π/2","why":"往下推要除以 −1/2，不是乘以 −1/2。"}]},{"ask":"∫₀^∞ x³ e^{−x²} dx 是？","options":[{"label":"1/2","correct":true},{"label":"√π/4","why":"m = 3 對應 Γ((3 + 1)/2) = Γ(2) = 1，是整數點，沒有 √π。"},{"label":"1","why":"公式前面有 1/2：(1/2)Γ(2) = 1/2。"}]}],"practice":[{"id":"mob-gamma-003","core":true},{"id":"mob-gamma-004","core":true},{"id":"mob-gamma-009","core":true},{"id":"rel-boss-004","core":true},{"id":"burst-int-009","core":true},{"id":"burst-int-010","core":true},{"id":"depth-int-026"},{"id":"mob-gamma-007"},{"id":"td-int-006","challenge":true,"note":"挑戰：整條實數線、指數有係數 3，先用偶函數變成兩倍，再縮放。"}]},"gamma-scaled":{"id":"gamma-scaled","prerequisites":["gamma-half-integer","u-sub-definite"],"next":["beta-function"],"related":["feynman-trick-basic","gamma-definition"],"objectives":["推出並使用 ∫₀^∞ x^{s−1} e^{−ax} dx = Γ(s)/aˢ（a > 0）。","推出並使用 ∫₀^∞ x^{s−1} e^{−axᵖ} dx = Γ(s/p)/(p a^{s/p})，處理 e^{−x³}、e^{−2x²} 這類指數。","用「量綱」檢查答案：x 的尺度是 1/a，結果一定帶 a 的 −s 次方。"],"concept":[{"heading":"① 指數裡有係數：令 u = ax","body":["∫₀^∞ x^{s−1} e^{−ax} dx（a > 0）：令 u = ax，x = u/a，dx = du/a。x^{s−1} dx = (u/a)^{s−1} du/a = u^{s−1} du/aˢ。","所以結果是 Γ(s)/aˢ。〈Gamma 函數：定義與遞迴〉裡的 Γ(k + 1)/a^{k+1} 是 s = k + 1 的特例。a ≤ 0 時 e^{−ax} 不衰減，積分發散。"],"tex":["\\int_0^{\\infty}x^{s-1}e^{-ax}\\,dx=\\frac{\\Gamma(s)}{a^{s}}\\qquad(s>0,\\ a>0)"]},{"heading":"② 指數裡是 xᵖ：令 u = a xᵖ","body":["∫₀^∞ x^{s−1} e^{−axᵖ} dx（p > 0）：令 u = a xᵖ，x = (u/a)^{1/p}，dx = (1/p) a^{−1/p} u^{1/p − 1} du。","合併 u 的次方：x^{s−1} dx = (1/p) a^{−s/p} u^{s/p − 1} du。結果是 Γ(s/p)/(p a^{s/p})。","p = 1 回到 ①；p = 2 就是上一課的 ∫₀^∞ xᵐ e^{−x²} dx = (1/2)Γ((m + 1)/2)（s = m + 1、a = 1）。"],"tex":["\\int_0^{\\infty}x^{s-1}e^{-a x^{p}}\\,dx=\\frac{\\Gamma(s/p)}{p\\,a^{s/p}}"]},{"heading":"③ 量綱檢查","body":["如果 x 帶單位（例如秒），a 的單位就是 1/秒，指數 ax 才是純數。積分 ∫ x^{s−1} dx 的單位是 秒ˢ，所以答案一定長成「純數 × a^{−s}」。寫出 a^{−(s−1)} 或 a^{−s−1}，量綱就對不上，一定是 dx 換錯了。p 的情況同理：a xᵖ 是純數，x 的尺度是 a^{−1/p}，答案帶 a^{−s/p}。"]}],"workedExamples":[{"title":"半整數加係數","prompt":"∫₀^∞ x^{3/2} e^{−4x} dx","problemId":"rel-hard-int-002","steps":["x^{3/2} = x^{s−1}，s = 5/2；a = 4。","結果 Γ(5/2)/4^{5/2}。Γ(5/2) = 3√π/4，4^{5/2} = (√4)⁵ = 32。","答案 (3√π/4)/32 = 3√π/128 ≈ 0.0415。"],"answer":"3√π/128"},{"title":"指數是 x³","prompt":"∫₀^∞ e^{−x³} dx","steps":["s − 1 = 0，s = 1；p = 3；a = 1。","結果 Γ(1/3)/3。","用遞迴改寫：Γ(4/3) = (1/3)Γ(1/3)，所以答案也是 Γ(4/3) ≈ 0.8930。這個值沒有更簡單的閉式。"],"answer":"Γ(1/3)/3 = Γ(4/3)"},{"title":"x² 指數又有係數","prompt":"∫₀^∞ x⁴ e^{−2x²} dx","problemId":"hc-spec-006","steps":["x⁴ = x^{s−1}，s = 5；p = 2；a = 2。","結果 Γ(5/2)/(2 · 2^{5/2})。","Γ(5/2) = 3√π/4；2^{5/2} = 4√2，所以分母 2 · 4√2 = 8√2。","答案 (3√π/4)/(8√2) = 3√π/(32√2) ≈ 0.1175。"],"answer":"3√π/(32√2)"}],"pitfalls":["aˢ 寫成 a^{s−1}：漏了 dx = du/a 的那一個 1/a。","指數是 xᵖ 時忘了前面的 1/p。","把 s 讀錯：x^{3/2} 對應 s = 5/2，不是 3/2。","a ≤ 0 也套公式；積分只在 a > 0 收斂。"],"checks":[{"ask":"∫₀^∞ x² e^{−5x} dx 是？","options":[{"label":"2/125","correct":true},{"label":"2/25","why":"分母是 a^{s}，s = 3，要 5³ = 125；寫成 5² 是漏了 dx = du/5。"},{"label":"250","why":"a 在分母：指數衰減得越快，面積越小。"}]},{"ask":"∫₀^∞ e^{−x⁴} dx 是？","options":[{"label":"Γ(5/4)","correct":true},{"label":"Γ(1/4)","why":"公式是 Γ(1/4)/4，漏了 1/p；Γ(1/4)/4 = Γ(5/4)。"},{"label":"Γ(4)","why":"p = 4 出現在 Γ 的分母位置：Γ(s/p) = Γ(1/4)，不是 Γ(4)。"}]},{"ask":"∫₀^∞ x^{s−1} e^{−ax} dx = Γ(s)/aˢ 裡的 aˢ 是從哪裡來的？","options":[{"label":"x^{s−1} 貢獻 a^{−(s−1)}，dx 再貢獻 a^{−1}","correct":true},{"label":"e^{−ax} 換元後變成 aˢ e^{−u}","why":"e^{−ax} 換元後就是 e^{−u}，不帶 a；a 全部來自 x^{s−1} 與 dx。"},{"label":"Γ 函數本身的性質 Γ(as) = aˢΓ(s)","why":"沒有這個性質；Gamma 不是這樣縮放的。"}]},{"ask":"∫₀^∞ x e^{−ax} dx 對哪些 a 收斂？","options":[{"label":"a > 0","correct":true},{"label":"a ≠ 0","why":"a < 0 時 e^{−ax} 是增長的指數，積分發散。"},{"label":"所有實數 a","why":"a = 0 時是 ∫₀^∞ x dx，發散。"}]}],"practice":[{"id":"rel-adv-011","core":true},{"id":"burst-int-001","core":true},{"id":"rel-hard-int-001","core":true},{"id":"rel-hard-int-002","core":true},{"id":"hc-spec-006","core":true},{"id":"burst-boss-param-002"},{"id":"td-int-006","challenge":true,"note":"挑戰：整條實數線，偶函數先乘 2，再套 p = 2、a = 3。"}]},"beta-function":{"id":"beta-function","prerequisites":["gamma-scaled","improper-p-test","integration-by-parts","u-sub-definite"],"next":["beta-gamma-relation"],"related":[],"objectives":["寫得出 B(p, q) = ∫₀¹ x^{p−1}(1 − x)^{q−1} dx，說得出它在 p > 0、q > 0 時收斂，並且 B(p, q) = B(q, p)。","從題目的次方正確讀出 p、q（次方加 1）。","用分部積分的遞迴算出整數點的值 B(m, n) = (m − 1)!(n − 1)!/(m + n − 1)!，並認得 [0, a] 與 [0, ∞) 上的變形。"],"concept":[{"heading":"① 另一整族積分：[0, 1] 上的 xᵃ(1 − x)ᵇ","body":["∫₀¹ x²(1 − x)³ dx、∫₀¹ √x (1 − x) dx、∫₀¹ dx/√(x(1 − x))……展開或換元都能做，但每題都不同。Gamma 統一了 [0, ∞) 上的 xᵏe^{−x}，Beta 統一 [0, 1] 上的 xᵃ(1 − x)ᵇ：","讀題方法跟 Gamma 一樣是「次方加 1」：x² 對應 p = 3，(1 − x)³ 對應 q = 4，所以 ∫₀¹ x²(1 − x)³ dx = B(3, 4)。"],"tex":["B(p,q)=\\int_0^{1}x^{p-1}(1-x)^{q-1}\\,dx"]},{"heading":"② 收斂與對稱","body":["兩個端點都可能是瑕點。x → 0⁺ 時被積函數像 x^{p−1}，由 p 判別要 p − 1 > −1，即 p > 0；x → 1⁻ 時像 (1 − x)^{q−1}，要 q > 0。所以：此積分表示式在 p > 0 且 q > 0 時收斂。","令 x = 1 − t，兩個因子對調、區間不變：B(p, q) = B(q, p)。"]},{"heading":"③ 整數點：用分部積分降次","body":["對 B(p, q + 1) = ∫₀¹ x^{p−1}(1 − x)^q dx 取 u = (1 − x)^q、dv = x^{p−1} dx。邊界項 [xᵖ(1 − x)^q/p]₀¹ = 0，得 B(p, q + 1) = (q/p) B(p + 1, q)：把 (1 − x) 的次數搬一個給 x。","一直搬到 (1 − x) 的次數變 0，再用 B(p, 1) = ∫₀¹ x^{p−1} dx = 1/p，就得到整數點的公式（下一課會用 Gamma 給出所有 p、q 的版本）。"],"tex":["B(m,n)=\\frac{(m-1)!\\,(n-1)!}{(m+n-1)!}\\qquad(m,n\\ \\text{為正整數})"]},{"heading":"④ 兩種常見的變形","body":["區間 [0, a]：令 x = a t，∫₀ᵃ x^{p−1}(a − x)^{q−1} dx = a^{p+q−1} B(p, q)。","區間 [0, ∞)：令 x = t/(1 + t)，1 − x = 1/(1 + t)，dx = dt/(1 + t)²，得 B(p, q) = ∫₀^∞ t^{p−1}/(1 + t)^{p+q} dt。看到 [0, ∞) 上「冪次除以 (1 + t) 的冪次」也要想到 Beta。"]}],"workedExamples":[{"title":"整數次方","prompt":"∫₀¹ x³(1 − x)⁴ dx","problemId":"burst-int-007","steps":["次方加 1：p = 4，q = 5，積分是 B(4, 5)。","B(4, 5) = 3! 4!/8! = (6 · 24)/40320 = 144/40320。","約分：1/280。展開 (1 − x)⁴ 再逐項積分也會得到 1/280，但要五項。"],"answer":"1/280"},{"title":"區間是 [0, 2]","prompt":"∫₀² x²(2 − x)³ dx","steps":["令 x = 2t，dx = 2 dt：x² = 4t²，(2 − x)³ = 8(1 − t)³。","積分 = ∫₀¹ 4t² · 8(1 − t)³ · 2 dt = 64 B(3, 4)。也就是公式 a^{p+q−1} = 2^{3+4−1} = 2⁶。","B(3, 4) = 2! 3!/6! = 12/720 = 1/60，答案 64/60 = 16/15。"],"answer":"16/15"},{"title":"無窮區間上的 Beta","prompt":"∫₀^∞ t/(1 + t)⁵ dt","steps":["對照 t^{p−1}/(1 + t)^{p+q}：p − 1 = 1，p = 2；p + q = 5，q = 3。","積分 = B(2, 3) = 1! 2!/4! = 2/24 = 1/12。","檢查收斂：t → ∞ 時被積函數 ~ 1/t⁴，收斂；跟 B 的條件 p、q > 0 一致。"],"answer":"1/12"}],"pitfalls":["次方直接當 p、q：x²(1 − x)³ 是 B(3, 4)，不是 B(2, 3)。","整數公式分母寫成 (m + n)!，正確是 (m + n − 1)!。","區間 [0, a] 忘了乘 a^{p+q−1}。","以為 p 或 q 小於 1 時積分發散；只要大於 0 都收斂。"],"checks":[{"ask":"∫₀¹ x²(1 − x)³ dx 用 Beta 寫是？","options":[{"label":"B(3, 4)","correct":true},{"label":"B(2, 3)","why":"B(p, q) 的次方是 p − 1 與 q − 1，所以要各加 1。"},{"label":"B(2, 3)/2","why":"不需要額外的係數；只要把次方加 1。"}]},{"ask":"∫₀¹ x^{p−1}(1 − x)^{q−1} dx 在什麼條件下收斂？","options":[{"label":"p > 0 而且 q > 0","correct":true},{"label":"p > 1 而且 q > 1","why":"太嚴了：p = 1/2 時 x → 0 附近像 x^{−1/2}，p 判別說收斂。"},{"label":"p + q > 0","why":"兩端要分開檢查：p = −1/2、q = 2 時 p + q > 0，但 0 那端像 x^{−3/2}，發散。"}]},{"ask":"B(1, q) 是？","options":[{"label":"1/q","correct":true},{"label":"q","why":"∫₀¹ (1 − x)^{q−1} dx = 1/q，積分會除以 q。"},{"label":"1","why":"只有 q = 1 時才是 1；一般是 1/q。"}]},{"ask":"B(2, 5) 與 B(5, 2) 的關係？","options":[{"label":"相等","correct":true},{"label":"B(2, 5) 比較大，因為 5 比較大的那邊在後面","why":"令 x = 1 − t，兩個因子互換、區間不變，所以兩者相等。"},{"label":"互為倒數","why":"沒有這個關係；它們是同一個積分換了變數的名字。"}]}],"practice":[{"id":"mob-beta-001","core":true},{"id":"mob-beta-002","core":true},{"id":"mob-beta-003","core":true},{"id":"mob-beta-004","core":true},{"id":"burst-int-007","core":true},{"id":"mob-beta-009"},{"id":"mob-beta-010"},{"id":"burst-rec-003"},{"id":"mob-tech-015"}]},"beta-gamma-relation":{"id":"beta-gamma-relation","prerequisites":["beta-function","gamma-half-integer","change-of-variables","jacobian-determinant"],"next":["beta-trig"],"related":["gamma-half","residue-real-integrals"],"objectives":["寫得出 B(p, q) = Γ(p)Γ(q)/Γ(p + q)，並用它算非整數的 Beta 值。","說得出證明的骨架：Γ(p)Γ(q) 寫成二重積分，換成「總和 u = x + y、比例 v = x/(x + y)」兩個變數。","把 [0, 1] 與 [0, ∞) 上的 Beta 型積分化成 Gamma 值計算。"],"concept":[{"heading":"① 公式","body":["Beta 可以完全用 Gamma 表示。整數時它就是上一課的 (m − 1)!(n − 1)!/(m + n − 1)!，因為 Γ(m) = (m − 1)!。","這條公式讓所有非整數的 Beta 都能算：B(1/2, 1/2) = Γ(1/2)²/Γ(1) = π，B(3/2, 3/2) = (√π/2)²/Γ(3) = (π/4)/2 = π/8。","分母 Γ(p + q) 最容易漏掉：B 是三個 Gamma 的組合，不是兩個相乘。"],"tex":["B(p,q)=\\frac{\\Gamma(p)\\,\\Gamma(q)}{\\Gamma(p+q)}"]},{"heading":"② 為什麼：把兩個 Gamma 合成一個二重積分","body":["Γ(p)Γ(q) = ∫₀^∞∫₀^∞ x^{p−1} y^{q−1} e^{−(x+y)} dx dy。指數只跟 x + y 有關，所以換成兩個新變數：u = x + y（總和）、v = x/(x + y)（x 佔的比例）。反過來 x = uv、y = u(1 − v)，u 從 0 到 ∞、v 從 0 到 1，剛好蓋滿第一象限。","代進去：x^{p−1}y^{q−1} = u^{p+q−2} v^{p−1}(1 − v)^{q−1}，再乘上 Jacobian u，被積函數拆成「只有 u」乘「只有 v」，兩個積分分開算：u 那邊是 Γ(p + q)，v 那邊是 B(p, q)。"]},{"heading":"Jacobian 的計算與嚴格性","body":["x = uv、y = u − uv：∂(x, y)/∂(u, v) 的行列式 = (v)(−u) − (u)(1 − v) = −u，絕對值是 u（〈Jacobian 行列式〉）。","被積函數非負，所以 Fubini–Tonelli 定理保證可以把瑕二重積分寫成累次積分、也可以換變數，不用擔心收斂順序。"],"collapsible":true},{"heading":"③ 一個副產品：再證一次 Γ(1/2) = √π","body":["B(1/2, 1/2) = ∫₀¹ dx/√(x(1 − x))。令 x = sin² θ，dx = 2 sin θ cos θ dθ，√(x(1 − x)) = sin θ cos θ，積分變成 ∫₀^{π/2} 2 dθ = π。","另一方面 B(1/2, 1/2) = Γ(1/2)²/Γ(1) = Γ(1/2)²。所以 Γ(1/2)² = π，跟〈Γ(1/2) = √π〉的極座標算法得到同一個答案。"]},{"heading":"預告：反射公式","body":["p + q = 1 時分母是 Γ(1) = 1，B(s, 1 − s) = Γ(s)Γ(1 − s)。可以證明 Γ(s)Γ(1 − s) = π/sin(πs)（0 < s < 1），證明要用複變（〈用留數算實積分〉）。有了它，∫₀^∞ dx/(1 + x⁴) = (1/4)B(1/4, 3/4) = π/(4 sin(π/4)) = π/(2√2) 這類積分都能一行算完。"],"collapsible":true}],"workedExamples":[{"title":"半圓的面積","prompt":"∫₀¹ √(x(1 − x)) dx","problemId":"burst-int-008","steps":["√(x(1 − x)) = x^{1/2}(1 − x)^{1/2}，次方加 1：B(3/2, 3/2)。","B(3/2, 3/2) = Γ(3/2)²/Γ(3) = (√π/2)²/2 = (π/4)/2 = π/8。","幾何檢查：y = √(x(1 − x)) 是以 (1/2, 0) 為圓心、半徑 1/2 的上半圓，面積 (1/2)π(1/2)² = π/8。"],"answer":"π/8"},{"title":"一端無界","prompt":"∫₀¹ x^{−1/2}(1 − x)^{3/2} dx","problemId":"rel-boss-005","steps":["p − 1 = −1/2，p = 1/2；q − 1 = 3/2，q = 5/2。p、q > 0，收斂。","B(1/2, 5/2) = Γ(1/2)Γ(5/2)/Γ(3)。","Γ(1/2) = √π，Γ(5/2) = 3√π/4，Γ(3) = 2：(√π · 3√π/4)/2 = 3π/8。"],"answer":"3π/8"},{"title":"[0, ∞) 上的 Beta","prompt":"∫₀^∞ √x/(1 + x)³ dx","problemId":"hc-spec-002","steps":["對照 t^{p−1}/(1 + t)^{p+q}（〈Beta 函數〉的變形）：p − 1 = 1/2，p = 3/2；p + q = 3，q = 3/2。","積分 = B(3/2, 3/2) = π/8（範例 1 算過）。"],"answer":"π/8"}],"pitfalls":["漏掉分母 Γ(p + q)，寫成 B(p, q) = Γ(p)Γ(q)。","Γ(3/2) 用成 √π（那是 Γ(1/2)）。","[0, ∞) 形式的 q 讀錯：分母的次方是 p + q，要減掉 p。","Jacobian 漏掉，或寫成 uv。"],"checks":[{"ask":"B(p, q) 用 Gamma 表示是？","options":[{"label":"Γ(p)Γ(q)/Γ(p + q)","correct":true},{"label":"Γ(p)Γ(q)","why":"少了分母 Γ(p + q)；例如 B(1, 1) = 1，但 Γ(1)Γ(1)/Γ(2) 才等於 1。"},{"label":"Γ(p + q)/(Γ(p)Γ(q))","why":"上下顛倒了；B(1, 2) = 1/2，代進去會得到 2。"}]},{"ask":"B(1/2, 1/2) 是？","options":[{"label":"π","correct":true},{"label":"√π","why":"Γ(1/2)² = (√π)² = π，分母 Γ(1) = 1。"},{"label":"2","why":"2 是 B(1/2, 1) = Γ(1/2)Γ(1)/Γ(3/2) = √π/(√π/2)。"}]},{"ask":"B(3/2, 1/2) 是？","options":[{"label":"π/2","correct":true},{"label":"π/4","why":"分母是 Γ(2) = 1：(√π/2)(√π)/1 = π/2。"},{"label":"π","why":"Γ(3/2) = √π/2，不是 √π。"}]},{"ask":"證明裡用 x = uv、y = u(1 − v) 換變數，Jacobian 的絕對值是？","options":[{"label":"u","correct":true},{"label":"1","why":"這個變換會拉伸面積：行列式 v(−u) − u(1 − v) = −u。"},{"label":"uv","why":"算行列式時 v 的項會消掉，剩 −u。"}]}],"practice":[{"id":"mob-trap-012","core":true},{"id":"mob-beta-005","core":true},{"id":"mob-beta-006","core":true},{"id":"mob-beta-007","core":true},{"id":"burst-int-008","core":true},{"id":"rel-boss-005","core":true},{"id":"hc-spec-002"},{"id":"burst-int-029","challenge":true,"note":"挑戰：令 u = x²，化成 [0, ∞) 的 Beta，再用反射公式。"}]},"beta-trig":{"id":"beta-trig","prerequisites":["beta-gamma-relation","trig-integral-sin-cos","u-sub-definite"],"next":["wallis-beta"],"related":["wallis-integral"],"objectives":["用 x = sin² θ 推出 ∫₀^{π/2} sin^{2p−1} θ cos^{2q−1} θ dθ = (1/2)B(p, q)。","看到 ∫₀^{π/2} sinᵐ θ cosⁿ θ dθ 就寫成 (1/2)B((m + 1)/2, (n + 1)/2)，再用 Gamma 算。","從 m、n 的奇偶預測答案有沒有 π，處理分數次方（例如 √tan θ）。"],"concept":[{"heading":"① 從 [0, 1] 搬到 [0, π/2]","body":["在 B(p, q) = ∫₀¹ x^{p−1}(1 − x)^{q−1} dx 裡令 x = sin² θ：1 − x = cos² θ，dx = 2 sin θ cos θ dθ，x 從 0 到 1 對應 θ 從 0 到 π/2。","x^{p−1} = sin^{2p−2} θ，(1 − x)^{q−1} = cos^{2q−2} θ，再乘上 2 sin θ cos θ，次方各加 1："],"tex":["\\int_0^{\\pi/2}\\sin^{2p-1}\\theta\\,\\cos^{2q-1}\\theta\\,d\\theta=\\tfrac12\\,B(p,q)"]},{"heading":"② 實際使用：次方加 1 再除以 2","body":["題目是 sinᵐ θ cosⁿ θ 時，令 2p − 1 = m、2q − 1 = n，也就是 p = (m + 1)/2、q = (n + 1)/2：","∫₀^{π/2} sinᵐ θ cosⁿ θ dθ = (1/2)B((m + 1)/2, (n + 1)/2) = Γ((m + 1)/2)Γ((n + 1)/2) / (2Γ((m + n + 2)/2))。","條件：m > −1、n > −1（對應 p、q > 0），所以分數次方、甚至負的次方（大於 −1）都可以。"]},{"heading":"③ 從奇偶預測答案","body":["m、n 都是偶數：(m + 1)/2、(n + 1)/2 都是半整數，各帶一個 √π，分母是整數點，答案帶 π。","至少一個是奇數：那一個的 Gamma 是整數點；另一個的 √π 會跟分母（也是半整數）的 √π 約掉，答案是有理數。這跟〈sinᵐ x cosⁿ x〉裡「有奇數次方就用換元」的經驗一致。"]}],"workedExamples":[{"title":"有奇數次方","prompt":"∫₀^{π/2} sin⁵ θ cos³ θ dθ","problemId":"burst-int-018","steps":["m = 5、n = 3：p = 3、q = 2，積分 = (1/2)B(3, 2)。","B(3, 2) = 2! 1!/4! = 2/24 = 1/12。","答案 (1/2)(1/12) = 1/24。有奇數次方，答案沒有 π。"],"answer":"1/24"},{"title":"兩個都是偶數","prompt":"∫₀^{π/2} sin⁴ θ cos² θ dθ","problemId":"rel-hard-int-007","steps":["m = 4、n = 2：p = 5/2、q = 3/2，積分 = (1/2)B(5/2, 3/2)。","B(5/2, 3/2) = Γ(5/2)Γ(3/2)/Γ(4) = (3√π/4)(√π/2)/6 = (3π/8)/6 = π/16。","答案 (1/2)(π/16) = π/32，跟〈Wallis 積分〉用 W₄ − W₆ 算的一樣。"],"answer":"π/32"},{"title":"分數次方","prompt":"∫₀^{π/2} √(tan θ) dθ","problemId":"world-065","steps":["√(tan θ) = sin^{1/2} θ cos^{−1/2} θ。m = 1/2、n = −1/2（> −1，收斂）：p = 3/4、q = 1/4。","積分 = (1/2)B(3/4, 1/4) = (1/2)Γ(3/4)Γ(1/4)/Γ(1)。","用反射公式 Γ(s)Γ(1 − s) = π/sin(πs)（〈Beta 與 Gamma 的關係〉的預告）：Γ(1/4)Γ(3/4) = π/sin(π/4) = π√2。","答案 (1/2)π√2 = π/√2 ≈ 2.221。"],"answer":"π/√2"}],"pitfalls":["忘了前面的 1/2。","p、q 讀成 m、n 本身，或讀成 m + 1、n + 1（沒有除以 2）。","Γ((m + n + 2)/2) 寫成 Γ((m + n)/2)：分母的參數是 p + q = (m + n + 2)/2。","負的次方小於等於 −1 時也套公式；那時積分發散。"],"checks":[{"ask":"∫₀^{π/2} sin³ θ cos² θ dθ 是？","options":[{"label":"2/15","correct":true},{"label":"4/15","why":"B(2, 3/2) = Γ(2)Γ(3/2)/Γ(7/2) = 4/15，但公式前面還有 1/2。"},{"label":"2π/15","why":"sin 的次方是奇數，√π 會上下約掉，答案沒有 π。"}]},{"ask":"∫₀^{π/2} sin⁶ θ cos⁴ θ dθ 寫成 Beta 是？","options":[{"label":"(1/2)B(7/2, 5/2)","correct":true},{"label":"(1/2)B(6, 4)","why":"要先加 1 再除以 2：p = (6 + 1)/2 = 7/2。"},{"label":"B(7/2, 5/2)","why":"x = sin² θ 換元時 dx = 2 sin θ cos θ dθ，所以三角形式是 Beta 的一半。"}]},{"ask":"∫₀^{π/2} dθ/√(sin θ) 收斂嗎？","options":[{"label":"收斂：m = −1/2 > −1","correct":true},{"label":"發散：被積函數在 θ = 0 無界","why":"無界不等於發散；θ → 0 時 sin θ ~ θ，被積函數像 θ^{−1/2}，p = 1/2 < 1。"},{"label":"不能用 Beta，因為次方是負的","why":"次方大於 −1 都可以：對應 p = 1/4 > 0。"}]},{"ask":"∫₀^{π/2} sin⁴ θ cos³ θ dθ 的答案：","options":[{"label":"是有理數（沒有 π）","correct":true},{"label":"帶 π，因為 sin 的次方是偶數","why":"只要有一個是奇數就沒有 π：Γ(5/2) 的 √π 會被分母 Γ(9/2) 的 √π 約掉。實際值是 2/35。"},{"label":"帶 √π","why":"分子的 √π 跟分母 Γ(9/2) 的 √π 正好約掉。"}]}],"practice":[{"id":"uni-int-016","core":true},{"id":"burst-int-018","core":true},{"id":"hc-rad-007","core":true},{"id":"burst-int-016","core":true},{"id":"burst-int-017","core":true},{"id":"burst-int-024","core":true},{"id":"burst-int-023"},{"id":"burst-int-019"},{"id":"burst-int-035"},{"id":"burst-int-032"},{"id":"burst-boss-int-017","challenge":true,"note":"挑戰：sin⁸ cos⁸，次方大但公式一樣；分母 Γ(9) = 8!。"},{"id":"world-065","challenge":true,"note":"挑戰：要用反射公式 Γ(1/4)Γ(3/4) = π√2。"}]},"wallis-beta":{"id":"wallis-beta","prerequisites":["beta-trig","wallis-integral","wallis-product"],"next":["parameter-integral"],"related":["gamma-half","stirling"],"objectives":["把 Wallis 積分寫成 Wₙ = (1/2)B((n + 1)/2, 1/2) = √π Γ((n + 1)/2)/(2Γ(n/2 + 1))，並從 Gamma 遞迴推回 Wₙ = ((n − 1)/n)Wₙ₋₂。","用這個式子處理遞迴做不到的非整數次方，例如 ∫₀^{π/2} √(sin x) dx。","說得出 Wallis、Beta、Gamma、Γ(1/2) = √π 怎麼互相推出，以及 Wₙ ~ √(π/(2n))。"],"concept":[{"heading":"① Wallis 是三角 Beta 的特例","body":["上一課：∫₀^{π/2} sinᵐ θ cosⁿ θ dθ = (1/2)B((m + 1)/2, (n + 1)/2)。Wallis 積分是 m = n、cos 的次方 0 的情況，所以 q = 1/2：","Wₙ = (1/2)B((n + 1)/2, 1/2) = Γ((n + 1)/2)Γ(1/2)/(2Γ(n/2 + 1))。"],"tex":["W_n=\\int_0^{\\pi/2}\\sin^{n}x\\,dx=\\frac{\\sqrt{\\pi}\\;\\Gamma\\!\\left(\\frac{n+1}{2}\\right)}{2\\,\\Gamma\\!\\left(\\frac{n}{2}+1\\right)}"]},{"heading":"② 遞迴是 Gamma 遞迴的影子","body":["把 n 換成 n − 2，分子分母的 Gamma 參數各少 1。用 Γ(s) = (s − 1)Γ(s − 1)：Wₙ/Wₙ₋₂ = [((n − 1)/2)Γ((n − 1)/2)/((n/2)Γ(n/2))] ÷ [Γ((n − 1)/2)/Γ(n/2)] = (n − 1)/n。","所以〈Wallis 積分〉的分部積分遞迴，跟 Gamma 的 Γ(s + 1) = sΓ(s) 是同一件事；偶數有 π、奇數沒有，則是因為半整數的 Gamma 帶 √π。"]},{"heading":"③ 遞迴做不到的：非整數次方","body":["∫₀^{π/2} sin^{1/3} x dx、∫₀^{π/2} √(sin x) dx 無法用 n → n − 2 的遞迴降到 W₀ 或 W₁。但 Gamma 公式對任何 n > −1 都成立，答案可以寫成 Gamma 值的組合。"]},{"heading":"④ 一圈閉合的推導","body":["n = 0：W₀ = π/2，而公式給 Γ(1/2)²/(2Γ(1)) = Γ(1/2)²/2。所以 Γ(1/2)² = π，這是 Γ(1/2) = √π 的第三種證明（前兩種是極座標與 B(1/2, 1/2)）。","n 很大時，Γ(x + 1/2)/Γ(x + 1) ~ x^{−1/2}（可由〈Stirling 公式〉推出），得 Wₙ ~ √(π/(2n))，跟〈Wallis 乘積〉裡由 nWₙWₙ₋₁ = π/2 得到的一樣。"]}],"workedExamples":[{"title":"用 Gamma 算 W₇","prompt":"∫₀^{π/2} sin⁷ x dx","problemId":"burst-int-021","steps":["W₇ = (1/2)B(4, 1/2) = Γ(4)Γ(1/2)/(2Γ(9/2))。","Γ(4) = 6，Γ(9/2) = (7/2)(5/2)(3/2)(1/2)√π = 105√π/16。","W₇ = 6√π/(2 · 105√π/16) = 6 · 16/210 = 96/210 = 16/35。跟遞迴 (6/7)(4/5)(2/3) = 16/35 一致。"],"answer":"16/35"},{"title":"非整數次方","prompt":"把 ∫₀^{π/2} √(sin x) dx 寫成 Gamma 值。","steps":["n = 1/2：(1/2)B(3/4, 1/2) = Γ(3/4)Γ(1/2)/(2Γ(5/4))。","Γ(1/2) = √π，Γ(5/4) = (1/4)Γ(1/4)。","答案 √π Γ(3/4)/(2Γ(5/4)) = 2√π Γ(3/4)/Γ(1/4) ≈ 1.1981。"],"answer":"√π Γ(3/4)/(2Γ(5/4)) ≈ 1.1981"},{"title":"大 n 的近似","prompt":"估計 W₁₀₀ = ∫₀^{π/2} sin¹⁰⁰ x dx。","steps":["Wₙ ~ √(π/(2n))，n = 100：√(π/200) ≈ 0.12533。","精確值（用遞迴 (99/100)(97/98)⋯(1/2) · π/2）約 0.12502。","比值約 0.9975，相對誤差約 1/(4n)。"],"answer":"≈ 0.125"}],"pitfalls":["q 寫成 0：cos⁰ 對應 (0 + 1)/2 = 1/2。","分母的 Gamma 參數寫成 n/2，正確是 p + q = n/2 + 1。","以為非整數次方就「不能算」；它有 Gamma 形式的精確值，只是沒有更簡單的閉式。","Wₙ ~ √(π/(2n)) 只保證比值 → 1；n 小時拿來當近似值誤差不小（n = 2 時差約 13%）。"],"checks":[{"ask":"Wₙ = ∫₀^{π/2} sinⁿ x dx 等於哪一個 Beta？","options":[{"label":"(1/2)B((n + 1)/2, 1/2)","correct":true},{"label":"(1/2)B(n/2, 1/2)","why":"sinᵐ 對應 p = (m + 1)/2，要先加 1 再除以 2。"},{"label":"(1/2)B((n + 1)/2, 0)","why":"cos⁰ 對應 q = (0 + 1)/2 = 1/2；q = 0 會讓 Beta 發散。"}]},{"ask":"用 Gamma 公式算 W₄，得到？","options":[{"label":"3π/16","correct":true},{"label":"3π/8","why":"公式分母有 2：Γ(5/2)Γ(1/2)/(2Γ(3)) = (3π/4)/4 = 3π/16。"},{"label":"3√π/8","why":"Γ(5/2)Γ(1/2) = (3√π/4)√π，兩個 √π 相乘是 π。"}]},{"ask":"n → ∞ 時 Wₙ 漸近於？","options":[{"label":"√(π/(2n))","correct":true},{"label":"π/(2n)","why":"nWₙWₙ₋₁ = π/2 給的是 Wₙ² ~ π/(2n)，要開根號。"},{"label":"1/n","why":"Wₙ 衰減得比 1/n 慢，是 n^{−1/2} 的速度。"}]},{"ask":"下面哪一個積分，Wallis 遞迴做不到、但 Beta–Gamma 公式可以？","options":[{"label":"∫₀^{π/2} sin^{1/3} x dx","correct":true},{"label":"∫₀^{π/2} sin⁶ x dx","why":"整數次方，遞迴降到 W₀ 就好。"},{"label":"∫₀^{π/2} sin⁴ x cos² x dx","why":"cos² = 1 − sin²，化成 W₄ − W₆，遞迴就能做。"}]}],"practice":[{"id":"burst-int-021","core":true},{"id":"burst-int-022","core":true},{"id":"burst-int-033","core":true},{"id":"burst-int-034","core":true},{"id":"mob-wallis-010","core":true},{"id":"burst-boss-int-018"},{"id":"burst-boss-int-019"},{"id":"mob-tech-017"},{"id":"dm-seq-004","challenge":true,"note":"挑戰：用 Wₙ ~ √(π/(2n)) 推出 C(2n, n) 的漸近。"}]},"parameter-integral":{"id":"parameter-integral","prerequisites":["improper-infinite","multivariable-continuity","partial-derivatives","improper-comparison"],"next":["leibniz-rule"],"related":["dominated-convergence","dirichlet-integral"],"objectives":["把 I(a) = ∫ f(x, a) dx 看成 a 的函數：會求它的定義域（積分在哪些 a 收斂）與公式。","說得出 I(a) 連續的一個充分條件：f 在閉矩形 [c, d] × [α, β] 上連續。","看出瑕積分的參數積分可能不連續，極限不能隨便搬進積分號（∫₀^∞ a e^{−ax} dx 的反例）。"],"concept":[{"heading":"① 積分算完，還剩一個變數","body":["∫₀¹ xᵃ dx：x 被積掉了，a 留下來，結果是 1/(a + 1)。一般地，I(a) = ∫_c^d f(x, a) dx 是 a 的函數，叫參數積分。積分變數 x 是「啞變數」，換成 t 也一樣；a 才是 I 的自變數。","第一個問題是定義域：積分在哪些 a 收斂。∫₀¹ xᵃ dx 在 a > −1 時收斂（0 端 p 判別），所以 I(a) = 1/(a + 1) 只在 a > −1 有意義，不能代 a = −2 得到 −1。"]},{"heading":"② 什麼時候 I(a) 連續","body":["充分條件：f(x, a) 在閉矩形 [c, d] × [α, β] 上（兩個變數一起）連續，則 I(a) 在 [α, β] 上連續。換句話說，可以把極限搬進積分號：lim_{a→a₀} ∫ f(x, a) dx = ∫ f(x, a₀) dx。","只要求「每個固定的 a，f 對 x 連續」是不夠的；要的是兩個變數一起連續（閉矩形上會自動一致連續，這是證明的關鍵）。"]},{"heading":"③ 無窮區間會出事","body":["I(a) = ∫₀^∞ a e^{−ax} dx：a > 0 時令 u = ax，得 I(a) = 1；a = 0 時被積函數是 0，I(0) = 0。所以 lim_{a→0⁺} I(a) = 1 ≠ I(0)。","圖像：a 越小，曲線 a e^{−ax} 越扁、拖得越長，面積 1 被推到越來越遠的地方，最後「逃到無窮遠」。逐點看被積函數 → 0，面積卻沒有 → 0。","瑕積分要把極限搬進積分號，需要額外條件，例如存在一個不依賴 a、可積的 g(x) 使 |f(x, a)| ≤ g(x)（這是〈控制收斂定理〉的特例）。上面的反例找不到這樣的 g。"]},{"heading":"連續性的證明（閉矩形）","body":["f 在閉矩形上連續，因此一致連續：給 ε > 0，存在 δ，使 |a − a₀| < δ 時對所有 x ∈ [c, d] 都有 |f(x, a) − f(x, a₀)| < ε。於是 |I(a) − I(a₀)| ≤ ∫_c^d |f(x, a) − f(x, a₀)| dx < ε(d − c)。關鍵是同一個 δ 對所有 x 都有效，這正是一致連續給的。"],"collapsible":true}],"workedExamples":[{"title":"公式與定義域","prompt":"I(a) = ∫₀¹ xᵃ dx：求 I(a) 與它的定義域。","steps":["a ≠ −1 時 ∫ xᵃ dx = x^{a+1}/(a + 1)。","從 0 積到 1：a + 1 > 0 時 x^{a+1} 在 0 的極限是 0，得 1/(a + 1)；a + 1 ≤ 0 時那一端發散。","所以 I(a) = 1/(a + 1)，定義域 a > −1。在這個範圍內 I 連續，而且 a → −1⁺ 時 I(a) → ∞。"],"answer":"I(a) = 1/(a + 1)，a > −1"},{"title":"面積逃到無窮遠","prompt":"I(a) = ∫₀^∞ a e^{−ax} dx，a ≥ 0。I 在 a = 0 連續嗎？","steps":["a > 0：令 u = ax，I(a) = ∫₀^∞ e^{−u} du = 1。","a = 0：被積函數 ≡ 0，I(0) = 0。","lim_{a→0⁺} I(a) = 1 ≠ 0 = I(0)，不連續。","原因：區間無限長，「閉矩形上連續」的條件不適用；也找不到控制函數 g。"],"answer":"不連續：a > 0 時 I = 1，I(0) = 0"},{"title":"閉區間上可以搬極限","prompt":"lim_{a→0} ∫₀¹ √(x² + a²) dx","steps":["f(x, a) = √(x² + a²) 在 [0, 1] × [−1, 1] 上兩變數一起連續。","所以可以把極限搬進去：lim_{a→0} ∫₀¹ √(x² + a²) dx = ∫₀¹ √(x²) dx = ∫₀¹ x dx（x ≥ 0）。","= 1/2。"],"answer":"1/2"}],"pitfalls":["把公式代到定義域外，例如由 ∫₀¹ xᵃ dx = 1/(a + 1) 說 a = −2 時積分是 −1。","瑕積分直接把極限搬進積分號（∫₀^∞ a e^{−ax} dx 的反例）。","以為「對每個 a，f 對 x 連續」就保證 I 連續；要兩變數一起連續。","把積分變數 x 跟參數 a 混在一起，對 x 求極限。"],"checks":[{"ask":"I(a) = ∫₀¹ xᵃ dx 的定義域是？","options":[{"label":"a > −1","correct":true},{"label":"a ≠ −1","why":"a < −1 時 x → 0⁺ 那端像 1/x^{|a|}，次方大於 1，發散。"},{"label":"所有實數 a","why":"a = −1 時是 ∫₀¹ dx/x，發散。"}]},{"ask":"下列哪一個條件保證 I(a) = ∫_c^d f(x, a) dx 在 [α, β] 上連續？","options":[{"label":"f 在閉矩形 [c, d] × [α, β] 上兩變數一起連續","correct":true},{"label":"對每個固定的 a，f 對 x 連續","why":"這只保證每個 I(a) 有定義，不保證 a 變動時 I 連續。"},{"label":"f 對 a 可微","why":"只看 a 不夠，還要控制 x 方向；連續性的條件是兩變數一起連續。"}]},{"ask":"a > 0 時 ∫₀^∞ a e^{−ax} dx = 1。那 lim_{a→0⁺} 與「把極限搬進積分」分別是？","options":[{"label":"1 與 0，兩者不同，所以不能搬","correct":true},{"label":"都是 0","why":"對每個 a > 0 積分都是 1，極限是 1，不是 0。"},{"label":"都是 1","why":"被積函數逐點 → 0，搬進去得到 ∫ 0 dx = 0。"}]},{"ask":"I(a) = ∫₀^∞ sin(ax)/x dx（a > 0 時等於 π/2）。I(−3) 是？","options":[{"label":"−π/2","correct":true},{"label":"π/2","why":"sin(−3x) = −sin(3x)，積分整個變號。"},{"label":"0","why":"只有 a = 0 時被積函數 ≡ 0。a ≠ 0 時用 u = |a|x 換元，大小都是 π/2。"}]}],"practice":[{"id":"burst-boss-param-002","core":true},{"id":"burst-boss-param-001","core":true},{"id":"burst-boss-param-003","core":true},{"id":"burst-rec-001","core":true},{"id":"rel-boss-001"},{"id":"lb-con-003","challenge":true,"note":"挑戰：參數是 n，被積函數逐點 → 0，但積分的極限是 1/2。"}]},"leibniz-rule":{"id":"leibniz-rule","prerequisites":["parameter-integral","ftc-part1","chain-rule","multivariable-chain-rule"],"next":["feynman-trick-basic"],"related":["dominated-convergence"],"objectives":["說得出把微分搬進積分號的一個充分條件：f 與 ∂f/∂a 在閉矩形上連續；瑕積分還要一個可積的控制函數。","會用完整版 Leibniz 法則：上下限與被積函數都含參數時，三項都要寫。","把一個已知的積分公式對參數微分，生出新的積分公式（例如 ∫₀¹ xⁿ ln x dx = −1/(n + 1)²）。"],"concept":[{"heading":"① 微分能不能搬進積分號","body":["I(a) = ∫_c^d f(x, a) dx。直覺上，I 的變化率就是每一條 x 處的變化率 ∂f/∂a 加起來，也就是 I′(a) = ∫_c^d ∂f/∂a dx。這個「微分與積分交換」不是永遠成立，需要條件。","充分條件（區間有限）：f 與 ∂f/∂a 都在閉矩形 [c, d] × [α, β] 上連續，則 I 在 (α, β) 上可微，而且可以交換。"],"tex":["\\frac{d}{da}\\int_c^{d}f(x,a)\\,dx=\\int_c^{d}\\frac{\\partial f}{\\partial a}(x,a)\\,dx"]},{"heading":"② 上下限也會動：三項都要寫","body":["上下限是 u(a)、v(a) 時，面積的變化有三個來源：右邊界移動（f(v(a), a) v′(a)）、左邊界移動（−f(u(a), a) u′(a)）、曲線本身移動（∫ ∂f/∂a dx）。","f 不含 a 時只剩前兩項，就是〈微積分基本定理 I〉加上連鎖律；上下限不動時只剩第三項，就是 ①。"],"tex":["\\frac{d}{da}\\int_{u(a)}^{v(a)}f(x,a)\\,dx=f(v,a)\\,v'(a)-f(u,a)\\,u'(a)+\\int_{u(a)}^{v(a)}\\frac{\\partial f}{\\partial a}\\,dx"]},{"heading":"③ 瑕積分：要一個控制函數","body":["區間無限或端點無界時，閉矩形的條件用不上。一個常用的充分條件：在 a₀ 附近，存在不依賴 a 的 g(x)，使 |∂f/∂a (x, a)| ≤ g(x)，而且 ∫ g 收斂（另外 ∫ f(x, a) dx 本身收斂）。這是〈控制收斂定理〉的應用。","例：I(a) = ∫₀¹ xᵃ dx，a ≥ a₀ > −1 時 |∂(xᵃ)/∂a| = xᵃ|ln x| ≤ x^{a₀}|ln x|，後者在 [0, 1] 可積，所以可以對 a 微分。"]},{"heading":"條件不滿足時會錯的例子","body":["I(a) = ∫₀^∞ sin(ax)/x dx：a > 0 時 I(a) = π/2 是常數，I′(a) = 0。硬把微分搬進去得到 ∫₀^∞ cos(ax) dx，這個積分根本不收斂。原因是 |∂f/∂a| = |cos(ax)| 找不到可積的控制函數。"],"collapsible":true}],"workedExamples":[{"title":"上下限都在動","prompt":"d/dx ∫ₓ^{2x} (sin t)/t dt","steps":["被積函數不含 x，只有上下限在動：第三項是 0。","上限 v = 2x：(sin 2x)/(2x) · 2 = (sin 2x)/x。下限 u = x：(sin x)/x · 1。","答案 (sin 2x)/x − (sin x)/x = (sin 2x − sin x)/x。sin t/t 沒有初等反導函數，但導數照樣算得出來。"],"answer":"(sin 2x − sin x)/x"},{"title":"三項都有","prompt":"F(x) = ∫₀ˣ e^{x−t} sin t dt。求 F′(x)，並說明它跟 F 的關係。","problemId":"int-057","steps":["上限 v = x：f(x, x) · 1 = e⁰ sin x = sin x。下限 0 不動。","被積函數對 x 偏微分：∂(e^{x−t} sin t)/∂x = e^{x−t} sin t，積分起來正好是 F(x)。","所以 F′(x) = sin x + F(x)，而且 F(0) = 0。這是一個一階線性微分方程，解出 F(x) = (eˣ − sin x − cos x)/2。"],"answer":"F′ = sin x + F"},{"title":"對公式微分，生出新公式","prompt":"由 ∫₀¹ xᵃ dx = 1/(a + 1) 求 ∫₀¹ xᵃ ln x dx。","problemId":"burst-rec-001","steps":["∂(xᵃ)/∂a = xᵃ ln x（xᵃ = e^{a ln x}）。","條件：a ≥ a₀ > −1 時 |xᵃ ln x| ≤ x^{a₀}|ln x|，可積（③），可以交換。","兩邊對 a 微分：∫₀¹ xᵃ ln x dx = d/da (a + 1)^{−1} = −1/(a + 1)²。","a = n：∫₀¹ xⁿ ln x dx = −1/(n + 1)²。再微分一次得 ∫₀¹ xⁿ (ln x)² dx = 2/(n + 1)³。"],"answer":"−1/(a + 1)²"}],"pitfalls":["上下限含參數時只寫 ∫ ∂f/∂a，漏了邊界兩項。","邊界項忘了乘 v′(a)、u′(a)（連鎖律）。","下限那一項的負號。","瑕積分不檢查控制函數就交換（sin(ax)/x 的反例）。"],"checks":[{"ask":"d/dx ∫₀^{x²} cos t dt 是？","options":[{"label":"2x cos(x²)","correct":true},{"label":"cos(x²)","why":"上限是 x²，要乘上它的導數 2x（連鎖律）。"},{"label":"sin(x²)","why":"那是積分本身的值；題目問的是它對 x 的導數。"}]},{"ask":"下面哪一個條件保證 d/da ∫_c^d f(x, a) dx = ∫_c^d ∂f/∂a dx？","options":[{"label":"f 與 ∂f/∂a 在閉矩形 [c, d] × [α, β] 上連續","correct":true},{"label":"f 在閉矩形上連續就夠了","why":"那只保證 I(a) 連續；要交換微分，∂f/∂a 也要連續。"},{"label":"∂f/∂a 存在就夠了","why":"只存在不夠，需要連續（或被可積函數控制）才能保證積分後的導數正確。"}]},{"ask":"I(a) = ∫₀¹ e^{ax} dx，I′(0) 是？","options":[{"label":"1/2","correct":true},{"label":"1","why":"I′(a) = ∫₀¹ x e^{ax} dx，在 a = 0 是 ∫₀¹ x dx = 1/2。"},{"label":"e − 1","why":"那是 I(1)。題目問的是對 a 的導數在 a = 0 的值。"}]},{"ask":"由 ∫₀^∞ e^{−ax} dx = 1/a（a > 0）對 a 微分一次，得到 ∫₀^∞ x e^{−ax} dx 等於？","options":[{"label":"1/a²","correct":true},{"label":"−1/a²","why":"左邊微分得 −∫ x e^{−ax} dx，右邊是 −1/a²，兩邊的負號約掉。"},{"label":"1/a","why":"微分會讓 a 的次方多一次：1/a 微分是 −1/a²。"}]}],"practice":[{"id":"cx-ftc-004","core":true},{"id":"exam-der-015","core":true},{"id":"depth-der-005","core":true},{"id":"burst-rec-001","core":true},{"id":"burst-rec-002","core":true},{"id":"int-057","core":true},{"id":"int-058"},{"id":"int-059"},{"id":"burst-boss-param-002"},{"id":"burst-boss-param-006","challenge":true,"note":"挑戰：從 ∫₀¹ xⁿ dx = 1/(n + 1) 微分三次。"}]},"feynman-trick-basic":{"id":"feynman-trick-basic","prerequisites":["leibniz-rule","parameter-integral","gamma-half"],"next":["feynman-trick-advanced"],"related":["frullani","dirichlet-integral"],"objectives":["照五個步驟用對參數微分算積分：放參數、對參數微分、算 I′(a)、積回 I(a)、用特殊值定常數。","選參數的原則：讓 ∂f/∂a 把難纏的因子（1/ln x、1/x）消掉。","每次交換微分與積分，都說得出用的是哪個充分條件（閉矩形連續，或可積的控制函數）。"],"concept":[{"heading":"① 想法：把一個積分放進一整族","body":["∫₀¹ (x² − 1)/ln x dx 的被積函數沒有初等反導函數。但把 2 換成參數 a，I(a) = ∫₀¹ (xᵃ − 1)/ln x dx，對 a 微分：∂/∂a (xᵃ − 1) = xᵃ ln x，分母的 ln x 被約掉，剩下 ∫₀¹ xᵃ dx = 1/(a + 1)，一行算完。","難的積分變簡單，代價是多一個變數；最後再積回來。"]},{"heading":"② 五個步驟","body":["1. 放參數：把題目的某個常數換成 a（或乘上 e^{−ax} 之類的因子），讓原題是 I 在某個 a 的值。","2. 對 a 微分，搬進積分號（〈Leibniz 積分法則〉；確認條件）。","3. 算出 I′(a)。","4. 對 a 積分得 I(a) = … + C。","5. 找一個 I 容易知道的 a（常常是 a = 0 或 a → ∞）定出 C，再代入要的 a。"]},{"heading":"③ 怎麼選參數","body":["看哪個因子讓積分卡住：1/ln x 卡住，就把 x 的次方換成 a（微分生出 ln x）；1/x 卡住，就乘上 e^{−ax}（微分生出 −x）；1/x² 卡住，就把 e^{−x²} 改成 e^{−ax²}（微分生出 −x²）。","放進去的 e^{−ax} 還有一個好處：a > 0 時它讓積分絕對收斂，交換微分與積分時容易找到控制函數。"]},{"heading":"範例 2 的交換為什麼合法","body":["f(x, a) = e^{−ax} sin x/x，∂f/∂a = −e^{−ax} sin x。對 a ≥ a₀ > 0，|∂f/∂a| ≤ e^{−a₀x}，在 [0, ∞) 可積，所以在 a > 0 上可以交換。","定常數用 a → ∞：|I(a)| ≤ ∫₀^∞ e^{−ax} dx = 1/a → 0（|sin x/x| ≤ 1）。I 在 a = 0 的值（Dirichlet 積分）要另外處理連續性，留到〈Dirichlet 積分〉。"],"collapsible":true}],"workedExamples":[{"title":"1/ln x 卡住：把次方換成參數","prompt":"∫₀¹ (x² − 1)/ln x dx","problemId":"world-019","steps":["I(a) = ∫₀¹ (xᵃ − 1)/ln x dx（a ≥ 0），原題是 I(2)。","I′(a) = ∫₀¹ xᵃ ln x/ln x dx = ∫₀¹ xᵃ dx = 1/(a + 1)。（a > 0 時 |∂f/∂a| = xᵃ ≤ 1，可積，可以交換。）","積回去：I(a) = ln(a + 1) + C。","a = 0 時被積函數是 0，I(0) = 0；而且 0 < x < 1 時 |xᵃ − 1| ≤ a|ln x|，所以 |I(a)| ≤ a → 0，I 在 0 連續。於是 C = 0，I(2) = ln 3。"],"answer":"ln 3"},{"title":"1/x 卡住：乘上 e^{−ax}","prompt":"∫₀^∞ e^{−x} sin x/x dx","problemId":"world-070","steps":["I(a) = ∫₀^∞ e^{−ax} sin x/x dx（a > 0），原題是 I(1)。","I′(a) = −∫₀^∞ e^{−ax} sin x dx = −1/(1 + a²)（這個積分可用兩次分部積分或複數指數算出）。","積回去：I(a) = −arctan a + C。","a → ∞ 時 I(a) → 0，而 arctan a → π/2，所以 C = π/2。I(a) = π/2 − arctan a，I(1) = π/2 − π/4 = π/4。"],"answer":"π/4"},{"title":"1/x² 卡住：參數放進 Gaussian","prompt":"∫₀^∞ (1 − e^{−x²})/x² dx","steps":["I(a) = ∫₀^∞ (1 − e^{−ax²})/x² dx（a ≥ 0），原題是 I(1)。","I′(a) = ∫₀^∞ x² e^{−ax²}/x² dx = ∫₀^∞ e^{−ax²} dx = (1/2)√(π/a)（〈Γ(1/2) = √π〉的縮放）。","積回去：I(a) = √(πa) + C；a = 0 時被積函數是 0，C = 0。","I(1) = √π。"],"answer":"√π","note":"交換條件：a ≥ a₀ > 0 時 e^{−ax²} ≤ e^{−a₀x²}，可積。"}],"pitfalls":["算出 I′(a) 就停了，忘了積回去。","積回去忘了 + C，或用一個 I 不知道的值去定 C。","參數放錯位置，微分之後沒有消掉難纏的因子。","沒檢查交換條件；尤其是 a = 0 這種邊界值，控制函數常常在那裡失效。"],"checks":[{"ask":"∫₀¹ (x³ − 1)/ln x dx 是？","options":[{"label":"ln 4","correct":true},{"label":"ln 3","why":"I(a) = ln(a + 1)，原題是 a = 3，所以是 ln(3 + 1)。"},{"label":"1/4","why":"那是 I′(3) = 1/(3 + 1)，還要積回去。"}]},{"ask":"I(a) = ∫₀^∞ e^{−ax} sin x/x dx 的積分常數，用哪個特殊值決定最方便？","options":[{"label":"a → ∞，因為 I(a) → 0","correct":true},{"label":"a = 0","why":"I(0) 就是 Dirichlet 積分，它的值正是我們還不知道的東西。"},{"label":"a = 1","why":"I(1) 是原題要求的值，不能拿來定常數。"}]},{"ask":"為什麼要在 sin x/x 前面乘上 e^{−ax}？","options":[{"label":"對 a 微分會生出 −x，把分母的 x 消掉；而且 a > 0 時積分絕對收斂","correct":true},{"label":"因為 e^{−ax} 讓 sin x/x 有初等反導函數","why":"e^{−ax} sin x/x 一樣沒有初等反導函數；有用的是微分之後的 −e^{−ax} sin x。"},{"label":"因為 a = 1 時剛好是原題，其他理由不重要","why":"放參數的目的是讓 ∂f/∂a 好積；只讓原題落在某個 a 上是不夠的。"}]},{"ask":"已知 I′(a) = 1/(a + 1)、I(0) = 0，I(a) 是？","options":[{"label":"ln(a + 1)","correct":true},{"label":"ln(a + 1) + 1","why":"代 a = 0 得 1，不滿足 I(0) = 0；常數應該是 0。"},{"label":"−1/(a + 1)²","why":"那是再微分一次；要的是積分。"}]}],"practice":[{"id":"world-041","core":true},{"id":"world-019","core":true},{"id":"world-064","core":true},{"id":"world-070","core":true},{"id":"dm-int-008"},{"id":"burst-boss-param-001"},{"id":"world-057","challenge":true,"note":"挑戰：令 I(a) = ∫₀^∞ ln(1 + a²x²)/(1 + x²) dx，I′(a) 用部分分式。"},{"id":"world-015","challenge":true,"note":"挑戰：令 I(a) = ∫₀¹ ln(1 + ax)/(1 + x²) dx，最後的常數用 a = 0。"}]},"feynman-trick-advanced":{"id":"feynman-trick-advanced","prerequisites":["feynman-trick-basic","first-order-linear","separation-of-variables","partial-fractions-quadratic"],"next":["frullani"],"related":["gamma-half","ibp-cyclic","residue-real-integrals"],"objectives":["I′(a) 算不出閉式、但能用 I(a) 本身表示時，解微分方程得到 I(a)（Gaussian 乘 cos 的例子）。","對 a 積分時需要輔助積分或巧妙換元的情況，能一步一步做完（∫₀^{π/2} ln(1 + a sin² x) dx）。","認出「積回去之後原積分又出現」的結構，移項解出答案（∫₀¹ ln(1 + x)/(1 + x²) dx）。"],"concept":[{"heading":"① 基礎版不夠用的三種情況","body":["〈Feynman 積分法：基礎〉的題目，I′(a) 都是一個能直接算出閉式的積分。進階題常卡在三個地方：","I′(a) 算不出來，但分部積分後又變回 I(a)：得到 I′ = (某個式子)·I，是一個微分方程。","I′(a) 算得出來，但對 a 積回去很難：需要一個輔助積分，加上一次換元。","積回去時，原本要求的積分又在另一邊出現：像〈重複分部與循環積分〉一樣移項。"]},{"heading":"② 微分方程型：I′ = −2a I","body":["I(t) = ∫₀^∞ e^{−x²} cos(2tx) dx。對 t 微分：I′(t) = −∫₀^∞ 2x e^{−x²} sin(2tx) dx（|∂f/∂t| ≤ 2x e^{−x²}，可積，可以交換）。","分部積分，u = sin(2tx)、dv = 2x e^{−x²} dx、v = −e^{−x²}：邊界項 [−e^{−x²} sin(2tx)]₀^∞ = 0，剩 2t ∫₀^∞ e^{−x²} cos(2tx) dx = 2t I(t)。","所以 I′(t) = −2t I(t)，分離變數得 I(t) = I(0) e^{−t²}，而 I(0) = √π/2。"],"tex":["\\int_0^{\\infty}e^{-x^{2}}\\cos(2tx)\\,dx=\\frac{\\sqrt{\\pi}}{2}\\,e^{-t^{2}}"]},{"heading":"③ 選參數的位置要「在 a = 0 時變簡單」","body":["定常數需要一個知道 I 值的 a。把參數放在「a = 0 時整個積分變成 0 或一個已知值」的位置：ln(1 + a sin² x) 在 a = 0 是 0；ln(1 + ax)/(1 + x²) 在 a = 0 也是 0。這比把參數放在別處（例如 ln(a + sin² x)）好用得多。"]},{"heading":"關於 ∫₀^∞ cos(tx)/(1 + x²) dx","body":["這個積分（Laplace 積分）等於 (π/2)e^{−|t|}，常被寫成「微分兩次得到 I″ = I」。但第二次微分時被積函數變成 −x² cos(tx)/(1 + x²)，找不到可積的控制函數，直接交換不合法。正確的做法要先把 x²/(1 + x²) 拆成 1 − 1/(1 + x²)，搭配 Dirichlet 積分處理；或者用〈用留數算實積分〉一行算完。"],"collapsible":true}],"workedExamples":[{"title":"微分方程型","prompt":"∫₀^∞ e^{−x²} cos(2x) dx","problemId":"world-037","steps":["I(t) = ∫₀^∞ e^{−x²} cos(2tx) dx，原題是 I(1)。","由 ②：I′(t) = −2t I(t)。","分離變數：dI/I = −2t dt，ln I = −t² + C，I(t) = I(0) e^{−t²}。I(0) = ∫₀^∞ e^{−x²} dx = √π/2。","I(1) = (√π/2) e^{−1} ≈ 0.3260。"],"answer":"√π/(2e)"},{"title":"積回去需要換元","prompt":"I(a) = ∫₀^{π/2} ln(1 + a sin² x) dx（a > −1）","problemId":"burst-boss-param-004","steps":["I′(a) = ∫₀^{π/2} sin² x/(1 + a sin² x) dx = (1/a)∫₀^{π/2} (1 − 1/(1 + a sin² x)) dx（a ≠ 0）。","輔助積分：上下同除以 cos² x、令 u = tan x，得 ∫₀^{π/2} dx/(1 + a sin² x) = ∫₀^∞ du/(1 + (1 + a)u²) = π/(2√(1 + a))。所以 I′(a) = (π/(2a))(1 − 1/√(1 + a))。","積回去（I(0) = 0）：I(a) = (π/2)∫₀^a (1/s)(1 − 1/√(1 + s)) ds。令 w = √(1 + s)，s = w² − 1，ds = 2w dw：(1/s)(1 − 1/w) · 2w = 2(w − 1)/(w² − 1) = 2/(w + 1)。","I(a) = (π/2) · 2[ln(w + 1)]₁^{√(1+a)} = π ln((1 + √(1 + a))/2)。"],"answer":"π ln((1 + √(1 + a))/2)"},{"title":"原積分又出現","prompt":"∫₀¹ ln(1 + x)/(1 + x²) dx","problemId":"world-015","steps":["I(a) = ∫₀¹ ln(1 + ax)/(1 + x²) dx，I(0) = 0，原題是 I(1)。","I′(a) = ∫₀¹ x/((1 + ax)(1 + x²)) dx。部分分式：x/((1 + ax)(1 + x²)) = (1/(1 + a²))[(x + a)/(1 + x²) − a/(1 + ax)]，積分得 I′(a) = (1/(1 + a²))[(ln 2)/2 + aπ/4 − ln(1 + a)]。","從 0 積到 1：I(1) = (ln 2/2)(π/4) + (π/4)(ln 2/2) − ∫₀¹ ln(1 + a)/(1 + a²) da。（∫₀¹ da/(1 + a²) = π/4，∫₀¹ a da/(1 + a²) = (ln 2)/2。）","最後一項正是 I(1) 本身：I(1) = (π ln 2)/4 − I(1)，所以 I(1) = (π ln 2)/8。"],"answer":"(π ln 2)/8"}],"pitfalls":["微分方程型忘了初值：I(t) = C e^{−t²} 的 C 要用 I(0) = √π/2 定。","部分分式拆錯，或積回去時漏了 1/(1 + a²) 這個因子。","原積分再出現時，把它當成「新的未知積分」繼續算，而不是移項。","第二次對參數微分時不檢查控制函數（Laplace 積分的陷阱）。"],"checks":[{"ask":"I′(t) = −2t I(t)，I(0) = √π/2，則 I(t) 是？","options":[{"label":"(√π/2) e^{−t²}","correct":true},{"label":"(√π/2) e^{−2t}","why":"∫ −2t dt = −t²，不是 −2t。"},{"label":"(√π/2)(1 − t²)","why":"那只是 e^{−t²} 的一階近似；解微分方程要用分離變數。"}]},{"ask":"∫₀^∞ e^{−x²} cos x dx 是？","options":[{"label":"(√π/2) e^{−1/4}","correct":true},{"label":"(√π/2) e^{−1}","why":"cos x = cos(2tx) 時 t = 1/2，e^{−t²} = e^{−1/4}。"},{"label":"(√π/2) e^{−1/2}","why":"指數是 −t²，t = 1/2 時是 −1/4，不是 −1/2。"}]},{"ask":"得到 I(1) = (π ln 2)/4 − I(1) 之後，I(1) 是？","options":[{"label":"(π ln 2)/8","correct":true},{"label":"(π ln 2)/4","why":"右邊還有 −I(1)，要移到左邊變成 2I(1)。"},{"label":"0","why":"這不是 I(1) = I(1) 的恆等式；移項後 2I(1) = (π ln 2)/4。"}]},{"ask":"I(t) = ∫₀^∞ e^{−x²} cos(2tx) dx 可以對 t 微分搬進積分號，理由是？","options":[{"label":"|∂f/∂t| = |−2x e^{−x²} sin(2tx)| ≤ 2x e^{−x²}，而後者在 [0, ∞) 可積","correct":true},{"label":"因為 cos 有界","why":"只看 f 有界不夠；要控制的是 ∂f/∂t，而且控制函數要可積。"},{"label":"微分與積分永遠可以交換","why":"不是：∫₀^∞ sin(tx)/x dx 對 t 微分就會出錯。"}]}],"practice":[{"id":"world-058","core":true},{"id":"world-037","core":true},{"id":"dm-int-006","core":true},{"id":"burst-boss-param-004","core":true},{"id":"world-015","core":true},{"id":"world-077"},{"id":"world-029"},{"id":"td-int-002","challenge":true,"note":"挑戰：令 I(b) = ∫₀^π ln(5 + b cos x) dx，I′(b) 的輔助積分是 ∫₀^π dx/(5 + b cos x)。"},{"id":"dm-int-009","challenge":true,"note":"挑戰：注意第二次微分不能直接搬進積分號（見可折疊段落）。"}]},"frullani":{"id":"frullani","prerequisites":["feynman-trick-basic","improper-conditional","mean-value-theorem"],"next":["gaussian-integral"],"related":["dirichlet-integral"],"objectives":["寫得出 Frullani 公式與條件：f 在 [0, ∞) 連續、f(∞) = lim_{x→∞} f(x) 存在，a、b > 0。","用「把區間的兩端各縮成一小段」的論證說明公式為什麼成立。","處理變形：f(∞) 不存在但 ∫^∞ f(u)/u du 收斂（cos）、積化和差（sin · sin）、arctan 與有理函數。"],"concept":[{"heading":"① 公式","body":["兩個同一個函數、不同縮放的版本相減，再除以 x，從 0 積到 ∞：答案只看 f 在兩端的值。","條件：f 在 [0, ∞) 上連續，f(∞) = lim_{x→∞} f(x) 存在（有限），a、b > 0。","符號檢查：f 遞減、b > a 時 f(ax) > f(bx)，被積函數為正；公式給 (f(0) − f(∞)) ln(b/a) > 0，一致。"],"tex":["\\int_0^{\\infty}\\frac{f(ax)-f(bx)}{x}\\,dx=\\bigl(f(0)-f(\\infty)\\bigr)\\ln\\frac{b}{a}"]},{"heading":"② 為什麼：中間抵銷，只剩兩端","body":["先積 [ε, R]。第一項令 u = ax、第二項令 u = bx，dx/x 都變成 du/u：∫_ε^R f(ax)/x dx = ∫_{aε}^{aR} f(u)/u du，∫_ε^R f(bx)/x dx = ∫_{bε}^{bR} f(u)/u du。","兩個積分的區間大部分重疊，重疊部分抵銷。剩下 ∫_{aε}^{bε} f(u)/u du − ∫_{aR}^{bR} f(u)/u du。","ε → 0 時第一段裡 f(u) ≈ f(0)，∫_{aε}^{bε} du/u = ln(b/a)，所以 → f(0) ln(b/a)。R → ∞ 時第二段裡 f(u) ≈ f(∞)，→ f(∞) ln(b/a)。相減得到公式。"]},{"heading":"③ 三種變形","body":["振盪：cos 在 ∞ 沒有極限，但 ∫_A^∞ cos u/u du 收斂（〈條件收斂的瑕積分〉），② 的第二段 ∫_{aR}^{bR} cos u/u du → 0，所以把 f(∞) 當 0：∫₀^∞ (cos ax − cos bx)/x dx = ln(b/a)。","積化和差：sin ax sin bx = (cos((a − b)x) − cos((a + b)x))/2（a > b > 0），所以 ∫₀^∞ sin ax sin bx/x dx = (1/2) ln((a + b)/(a − b))。","其他函數：f(t) = arctan t，f(0) = 0、f(∞) = π/2；f(t) = 1/(1 + t)，f(0) = 1、f(∞) = 0。"]},{"heading":"② 裡「f(u) ≈ f(0)」的嚴格版","body":["積分均值定理：f 連續、1/u > 0，所以存在 c ∈ [aε, bε]（設 a < b）使 ∫_{aε}^{bε} f(u)/u du = f(c) ln(b/a)。ε → 0 時 c → 0，f(c) → f(0)。∞ 那端同理，c ∈ [aR, bR]，f(c) → f(∞)。"],"collapsible":true}],"workedExamples":[{"title":"指數","prompt":"∫₀^∞ (e^{−2x} − e^{−5x})/x dx","problemId":"rel-boss-002","steps":["f(t) = e^{−t}，a = 2，b = 5。f 連續，f(0) = 1，f(∞) = 0。","(1 − 0) ln(5/2) = ln(5/2) ≈ 0.916。","用 Feynman 法也可以驗：對 b 微分得 ∫₀^∞ e^{−bx} dx = 1/b，積回去 ln b + C，b = a 時積分是 0。"],"answer":"ln(5/2)"},{"title":"arctan：f(0) 與 f(∞) 都要代","prompt":"∫₀^∞ (arctan 5x − arctan 2x)/x dx","problemId":"int-074","steps":["f(t) = arctan t，題目是 f(ax) − f(bx)，a = 5、b = 2。","f(0) = 0，f(∞) = π/2。","(0 − π/2) ln(2/5) = (π/2) ln(5/2) ≈ 1.439。符號檢查：arctan 遞增，arctan 5x > arctan 2x，答案應為正，一致。"],"answer":"(π/2) ln(5/2)"},{"title":"積化和差再套振盪版","prompt":"∫₀^∞ sin 3x sin 8x/x dx","problemId":"int-071","steps":["sin 3x sin 8x = (cos 5x − cos 11x)/2。","振盪版 Frullani：∫₀^∞ (cos 5x − cos 11x)/x dx = ln(11/5)。","乘上 1/2：(1/2) ln(11/5) ≈ 0.394。"],"answer":"(1/2) ln(11/5)"}],"pitfalls":["a、b 的順序搞反：公式是 f(ax) − f(bx) 對應 ln(b/a)。","只代 f(0)，忘了 f(∞)（arctan 的 f(∞) = π/2）。","f(∞) 不存在就直接放棄；cos 這類「∫^∞ f(u)/u du 收斂」的情況可以把 f(∞) 當 0。","把 f(ax) 與 f(bx) 拆成兩個積分分別算；兩個單獨都發散，合在一起才收斂。"],"checks":[{"ask":"∫₀^∞ (e^{−x} − e^{−4x})/x dx 是？","options":[{"label":"ln 4","correct":true},{"label":"ln(1/4)","why":"a = 1、b = 4，公式是 ln(b/a) = ln 4；e^{−x} > e^{−4x}，答案應為正。"},{"label":"3","why":"答案是係數比的對數，不是係數的差。"}]},{"ask":"Frullani 公式（標準版）需要 f 滿足？","options":[{"label":"在 [0, ∞) 連續，而且 lim_{x→∞} f(x) 存在","correct":true},{"label":"f(0) = 0","why":"f(0) 可以是任何數，它就是公式裡的係數之一。"},{"label":"f 是多項式","why":"非常數多項式在 ∞ 沒有有限極限，反而不能用。"}]},{"ask":"∫₀^∞ (cos 2x − cos 5x)/x dx 是？","options":[{"label":"ln(5/2)","correct":true},{"label":"不能用 Frullani，因為 cos 在 ∞ 沒有極限","why":"振盪版成立：∫_A^∞ cos u/u du 收斂，∞ 那端的貢獻 → 0，把 f(∞) 當 0。"},{"label":"ln(2/5)","why":"a = 2、b = 5，答案 (1 − 0) ln(5/2)；順序反了。"}]},{"ask":"∫₀^∞ (e^{−5x} − e^{−2x})/x dx 是？","options":[{"label":"ln(2/5)","correct":true},{"label":"ln(5/2)","why":"這題 a = 5、b = 2，ln(b/a) = ln(2/5)。e^{−5x} < e^{−2x}，被積函數為負，答案應為負。"},{"label":"0","why":"兩項不會抵銷：在 x 小的地方兩者差很多。"}]}],"practice":[{"id":"int-066","core":true},{"id":"cx-hi-008","core":true},{"id":"td-int-003","core":true},{"id":"int-075","core":true},{"id":"putnam-012","core":true},{"id":"int-069","core":true},{"id":"int-072","core":true},{"id":"int-065"},{"id":"rel-hard-int-008"},{"id":"int-076"},{"id":"rel-boss-003"},{"id":"td-int-004"},{"id":"px-int-001","challenge":true,"note":"挑戰：白話證明。照觀念 ② 的「中間抵銷、只剩兩端」寫。"}]},"gaussian-integral":{"id":"gaussian-integral","prerequisites":["gamma-half","feynman-trick-basic","leibniz-rule"],"next":["dirichlet-integral"],"related":["feynman-trick-advanced","gamma-half-integer"],"objectives":["背得出並推得出 ∫_{−∞}^∞ e^{−ax²} dx = √(π/a)（a > 0）。","用配方處理一般的 Gaussian ∫_{−∞}^∞ e^{−ax² + bx} dx = √(π/a) e^{b²/(4a)}。","用對 a 微分算動差 ∫ x^{2n} e^{−ax²} dx，並用奇偶性直接看出奇數動差是 0。"],"concept":[{"heading":"① 從標準形開始","body":["〈Γ(1/2) = √π〉用極座標算出 ∫_{−∞}^∞ e^{−x²} dx = √π。令 u = √a x 縮放，得到下面的公式。","e^{−x²} 有反導函數（例如 ∫₀ˣ e^{−t²} dt，統計裡寫成誤差函數 erf），但它不能寫成常見初等函數的有限組合；所以 Gaussian 積分只有在 (−∞, ∞) 或 [0, ∞) 這種特殊區間上才有漂亮的值。"],"tex":["\\int_{-\\infty}^{\\infty}e^{-a x^{2}}\\,dx=\\sqrt{\\frac{\\pi}{a}}\\qquad(a>0)"]},{"heading":"② 一次項：配方","body":["−ax² + bx = −a(x − b/(2a))² + b²/(4a)。平移不改變整條實數線上的積分，所以 ∫_{−∞}^∞ e^{−ax² + bx} dx = e^{b²/(4a)} √(π/a)。","圖像：加上 bx 只是把鐘往旁邊推、再整體放大 e^{b²/(4a)} 倍，寬度不變。"]},{"heading":"③ 動差：對 a 微分","body":["J(a) = ∫_{−∞}^∞ e^{−ax²} dx = √π a^{−1/2}。對 a 微分，被積函數多出 −x²（〈Leibniz 積分法則〉；a ≥ a₀ > 0 時 x² e^{−ax²} ≤ x² e^{−a₀x²}，可積）：","∫ x² e^{−ax²} dx = −J′(a) = (√π/2) a^{−3/2}；再微分一次：∫ x⁴ e^{−ax²} dx = J″(a) = (3√π/4) a^{−5/2}。","奇數次方：x^{2n+1} e^{−ax²} 是奇函數，在 (−∞, ∞) 上的積分是 0（積分本身絕對收斂，所以可以這樣說）。"]},{"heading":"跟 Gamma 的對照","body":["同樣的動差也可以用〈半整數的 Gamma〉的 ∫₀^∞ xᵐ e^{−x²} dx = (1/2)Γ((m + 1)/2) 算。兩種方法互相檢查：m = 4、a = 1 時，J″(1) = 3√π/4，而 2 · (1/2)Γ(5/2) = 3√π/4。"],"collapsible":true}],"workedExamples":[{"title":"配方","prompt":"∫_{−∞}^∞ e^{−x² + 2x} dx","steps":["−x² + 2x = −(x² − 2x + 1) + 1 = −(x − 1)² + 1。","∫_{−∞}^∞ e^{−(x−1)²} e¹ dx = e ∫_{−∞}^∞ e^{−u²} du（u = x − 1）。","= e√π ≈ 4.818。"],"answer":"√π e"},{"title":"四次動差","prompt":"∫_{−∞}^∞ x⁴ e^{−3x²} dx","problemId":"td-int-006","steps":["J(a) = √π a^{−1/2}，J″(a) = √π · (−1/2)(−3/2) a^{−5/2} = (3√π/4) a^{−5/2}，而 J″(a) = ∫ x⁴ e^{−ax²} dx（微分兩次，兩個 −x² 相乘是 +x⁴）。","a = 3：3^{−5/2} = 1/(9√3)。","(3√π/4) · 1/(9√3) = √π/(12√3) ≈ 0.0853。"],"answer":"√π/(12√3)"},{"title":"常態分布的變異數","prompt":"證明 (1/√(2π)) ∫_{−∞}^∞ x² e^{−x²/2} dx = 1。","steps":["a = 1/2：∫ x² e^{−ax²} dx = (√π/2) a^{−3/2} = (√π/2) · 2^{3/2} = √π · √2 = √(2π)。","除以 √(2π) 得 1。","所以標準常態分布的變異數是 1；同樣的計算給出總機率 (1/√(2π))√(π/(1/2)) = 1。"],"answer":"1"}],"pitfalls":["√(π/a) 寫成 √π/a。","∫₀^∞ 與 ∫_{−∞}^∞ 混用，差一個 2。","配方時常數項的正負號：−(x − 1)² + 1 的 +1 變成 e 的正次方。","對 a 微分時漏了負號：∫ x² e^{−ax²} dx = −J′(a)。"],"checks":[{"ask":"∫_{−∞}^∞ e^{−4x²} dx 是？","options":[{"label":"√π/2","correct":true},{"label":"√π/4","why":"那是 [0, ∞) 的值。√(π/4) = √π/2 才是整條實數線。"},{"label":"√(4π)","why":"a 在分母：√(π/a)。a 越大鐘越窄、面積越小。"}]},{"ask":"∫_{−∞}^∞ x³ e^{−x²} dx 是？","options":[{"label":"0","correct":true},{"label":"1","why":"那是 2∫₀^∞ x³ e^{−x²} dx；但 x³ e^{−x²} 是奇函數，左右兩半正負抵銷。"},{"label":"1/2","why":"1/2 是只從 0 積到 ∞ 的值。"}]},{"ask":"∫_{−∞}^∞ e^{−x² + 4x} dx 是？","options":[{"label":"√π e⁴","correct":true},{"label":"√π e²","why":"配方：−x² + 4x = −(x − 2)² + 4，常數是 4 = b²/(4a)，不是 2。"},{"label":"√π","why":"平移不改變面積，但配方多出來的常數 e⁴ 要乘上去。"}]},{"ask":"J(a) = ∫_{−∞}^∞ e^{−ax²} dx。用 −J′(a) 算 ∫ x² e^{−ax²} dx，交換微分與積分的理由是？","options":[{"label":"a ≥ a₀ > 0 時 |∂/∂a e^{−ax²}| = x² e^{−ax²} ≤ x² e^{−a₀x²}，可積","correct":true},{"label":"因為 e^{−ax²} 永遠是正的","why":"正值不夠；交換需要 ∂f/∂a 被一個可積函數控制。"},{"label":"因為區間是對稱的","why":"對稱性跟能不能交換微分與積分無關。"}]}],"practice":[{"id":"world-090","core":true},{"id":"burst-int-009","core":true},{"id":"td-int-006","core":true},{"id":"uni-int-018"},{"id":"hc-spec-006"},{"id":"dm-lim-012","challenge":true,"note":"挑戰：尾巴 ∫ₓ^∞ e^{−t²} dt 的漸近，用分部積分。"}]},"dirichlet-integral":{"id":"dirichlet-integral","prerequisites":["improper-conditional","feynman-trick-basic","parameter-integral"],"next":["log-sine-integral"],"related":["frullani","residue-real-integrals"],"objectives":["用 Feynman 法算出 ∫₀^∞ e^{−ax} sin x/x dx = π/2 − arctan a，並說得出讓 a → 0⁺ 為什麼需要額外論證。","用縮放、奇偶、積化和差，從 ∫₀^∞ sin x/x dx = π/2 推出 ∫₀^∞ sin(bx)/x dx = (π/2)·sgn b 等結果。","用分部積分把 sin² x/x²、(cos ax − cos bx)/x² 化回 Dirichlet 積分。"],"concept":[{"heading":"① 目標：一個條件收斂的積分的精確值","body":["〈條件收斂的瑕積分〉證明了 ∫₀^∞ sin x/x dx 收斂但不絕對收斂。sin x/x 沒有初等反導函數，值要靠別的方法。答案是 π/2。"],"tex":["\\int_0^{\\infty}\\frac{\\sin x}{x}\\,dx=\\frac{\\pi}{2}"]},{"heading":"② Feynman 法：先加阻尼，再拿掉","body":["〈Feynman 積分法：基礎〉算過：a > 0 時 I(a) = ∫₀^∞ e^{−ax} sin x/x dx = π/2 − arctan a。a > 0 時 e^{−ax} 讓一切都絕對收斂，交換微分與積分沒有問題。","要的是 I(0)。如果 I 在 a = 0 右連續，答案就是 lim_{a→0⁺}(π/2 − arctan a) = π/2。","這一步不能用控制函數：控制 e^{−ax}|sin x|/x 的最好函數是 |sin x|/x，它不可積。需要另一個論證（可折疊段落）。"]},{"heading":"I 在 0 右連續的證明","body":["把積分切成 [0, A] 與 [A, ∞)。[0, A] 上 e^{−ax} sin x/x 在閉矩形 [0, A] × [0, 1] 上連續（x = 0 處補值），〈參數積分〉的定理保證這一段對 a 連續。","尾巴：g(x) = e^{−ax}/x 在 [A, ∞) 上遞減到 0，而 |∫_A^B sin x dx| ≤ 2。用分部積分（Dirichlet 判別法的估計）得 |∫_A^∞ g(x) sin x dx| ≤ 2g(A) ≤ 2/A，對所有 a ≥ 0 一致成立。","所以 |I(a) − I(0)| ≤ |[0, A] 那段的差| + 4/A。先取 A 大讓 4/A < ε，再讓 a → 0⁺ 讓前一項 < ε。"],"collapsible":true},{"heading":"③ 一個值，變出很多個","body":["縮放：b > 0 時令 u = bx，sin(bx)/x dx = sin u/u du，值不變，還是 π/2；b < 0 時 sin 變號，得 −π/2。所以 ∫₀^∞ sin(bx)/x dx = (π/2)·sgn b。","奇偶：sin x/x 是偶函數，∫_{−∞}^∞ sin x/x dx = π。","分部積分：分母是 x² 時，分部一次讓分母降成 x，再回到 Dirichlet 積分。"]}],"workedExamples":[{"title":"Feynman 法的兩步","prompt":"用 I(a) = ∫₀^∞ e^{−ax} sin x/x dx 算 ∫₀^∞ sin x/x dx。","problemId":"world-088","steps":["a > 0：I′(a) = −∫₀^∞ e^{−ax} sin x dx = −1/(1 + a²)；a → ∞ 時 I → 0，所以 I(a) = π/2 − arctan a。","I 在 a = 0 右連續（可折疊段落的論證：前段用閉矩形連續，尾巴用 2/A 的一致估計）。","I(0) = lim_{a→0⁺} (π/2 − arctan a) = π/2。"],"answer":"π/2"},{"title":"縮放與積化和差","prompt":"∫₀^∞ sin 3x/x dx 與 ∫₀^∞ sin x cos x/x dx","problemId":"rel-boss-001","steps":["令 u = 3x：∫₀^∞ sin 3x/x dx = ∫₀^∞ sin u/u du = π/2。係數 3 不影響答案。","sin x cos x = (sin 2x)/2，所以第二個 = (1/2) · π/2 = π/4。"],"answer":"π/2 與 π/4"},{"title":"分部積分降分母","prompt":"∫₀^∞ sin² x/x² dx","problemId":"dm-int-001","steps":["u = sin² x、dv = dx/x²：du = 2 sin x cos x dx = sin 2x dx，v = −1/x。","邊界項 [−sin² x/x]₀^∞：x → ∞ 時 ≤ 1/x → 0；x → 0⁺ 時 sin² x/x ~ x → 0。所以是 0。","剩下 ∫₀^∞ sin 2x/x dx = π/2（縮放）。","所以 ∫₀^∞ sin² x/x² dx = π/2。注意原積分絕對收斂，分部之後變成條件收斂的積分。"],"answer":"π/2"}],"pitfalls":["以為 sin(bx)/x 的積分會變成 bπ/2；dx/x 在縮放下不變，答案還是 π/2（或 −π/2）。","用控制收斂讓 a → 0⁺：|sin x|/x 不可積，這一步需要專門的論證。","把 ∫_{−∞}^∞ sin x/x dx 當成 0（以為是奇函數）；sin x/x 是偶函數，值是 π。","分部積分後不檢查兩端的邊界項。"],"checks":[{"ask":"∫₀^∞ sin 5x/x dx 是？","options":[{"label":"π/2","correct":true},{"label":"5π/2","why":"令 u = 5x，sin 5x/x dx = sin u/u du，係數被吸收了。"},{"label":"π/10","why":"係數不會留在分母；dx/x 在縮放下不變。"}]},{"ask":"∫₀^∞ sin(−2x)/x dx 是？","options":[{"label":"−π/2","correct":true},{"label":"π/2","why":"sin(−2x) = −sin 2x，整個積分變號。"},{"label":"−π","why":"大小不受係數影響，還是 π/2，只是符號變負。"}]},{"ask":"用 I(a) = ∫₀^∞ e^{−ax} sin x/x dx 證明時，最需要小心的一步是？","options":[{"label":"證明 I 在 a = 0 右連續，因為找不到可積的控制函數","correct":true},{"label":"算 ∫₀^∞ e^{−ax} sin x dx","why":"那是標準積分（分部兩次），a > 0 時沒有任何收斂問題。"},{"label":"用 a → ∞ 定常數","why":"|I(a)| ≤ 1/a → 0 很直接；困難在另一端 a → 0⁺。"}]},{"ask":"∫_{−∞}^∞ sin x/x dx 是？","options":[{"label":"π","correct":true},{"label":"0","why":"sin x 與 x 都是奇函數，相除是偶函數，左右兩半相等，不會抵銷。"},{"label":"π/2","why":"那只是 [0, ∞) 的一半。"}]}],"practice":[{"id":"world-088","core":true},{"id":"rel-boss-001","core":true},{"id":"dm-int-001","core":true},{"id":"world-033","core":true},{"id":"world-089"},{"id":"world-070"},{"id":"world-038","challenge":true,"note":"挑戰：sin³ x = (3 sin x − sin 3x)/4，分部積分兩次。"},{"id":"world-047","challenge":true,"note":"挑戰：sin⁴ x 化成 cos 2x、cos 4x 的組合，分部積分三次。"}]},"log-sine-integral":{"id":"log-sine-integral","prerequisites":["improper-singular","trig-identities","u-sub-definite","integration-by-parts"],"next":["basel-problem"],"related":["wallis-integral"],"objectives":["說明 ∫₀^{π/2} ln(sin x) dx 為什麼收斂（x → 0 時 ln(sin x) ~ ln x）。","用「sin、cos 對稱 + 倍角 + 自己等於自己的一部分」算出 −(π/2) ln 2，每一步都說得出理由。","用分部積分或換元，把 x cot x、ln x/√(1 − x²) 這類積分化成它。"],"concept":[{"heading":"① 先確認它收斂","body":["ln(sin x) 在 x → 0⁺ 時 → −∞，是瑕積分。x → 0 時 sin x ~ x，所以 ln(sin x) − ln x = ln(sin x/x) → 0，被積函數的行為跟 ln x 一樣，而 ∫₀¹ ln x dx = −1 收斂（〈瑕積分 II：奇異點〉）。所以 I = ∫₀^{π/2} ln(sin x) dx 收斂，是一個負數。"]},{"heading":"② 三個對稱，讓 I 等於自己的一部分","body":["對稱一：令 x = π/2 − t，sin 變 cos，區間不變：∫₀^{π/2} ln(cos x) dx = I。","倍角：sin x cos x = (sin 2x)/2，所以 2I = ∫₀^{π/2} ln(sin x cos x) dx = ∫₀^{π/2} ln(sin 2x) dx − (π/2) ln 2。","對稱二：∫₀^{π/2} ln(sin 2x) dx 令 u = 2x 變成 (1/2)∫₀^π ln(sin u) du；sin u 對 u = π/2 對稱，∫₀^π = 2I，所以這一項等於 I。","合起來：2I = I − (π/2) ln 2，I = −(π/2) ln 2 ≈ −1.0888。"],"tex":["\\int_0^{\\pi/2}\\ln(\\sin x)\\,dx=\\int_0^{\\pi/2}\\ln(\\cos x)\\,dx=-\\frac{\\pi}{2}\\ln 2"]},{"heading":"③ 為什麼可以這樣移項","body":["「2I = I − (π/2) ln 2，所以 I = …」要先知道 I 是一個有限的數；如果 I 發散，這種移項會得到荒謬的結論。這就是 ① 先證收斂的原因。","另外，拆成 ∫ ln(sin 2x) − ∫ ln 2 也要每一項都收斂；兩項確實都收斂。"]},{"heading":"相關的結果","body":["∫₀^π ln(sin x) dx = −π ln 2；∫₀^{π/2} ln(tan x) dx = 0（ln sin − ln cos，兩項相等）；用 x ↦ π − x 可得 ∫₀^π x ln(sin x) dx = (π/2)∫₀^π ln(sin x) dx = −(π²/2) ln 2。"],"collapsible":true}],"workedExamples":[{"title":"完整推導","prompt":"∫₀^{π/2} ln(sin x) dx","problemId":"burst-int-011","steps":["收斂：x → 0⁺ 時 ln(sin x) ~ ln x，可積。記值為 I。","x ↦ π/2 − x：∫₀^{π/2} ln(cos x) dx = I。相加：2I = ∫₀^{π/2} ln(sin 2x/2) dx = ∫₀^{π/2} ln(sin 2x) dx − (π/2) ln 2。","u = 2x：∫₀^{π/2} ln(sin 2x) dx = (1/2)∫₀^π ln(sin u) du = (1/2)(2I) = I。","2I = I − (π/2) ln 2，I = −(π/2) ln 2。"],"answer":"−(π/2) ln 2"},{"title":"分部積分化成 log-sine","prompt":"∫₀^{π/2} x cot x dx","problemId":"dm-int-003","steps":["u = x、dv = cot x dx，du = dx、v = ln(sin x)（0 < x < π/2 時 sin x > 0）。","邊界項 [x ln(sin x)]₀^{π/2}：x = π/2 時 ln 1 = 0；x → 0⁺ 時 x ln(sin x) ~ x ln x → 0。所以是 0。","剩下 −∫₀^{π/2} ln(sin x) dx = (π/2) ln 2 ≈ 1.0888。"],"answer":"(π/2) ln 2"},{"title":"換元化成 log-sine","prompt":"∫₀¹ ln x/√(1 − x²) dx","steps":["令 x = sin θ，dx = cos θ dθ，√(1 − x²) = cos θ（0 ≤ θ < π/2 時 cos θ > 0）。","x 從 0 到 1 對應 θ 從 0 到 π/2。積分變成 ∫₀^{π/2} ln(sin θ) dθ。","= −(π/2) ln 2。"],"answer":"−(π/2) ln 2"}],"pitfalls":["沒先證收斂就移項。","u = 2x 時漏了 1/2，或忘了區間變成 [0, π]。","把 ln(sin x cos x) 拆成 ln(sin 2x) + ln 2，正負號錯：sin x cos x = (sin 2x)/2，是減 ln 2。","∫₀^π 與 ∫₀^{π/2} 混用，差一個 2。"],"checks":[{"ask":"∫₀^π ln(sin x) dx 是？","options":[{"label":"−π ln 2","correct":true},{"label":"−(π/2) ln 2","why":"那是 [0, π/2] 的值；sin 對 π/2 對稱，[0, π] 是兩倍。"},{"label":"0","why":"ln(sin x) 在 (0, π) 上都 ≤ 0，積分是負的，不會抵銷成 0。"}]},{"ask":"∫₀^{π/2} ln(tan x) dx 是？","options":[{"label":"0","correct":true},{"label":"−π ln 2","why":"ln(tan x) = ln(sin x) − ln(cos x)，兩項積分相等，相減是 0。"},{"label":"發散","why":"兩端都是瑕點，但都像 ±ln x，可積；而且 ln(tan x) 對 π/4 反對稱。"}]},{"ask":"∫₀^{π/2} ln(sin x) dx 為什麼收斂？","options":[{"label":"x → 0⁺ 時 ln(sin x) 的行為跟 ln x 一樣，而 ∫₀¹ ln x dx 收斂","correct":true},{"label":"因為 ln(sin x) 在 [0, π/2] 上有界","why":"它在 x → 0⁺ 時 → −∞，無界。"},{"label":"因為區間長度有限","why":"區間有限不夠：∫₀¹ dx/x 區間也有限，但發散。"}]},{"ask":"推導中 2I = ∫₀^{π/2} ln(sin x cos x) dx 之後，下一步是把 sin x cos x 寫成？","options":[{"label":"(sin 2x)/2","correct":true},{"label":"sin 2x","why":"sin 2x = 2 sin x cos x，所以 sin x cos x 是它的一半，會多出 −ln 2。"},{"label":"(1 − cos 2x)/2","why":"那是 sin² x 的半角公式，不是 sin x cos x。"}]}],"practice":[{"id":"burst-int-011","core":true},{"id":"rel-hard-int-017","core":true},{"id":"dm-int-003","core":true},{"id":"world-044","core":true},{"id":"burst-int-012","challenge":true,"note":"挑戰：(ln sin x)²，需要 Basel 值 π²/6 或 Fourier 級數。"},{"id":"burst-boss-int-015","challenge":true,"note":"挑戰：(ln tan x)²，令 u = tan x 變成 ∫₀^∞ (ln u)²/(1 + u²) du。"}]},"basel-problem":{"id":"basel-problem","prerequisites":["p-series","maclaurin-series","squeeze-theorem","partial-fractions-linear"],"next":["complex-numbers"],"related":["euler-formula","residue-theorem","euler-maclaurin-intro","gamma-scaled"],"objectives":["說得出 Euler 的論證（把 sin x/x 當成無窮次多項式分解），並說清楚它是直覺、漏了什麼。","從 Σ 1/n² = π²/6 推出奇數項和 π²/8、交錯和 π²/12。","把級數與積分互換，算出 ∫₀^∞ x/(eˣ − 1) dx、∫₀¹ ln(1 + x)/x dx 這類積分，並說出交換的理由。"],"concept":[{"heading":"① 問題","body":["〈p 級數〉說 Σ 1/n² 收斂（p = 2 > 1），但收斂到多少？部分和 1 + 1/4 + 1/9 + ⋯ 收斂得很慢，加一萬項還差約 10⁻⁴。答案是 π²/6，一個圓周率出現在只有整數的級數裡。"],"tex":["\\sum_{n=1}^{\\infty}\\frac{1}{n^{2}}=\\frac{\\pi^{2}}{6}"]},{"heading":"② Euler 的論證（直覺，不是證明）","body":["多項式可以用根分解。sin x/x 的根是 x = ±π, ±2π, ±3π, …，而且在 x = 0 的值是 1。Euler 大膽假設它可以像多項式一樣寫成 (1 − x²/π²)(1 − x²/(4π²))(1 − x²/(9π²))⋯。","比較 x² 的係數：右邊乘開，x² 項是 −(1/π²)(1 + 1/4 + 1/9 + ⋯)；左邊由 Maclaurin 級數 sin x/x = 1 − x²/6 + ⋯ 得 −1/6。兩邊相等就得到 Σ 1/n² = π²/6。","漏掉的是：無窮乘積是否收斂、是否真的等於 sin x/x（例如乘上 e^{x} 這種沒有根的因子，根完全不變），以及能不能逐項比較係數。這些都要複變的工具才能補齊。"]},{"heading":"一個初等的嚴格證明（Cauchy）","body":["0 < x < π/2 時 sin x < x < tan x，所以 cot² x < 1/x² < 1 + cot² x。取 x = kπ/(2m + 1)，k = 1, …, m，相加。","需要一個恆等式：Σ_{k=1}^m cot²(kπ/(2m + 1)) = m(2m − 1)/3（由 (cos θ + i sin θ)^{2m+1} 的虛部展開得到，見〈Euler 公式〉）。","得 m(2m − 1)/3 < ((2m + 1)/π)² Σ_{k≤m} 1/k² < m + m(2m − 1)/3。乘上 π²/(2m + 1)² 後兩邊都 → π²/6，由夾擠定理得證。"],"collapsible":true},{"heading":"③ 一個值，推出一串","body":["偶數項：Σ 1/(2n)² = (1/4) Σ 1/n² = π²/24。","奇數項：π²/6 − π²/24 = π²/8。","交錯：Σ (−1)^{n+1}/n² = 奇數項 − 偶數項 = π²/8 − π²/24 = π²/12。（這些重組合法，因為級數絕對收斂。）"]}],"workedExamples":[{"title":"奇數項與交錯和","prompt":"求 Σ_{n≥1} 1/(2n − 1)² 與 Σ_{n≥1} (−1)^{n+1}/n²。","problemId":"burst-boss-ser-004","steps":["偶數項 Σ 1/(2n)² = (1/4)(π²/6) = π²/24。","奇數項 = 全部 − 偶數項 = π²/6 − π²/24 = 3π²/24 = π²/8。","交錯和 = 奇數項 − 偶數項 = π²/8 − π²/24 = 2π²/24 = π²/12。"],"answer":"π²/8 與 π²/12"},{"title":"積分裡藏著 Basel","prompt":"∫₀^∞ x/(eˣ − 1) dx","problemId":"burst-int-026","steps":["x > 0 時 1/(eˣ − 1) = e^{−x}/(1 − e^{−x}) = Σ_{n≥1} e^{−nx}（幾何級數，公比 e^{−x} < 1）。","被積函數 = Σ_{n≥1} x e^{−nx}，每一項都非負，所以可以逐項積分（非負項的級數與積分可以交換，即單調收斂定理）。","∫₀^∞ x e^{−nx} dx = 1/n²（〈縮放的 Gamma 積分〉，Γ(2)/n²）。","總和 Σ 1/n² = π²/6。"],"answer":"π²/6"},{"title":"部分分式 + Basel","prompt":"Σ_{n≥1} 1/(n²(n + 1))","problemId":"world-075","steps":["部分分式：1/(n²(n + 1)) = 1/n² − 1/n + 1/(n + 1)。（通分檢查：(n + 1) − n(n + 1) + n² = 1。）","Σ (−1/n + 1/(n + 1)) 是望遠鏡級數，部分和 −1 + 1/(N + 1) → −1。","Σ 1/n² = π²/6。兩個收斂級數可以相加：總和 π²/6 − 1 ≈ 0.6449。"],"answer":"π²/6 − 1","note":"不能把 Σ 1/n² − Σ 1/n + Σ 1/(n + 1) 拆成三個級數：後兩個各自發散。要先把後兩項合成望遠鏡。"}],"pitfalls":["把 Euler 的乘積論證當成證明。","偶數項寫成 (1/2)·π²/6：(2n)² = 4n²，是 1/4。","部分分式後把發散的 Σ 1/n 單獨拆出來。","逐項積分不說理由；非負項或一致收斂才能交換。"],"checks":[{"ask":"1 + 1/9 + 1/25 + 1/49 + ⋯ 是？","options":[{"label":"π²/8","correct":true},{"label":"π²/12","why":"那是交錯和 1 − 1/4 + 1/9 − ⋯。奇數項和是 π²/6 − π²/24。"},{"label":"π²/24","why":"π²/24 是偶數項 1/4 + 1/16 + ⋯ 的和。"}]},{"ask":"1 − 1/4 + 1/9 − 1/16 + ⋯ 是？","options":[{"label":"π²/12","correct":true},{"label":"π²/6","why":"那是全部取正號的和；交錯和要減掉兩倍的偶數項。"},{"label":"ln 2","why":"ln 2 是 1 − 1/2 + 1/3 − ⋯（分母沒有平方）。"}]},{"ask":"Euler 用乘積 sin x/x = Π(1 − x²/(n²π²)) 的論證，問題在哪裡？","options":[{"label":"只知道兩邊根相同，沒證明乘積收斂而且真的等於 sin x/x","correct":true},{"label":"sin x/x 的 Maclaurin 級數算錯了","why":"sin x/x = 1 − x²/6 + ⋯ 是對的；問題在乘積那一邊。"},{"label":"答案 π²/6 是錯的","why":"答案對，論證不完整；嚴格證明（例如 Cauchy 的夾擠法）給出同樣的值。"}]},{"ask":"∫₀¹ ln(1 + x)/x dx 是？","options":[{"label":"π²/12","correct":true},{"label":"π²/6","why":"ln(1 + x)/x = 1 − x/2 + x²/3 − ⋯，逐項積分得 1 − 1/4 + 1/9 − ⋯，是交錯和。"},{"label":"ln 2","why":"那是 ∫₀¹ dx/(1 + x)；這裡被積函數是 ln(1 + x)/x。"}]}],"practice":[{"id":"burst-boss-ser-004","core":true},{"id":"world-075","core":true},{"id":"depth-int-017","core":true},{"id":"burst-int-026","core":true},{"id":"burst-boss-int-010","core":true},{"id":"world-023"},{"id":"dm-int-002"},{"id":"dm-int-005"},{"id":"dm-int-007","challenge":true,"note":"挑戰：∫∫ dx dy/(1 − xy) 展成 Σ (xy)ⁿ⁻¹，逐項積分正好是 Σ 1/n²。"}]},"complex-numbers":{"id":"complex-numbers","prerequisites":["polynomial-rational","r2-r3"],"next":["complex-polar"],"related":["complex-roots"],"objectives":["會做複數的四則運算，除法用分母的共軛複數把分母變成實數。","把複數 a + bi 看成平面上的點 (a, b)：加法是向量相加，|z| 是到原點的距離。","用 z z̄ = |z|² 與實係數多項式的根成對出現，解判別式為負的二次方程式。"],"concept":[{"heading":"① 為什麼要 i","body":["x² + 1 = 0 在實數裡沒有解。引進一個新的數 i，規定 i² = −1，再允許它跟實數做加法與乘法，得到形如 z = a + bi（a、b 為實數）的數，叫複數。a 是實部 Re z，b 是虛部 Im z（虛部是實數 b，不是 bi）。","在〈複數根〉解 y″ + y = 0 時已經用過它；這一章把它當成一個完整的數系來研究。"]},{"heading":"② 運算：把 i 當成字母，最後用 i² = −1","body":["加減：實部與實部、虛部與虛部各自相加減。","乘法：(a + bi)(c + di) = ac + adi + bci + bd i² = (ac − bd) + (ad + bc)i。","i 的次方四個一循環：i¹ = i、i² = −1、i³ = −i、i⁴ = 1。"]},{"heading":"③ 共軛複數、絕對值與除法","body":["z = a + bi 的共軛複數是 z̄ = a − bi。關鍵恆等式：z z̄ = a² + b²，是一個非負實數，記作 |z|²。|z| = √(a² + b²) 就是點 (a, b) 到原點的距離。","除法：分子分母同乘分母的共軛複數，分母就變成實數 |w|²。例如 1/i = −i。","性質：|zw| = |z||w|，z + z̄ = 2 Re z，z − z̄ = 2i Im z，z = z̄ ⇔ z 是實數。"],"tex":["\\frac{z}{w}=\\frac{z\\,\\bar w}{w\\,\\bar w}=\\frac{z\\,\\bar w}{|w|^{2}}"]},{"heading":"④ 平面上的圖像","body":["a + bi ↔ 點 (a, b)：橫軸是實軸、縱軸是虛軸。加法就是向量相加（平行四邊形），共軛是對實軸的鏡射，|z − w| 是兩點距離。乘法的圖像（轉角度、伸縮長度）要等下一課的極式才看得清楚。"]},{"heading":"實係數多項式的根成對出現","body":["若 p(x) 的係數都是實數，對 p(z) = 0 兩邊取共軛：共軛複數對加法、乘法都「可以穿過」，而實係數的共軛是自己，所以 p(z̄) = 0。因此非實數的根一定成對 z、z̄ 出現；例如 x² − 2x + 5 = 0 的根是 1 ± 2i。"],"collapsible":true}],"workedExamples":[{"title":"乘法","prompt":"(2 + 3i)(1 − 2i)","steps":["展開：2 · 1 + 2 · (−2i) + 3i · 1 + 3i · (−2i) = 2 − 4i + 3i − 6i²。","i² = −1：−6i² = 6。","合併：(2 + 6) + (−4 + 3)i = 8 − i。"],"answer":"8 − i"},{"title":"除法","prompt":"(3 + 4i)/(1 − 2i)","steps":["分子分母同乘 1 + 2i（分母的共軛複數）。分母：(1 − 2i)(1 + 2i) = 1 + 4 = 5。","分子：(3 + 4i)(1 + 2i) = 3 + 6i + 4i + 8i² = −5 + 10i。","結果 (−5 + 10i)/5 = −1 + 2i。檢查：(−1 + 2i)(1 − 2i) = −1 + 2i + 2i − 4i² = 3 + 4i。"],"answer":"−1 + 2i"},{"title":"判別式為負的二次方程式","prompt":"解 z² − 2z + 5 = 0","steps":["公式解：z = (2 ± √(4 − 20))/2 = (2 ± √(−16))/2。","√(−16) = 4i（因為 (4i)² = −16），所以 z = (2 ± 4i)/2 = 1 ± 2i。","驗算 z = 1 + 2i：z² = 1 + 4i + 4i² = −3 + 4i；z² − 2z + 5 = (−3 + 4i) − (2 + 4i) + 5 = 0。"],"answer":"z = 1 ± 2i"}],"pitfalls":["把虛部寫成 bi；虛部是實數 b。","乘法忘了 i² = −1，留下 i² 或把它當成 1。","除法只乘分子、不乘分母，或乘的不是共軛複數。","|a + bi| 寫成 a + b 或 √(a² − b²)。"],"checks":[{"ask":"i²⁰²⁵ 是？","options":[{"label":"i","correct":true},{"label":"−1","why":"i 的次方四個一循環，2025 = 4 · 506 + 1，所以是 i¹ = i。"},{"label":"1","why":"只有指數是 4 的倍數時才是 1；2025 除以 4 餘 1。"}]},{"ask":"|3 − 4i| 是？","options":[{"label":"5","correct":true},{"label":"−1","why":"絕對值是距離 √(3² + (−4)²)，不是 3 + (−4)。"},{"label":"√7","why":"虛部也是平方後相加：9 + 16 = 25，不是 9 − 16 的絕對值。"}]},{"ask":"1/i 是？","options":[{"label":"−i","correct":true},{"label":"i","why":"i · i = −1，不是 1；同乘 −i（共軛複數）得 −i/1 = −i。"},{"label":"沒有定義","why":"只有 0 不能當分母；i ≠ 0，1/i 有定義。"}]},{"ask":"z z̄ 一定是？","options":[{"label":"非負實數 |z|²","correct":true},{"label":"純虛數","why":"(a + bi)(a − bi) = a² − (bi)² = a² + b²，虛部抵銷。"},{"label":"z²","why":"z̄ ≠ z（除非 z 是實數），所以 z z̄ 一般不等於 z²。"}]}],"practice":[{"id":"der-077","core":true},{"id":"der-078","core":true},{"id":"der-075"},{"id":"der-076"}]},"complex-polar":{"id":"complex-polar","prerequisites":["complex-numbers","polar-coordinates","trig-identities","inverse-trig"],"next":["euler-formula"],"related":[],"objectives":["把 z 寫成 r(cos θ + i sin θ)：r = |z|，θ 是輻角，而且依象限判斷 θ，不是只算 arctan(b/a)。","說出乘法的幾何意義：長度相乘、角度相加；並用 De Moivre 公式算 zⁿ。","求 n 次方根：n 個根平均分布在半徑 r^{1/n} 的圓上。"],"concept":[{"heading":"① 用長度和角度描述一個複數","body":["點 (a, b) 也可以用極座標描述（〈極座標〉）：r = √(a² + b²) = |z|，θ 是從正實軸逆時針量到它的角，叫輻角 arg z。於是 z = r(cos θ + i sin θ)。","輻角不唯一：θ 加上 2π 的整數倍是同一個點。常用的主值 Arg z 取在 (−π, π]。z = 0 沒有輻角。"]},{"heading":"② 角度要看象限","body":["tan θ = b/a 只決定角度到差 π：−1 + √3 i 與 1 − √3 i 的 b/a 都是 −√3，但一個在第二象限、一個在第四象限。arctan(b/a) 給的值在 (−π/2, π/2)，只有 a > 0 時才直接是輻角；a < 0 時要加或減 π。最可靠的做法：先畫點，看它在哪個象限，再找角度。"]},{"heading":"③ 乘法：長度相乘、角度相加","body":["z₁ = r₁(cos θ₁ + i sin θ₁)、z₂ = r₂(cos θ₂ + i sin θ₂)。乘開後用和角公式：實部 cos θ₁cos θ₂ − sin θ₁sin θ₂ = cos(θ₁ + θ₂)，虛部 sin θ₁cos θ₂ + cos θ₁sin θ₂ = sin(θ₁ + θ₂)。所以 z₁z₂ = r₁r₂(cos(θ₁ + θ₂) + i sin(θ₁ + θ₂))。","圖像：乘以 i（r = 1、θ = π/2）就是逆時針轉 90°。除法：長度相除、角度相減。","重複乘同一個數，得到 De Moivre 公式。"],"tex":["\\bigl(r(\\cos\\theta+i\\sin\\theta)\\bigr)^{n}=r^{n}\\bigl(\\cos n\\theta+i\\sin n\\theta\\bigr)"]},{"heading":"④ n 次方根","body":["解 wⁿ = r(cos θ + i sin θ)：長度 |w|ⁿ = r，所以 |w| = r^{1/n}；角度 nφ = θ + 2πk，所以 φ = (θ + 2πk)/n，k = 0, 1, …, n − 1。","k 取 n 個不同的值就得到 n 個不同的根，它們是半徑 r^{1/n} 的圓上正 n 邊形的頂點；k = n 又回到 k = 0 的根。"]}],"workedExamples":[{"title":"化成極式，注意象限","prompt":"把 −1 + √3 i 寫成極式。","steps":["r = √(1 + 3) = 2。","點 (−1, √3) 在第二象限。arctan(√3/(−1)) = −π/3 落在第四象限，不對；要加 π，得 θ = 2π/3。","−1 + √3 i = 2(cos(2π/3) + i sin(2π/3))。檢查：2 cos(2π/3) = −1，2 sin(2π/3) = √3。"],"answer":"2(cos(2π/3) + i sin(2π/3))"},{"title":"De Moivre 算高次方","prompt":"(1 + i)¹⁰","steps":["1 + i = √2 (cos(π/4) + i sin(π/4))。","十次方：(√2)¹⁰ = 2⁵ = 32，角度 10 · π/4 = 5π/2，跟 π/2 是同一個方向。","(1 + i)¹⁰ = 32(cos(π/2) + i sin(π/2)) = 32i。直接展開要十次乘法。"],"answer":"32i"},{"title":"三次方根","prompt":"解 w³ = 8i","steps":["8i = 8(cos(π/2) + i sin(π/2))。|w| = 8^{1/3} = 2。","角度 φ = (π/2 + 2πk)/3：k = 0, 1, 2 給 π/6、5π/6、3π/2。","三個根：2(cos(π/6) + i sin(π/6)) = √3 + i；2(cos(5π/6) + i sin(5π/6)) = −√3 + i；2(cos(3π/2) + i sin(3π/2)) = −2i。","驗算 (√3 + i)³ = 3√3 + 9i − 3√3 − i = 8i。三個根是正三角形的頂點。"],"answer":"√3 + i、−√3 + i、−2i"}],"pitfalls":["輻角直接用 arctan(b/a)，第二、三象限的點錯 π。","De Moivre 時長度沒有取 n 次方，只轉了角度。","n 次方根只寫出一個（k = 0），漏了其他 n − 1 個。","方根的角度寫成 θ/n + 2πk，而不是 (θ + 2πk)/n：前者只會得到同一個根。"],"checks":[{"ask":"−1 − i 的主輻角 Arg 是？","options":[{"label":"−3π/4","correct":true},{"label":"π/4","why":"arctan((−1)/(−1)) = π/4 是第一象限的角；點 (−1, −1) 在第三象限。"},{"label":"5π/4","why":"5π/4 也指向同一個點，但主值要在 (−π, π] 裡，所以是 −3π/4。"}]},{"ask":"乘以 i 在複數平面上的效果是？","options":[{"label":"繞原點逆時針轉 90°","correct":true},{"label":"對實軸鏡射","why":"那是取共軛複數。i 的長度 1、角度 π/2，乘它是旋轉。"},{"label":"往上平移 1","why":"那是加上 i。乘法是旋轉加伸縮。"}]},{"ask":"(cos(π/6) + i sin(π/6))⁶ 是？","options":[{"label":"−1","correct":true},{"label":"1","why":"角度 6 · π/6 = π，cos π + i sin π = −1。"},{"label":"i","why":"那是三次方的結果（角度 π/2）。"}]},{"ask":"z⁴ = 16 有幾個複數根？它們的長度是？","options":[{"label":"4 個，長度都是 2","correct":true},{"label":"2 個（±2），長度 2","why":"實數根只有 ±2，但還有 ±2i；n 次方程式有 n 個複數根。"},{"label":"4 個，長度是 16、4、2、1","why":"每個根的長度都是 16^{1/4} = 2，它們在同一個圓上。"}]}],"practice":[{"id":"der-078","core":true},{"id":"der-077"}]},"euler-formula":{"id":"euler-formula","prerequisites":["complex-polar","maclaurin-series","radius-of-convergence"],"next":["complex-functions"],"related":["complex-roots","ibp-cyclic","basel-problem"],"objectives":["從 eˣ、cos x、sin x 的 Maclaurin 級數推出 e^{iθ} = cos θ + i sin θ，並說清楚 e^{iθ} 是怎麼定義的。","用 cos θ = (e^{iθ} + e^{−iθ})/2、sin θ = (e^{iθ} − e^{−iθ})/(2i) 把三角函數換成指數。","用「取實部」算 ∫ e^{ax} cos bx dx 與 eˣ cos x 的高階導數，取代重複分部積分。"],"concept":[{"heading":"① 先問：e 的虛數次方是什麼意思","body":["e³ 是三個 e 相乘，e^{1/2} 是開根號，但 e^{i} 不能用「乘幾次」來理解。我們用級數來定義：對任何複數 z，e^z = 1 + z + z²/2! + z³/3! + ⋯。這個級數的收斂半徑是 ∞（跟實數時一樣用比值判別），所以對所有複數都有定義，而且 z 是實數時就是原來的 eˣ。"]},{"heading":"② 代入 z = iθ，分成實部與虛部","body":["i 的次方四個一循環：i⁰ = 1、i¹ = i、i² = −1、i³ = −i。所以 e^{iθ} = 1 + iθ − θ²/2! − iθ³/3! + θ⁴/4! + iθ⁵/5! − ⋯。","把沒有 i 的項收在一起：1 − θ²/2! + θ⁴/4! − ⋯ = cos θ；有 i 的項：θ − θ³/3! + θ⁵/5! − ⋯ = sin θ。（級數絕對收斂，重新分組合法。）"],"tex":["e^{i\\theta}=\\cos\\theta+i\\sin\\theta"]},{"heading":"③ 立刻得到的東西","body":["極式可以寫成 z = r e^{iθ}，上一課的「長度相乘、角度相加」變成指數律 e^{iα}e^{iβ} = e^{i(α+β)}。θ = π 時 e^{iπ} = −1。","把 θ 換成 −θ 得 e^{−iθ} = cos θ − i sin θ，兩式相加減：cos θ = (e^{iθ} + e^{−iθ})/2，sin θ = (e^{iθ} − e^{−iθ})/(2i)。三角恆等式變成指數的代數，例如 sin³ θ = (3 sin θ − sin 3θ)/4 可以直接展開 ((e^{iθ} − e^{−iθ})/(2i))³ 得到。"]},{"heading":"④ 微積分裡的用法：先算複數，最後取實部","body":["對實變數 x 與複數常數 c，d/dx e^{cx} = c e^{cx}（逐項微分級數）。所以 e^{ax} cos bx = Re e^{(a+ib)x}，它的反導函數就是 Re[e^{(a+ib)x}/(a + ib)]，不必做〈重複分部與循環積分〉。同理 n 階導數是 Re[(a + ib)ⁿ e^{(a+ib)x}]。"]},{"heading":"另一個證明：導數為零","body":["令 g(θ) = e^{−iθ}(cos θ + i sin θ)。g′(θ) = −i e^{−iθ}(cos θ + i sin θ) + e^{−iθ}(−sin θ + i cos θ) = e^{−iθ}(−i cos θ + sin θ − sin θ + i cos θ) = 0，而 g(0) = 1，所以 g ≡ 1，即 e^{iθ} = cos θ + i sin θ。這個證明用到 d/dθ e^{−iθ} = −i e^{−iθ}，它同樣來自級數逐項微分。"],"collapsible":true}],"workedExamples":[{"title":"取實部算積分","prompt":"∫ e^{2x} cos 3x dx","steps":["e^{2x} cos 3x = Re e^{(2+3i)x}。∫ e^{(2+3i)x} dx = e^{(2+3i)x}/(2 + 3i)。","1/(2 + 3i) = (2 − 3i)/13；e^{(2+3i)x} = e^{2x}(cos 3x + i sin 3x)。","相乘取實部：e^{2x}(2 cos 3x + 3 sin 3x)/13。","答案：e^{2x}(2 cos 3x + 3 sin 3x)/13 + C。微分檢查會回到 e^{2x} cos 3x。"],"answer":"e^{2x}(2 cos 3x + 3 sin 3x)/13 + C"},{"title":"高階導數","prompt":"d⁴/dx⁴ (eˣ cos x) 在 x = 0 的值","problemId":"world-024","steps":["eˣ cos x = Re e^{(1+i)x}，所以 n 階導數是 Re[(1 + i)ⁿ e^{(1+i)x}]。","1 + i = √2 e^{iπ/4}，(1 + i)ⁿ = 2^{n/2} e^{inπ/4}。所以 dⁿ/dxⁿ (eˣ cos x) = 2^{n/2} eˣ cos(x + nπ/4)。","n = 4、x = 0：4 · cos π = −4。"],"answer":"−4"},{"title":"三角恆等式","prompt":"用 Euler 公式證明 sin³ θ = (3 sin θ − sin 3θ)/4。","steps":["sin θ = (e^{iθ} − e^{−iθ})/(2i)，(2i)³ = −8i。","(e^{iθ} − e^{−iθ})³ = e^{3iθ} − 3e^{iθ} + 3e^{−iθ} − e^{−3iθ} = 2i sin 3θ − 3 · 2i sin θ。","除以 −8i：sin³ θ = (2i sin 3θ − 6i sin θ)/(−8i) = (3 sin θ − sin 3θ)/4。"],"answer":"sin³ θ = (3 sin θ − sin 3θ)/4"}],"pitfalls":["把 e^{iθ} 當成「e 乘 iθ 次」來理解；它是用級數定義的。","sin θ 的公式漏了分母的 i：(e^{iθ} − e^{−iθ})/(2i)。","取實部之前先把 1/(a + ib) 化成 (a − ib)/(a² + b²)，否則實部會取錯。","以為 e^{iθ} 的長度會隨 θ 變大；它永遠在單位圓上，|e^{iθ}| = 1。"],"checks":[{"ask":"e^{iπ/2} 是？","options":[{"label":"i","correct":true},{"label":"e^{π/2}","why":"指數是純虛數，結果在單位圓上：cos(π/2) + i sin(π/2) = i。"},{"label":"−1","why":"那是 e^{iπ}。"}]},{"ask":"cos θ 用指數表示是？","options":[{"label":"(e^{iθ} + e^{−iθ})/2","correct":true},{"label":"(e^{iθ} − e^{−iθ})/2","why":"相減會消掉 cos，剩 i sin θ；那是 i sin θ 的式子。"},{"label":"e^{iθ}","why":"e^{iθ} 是 cos θ + i sin θ，它的實部才是 cos θ。"}]},{"ask":"用複數算 ∫ eˣ sin x dx，應該取哪一個的虛部？","options":[{"label":"e^{(1+i)x}/(1 + i)","correct":true},{"label":"e^{(1+i)x}(1 + i)","why":"積分要除以 1 + i；乘以 1 + i 是微分。"},{"label":"e^{x}/(1 + i)","why":"sin x 要從 e^{ix} 來，指數裡必須有 i。"}]},{"ask":"|e^{iθ}| 是？","options":[{"label":"1","correct":true},{"label":"e^θ","why":"|e^{iθ}|² = cos² θ + sin² θ = 1；虛數的指數只轉角度，不改長度。"},{"label":"|θ|","why":"θ 是角度，不是長度。"}]}],"practice":[{"id":"world-024","core":true},{"id":"hd-006","core":true},{"id":"world-027","core":true},{"id":"burst-int-002","core":true},{"id":"burst-der-008"},{"id":"burst-der-010"},{"id":"burst-int-003"},{"id":"ode-h2-008"},{"id":"burst-boss-der-005","challenge":true,"note":"挑戰：eˣ cos 2x 的 16 階導數，(1 + 2i)¹⁶ 用極式算。"}]},"complex-functions":{"id":"complex-functions","prerequisites":["euler-formula","two-variable-functions","inverse-function"],"next":["complex-limit"],"related":["complex-polar"],"objectives":["把 w = f(z) 拆成實部與虛部 u(x, y) + i v(x, y)，並用「平面到平面的映射」來想像它。","算 e^z、z²、1/z 的實部虛部，說出 e^z 的週期 2πi 與它把直線送到哪裡。","說清楚 log z 為什麼有無窮多個值，以及主值 Log z = ln|z| + i Arg z 的定義與限制。"],"concept":[{"heading":"① 輸入是平面、輸出也是平面","body":["複變函數 w = f(z) 吃一個複數、吐一個複數。寫 z = x + iy，輸出也拆成實部與虛部：f(z) = u(x, y) + i v(x, y)，u、v 是兩個實數值的二變數函數（〈二變數函數〉）。","例：f(z) = z² = (x + iy)² = (x² − y²) + i(2xy)，所以 u = x² − y²、v = 2xy。","沒辦法畫成「圖形」（要四維），所以改成看映射：z 平面上的一條線、一個區域，被送到 w 平面的哪裡。"]},{"heading":"② 指數函數 e^z","body":["e^z = e^{x+iy} = eˣ · e^{iy} = eˣ(cos y + i sin y)。所以 |e^z| = eˣ（只看實部）、arg e^z = y（只看虛部）。","兩個跟實數不一樣的地方：e^z 有週期 2πi（e^{z+2πi} = e^z），而且可以是負數，例如 e^{iπ} = −1。但 e^z 永遠不是 0，因為 |e^z| = eˣ > 0。","映射：垂直線 x = c 變成半徑 e^c 的圓；水平線 y = c 變成角度 c 的射線。"]},{"heading":"③ 對數：反函數有無窮多個值","body":["因為 e^z 有週期 2πi，e^w = z 的解不只一個：w = ln|z| + i(arg z + 2πk)，k 是任意整數。所以 log z 是「多值」的。","選定一個值：主值 Log z = ln|z| + i Arg z，Arg z ∈ (−π, π]。代價是 Log 在負實軸上不連續（從上方靠近時虛部 → π，從下方靠近時 → −π），所以通常只在去掉 (−∞, 0] 的平面上使用。","連帶地，z^{1/2} = e^{(1/2) log z} 有兩個值、z^{1/3} 有三個值，跟〈極式〉的 n 次方根一致。"]},{"heading":"三角函數不再有界","body":["用 Euler 公式定義 cos z = (e^{iz} + e^{−iz})/2、sin z = (e^{iz} − e^{−iz})/(2i)。z = iy 時 cos(iy) = (e^{−y} + e^{y})/2 = cosh y，y → ∞ 時無界。一般地 |cos(x + iy)|² = cos² x + sinh² y，所以實數時的 |cos x| ≤ 1 在複數上不成立。"],"collapsible":true}],"workedExamples":[{"title":"z² 把直線送到哪裡","prompt":"f(z) = z²。垂直線 x = 1 的像是什麼曲線？","steps":["u = x² − y²、v = 2xy。x = 1 時 u = 1 − y²、v = 2y，y 是參數。","消去 y：y = v/2，u = 1 − v²/4。","像是開口向左的拋物線 u = 1 − v²/4。直線被彎成了拋物線。"],"answer":"拋物線 u = 1 − v²/4"},{"title":"解 e^z = −1","prompt":"求所有滿足 e^z = −1 的 z。","steps":["|e^z| = eˣ = |−1| = 1，所以 x = 0。","arg e^z = y 要是 −1 的輻角：y = π + 2πk。","z = i(π + 2πk) = (2k + 1)πi，k 為整數。有無窮多個解，相鄰的差 2πi，這就是週期。"],"answer":"z = (2k + 1)πi"},{"title":"主值對數","prompt":"Log(−1 − i)","steps":["|−1 − i| = √2，ln √2 = (ln 2)/2。","點 (−1, −1) 在第三象限，Arg = −3π/4（不是 arctan 1 = π/4）。","Log(−1 − i) = (ln 2)/2 − 3πi/4。所有的值是 (ln 2)/2 + i(−3π/4 + 2πk)。"],"answer":"(ln 2)/2 − 3πi/4"}],"pitfalls":["以為 e^z 一定是正實數；e^{iπ} = −1。","以為 log z 只有一個值；它差 2πi 的整數倍。","Log 的虛部用 arctan(y/x)，沒有判斷象限。","把實數的不等式（|sin x| ≤ 1、eˣ > 0 的「正」）直接搬到複數。"],"checks":[{"ask":"|e^{3 + 4i}| 是？","options":[{"label":"e³","correct":true},{"label":"e⁵","why":"|e^{x+iy}| = eˣ，只看實部；不是 e^{|3 + 4i|}。"},{"label":"e^{3}·4","why":"虛部只決定方向（角度），不影響長度。"}]},{"ask":"e^z 的週期是？","options":[{"label":"2πi","correct":true},{"label":"2π","why":"e^{z+2π} = e^{2π}e^z ≠ e^z。要加在虛部才是轉一圈。"},{"label":"沒有週期","why":"e^{2πi} = cos 2π + i sin 2π = 1，所以 e^{z+2πi} = e^z。"}]},{"ask":"z² 的實部 u(x, y) 是？","options":[{"label":"x² − y²","correct":true},{"label":"x² + y²","why":"(iy)² = −y²，不是 +y²；x² + y² 是 |z|²。"},{"label":"2xy","why":"2xy 是虛部 v。"}]},{"ask":"log(1) 的所有值是？","options":[{"label":"2πik，k 為整數","correct":true},{"label":"只有 0","why":"那是主值 Log 1。e^{2πik} = 1，所以每個 2πik 都是解。"},{"label":"沒有定義","why":"只有 log 0 沒有定義；1 ≠ 0。"}]}],"practice":[{"id":"der-075","core":true},{"id":"der-076","core":true}]},"complex-limit":{"id":"complex-limit","prerequisites":["complex-functions","multivariable-limit","path-test"],"next":["complex-differentiability"],"related":[],"objectives":["說得出 lim_{z→z₀} f(z) = L 的意思：|z − z₀| → 0 時 |f(z) − L| → 0，z 可以從任何方向靠近。","用實部、虛部分開算極限，並用「兩條路徑給出不同值」證明極限不存在。","處理 z → ∞ 的極限：比最高次項。"],"concept":[{"heading":"① 定義：距離換成絕對值","body":["跟實數一樣，lim_{z→z₀} f(z) = L 的意思是：只要 z 夠靠近 z₀（但不等於 z₀），f(z) 就能要多靠近 L 就多靠近 L。差別是「靠近」用的是複數的絕對值 |z − z₀|，也就是平面上的距離。","所以 z 可以從四面八方、沿任何曲線靠近 z₀，每一種方式都要得到同一個 L。這跟〈多變數極限〉完全一樣，不只左右兩邊。"]},{"heading":"② 實部、虛部分開算","body":["f = u + iv、L = a + ib 時，f(z) → L 若且唯若 u → a 而且 v → b。原因：|Re w| ≤ |w|、|Im w| ≤ |w|，而 |w| ≤ |Re w| + |Im w|。","所以極限定律（和、積、商、合成）跟實數一樣成立；多項式與分母不為 0 處的有理函數都可以直接代入，也就是連續。"]},{"heading":"③ 證明極限不存在：找兩條路徑","body":["f(z) = z̄/z 在 0 附近：沿實軸 z = x，z̄/z = 1；沿虛軸 z = iy，z̄/z = −iy/(iy) = −1。兩條路徑給出不同的值，所以極限不存在。","反過來，沿幾條路徑得到同一個值，不能證明極限存在；那需要估計 |f(z) − L|（〈路徑測試〉的同一個道理）。"]},{"heading":"④ z → ∞","body":["z → ∞ 的意思是 |z| → ∞，方向不限。有理函數比最高次項：(2z² + 1)/(z² − 3i) → 2。常用的事實：1/z → 0（z → ∞），因為 |1/z| = 1/|z|。"]}],"workedExamples":[{"title":"多項式直接代入","prompt":"lim_{z→1+i} z²","steps":["z² = (x² − y²) + i(2xy)，實部虛部都是 x、y 的多項式，連續。","代 x = 1、y = 1：實部 1 − 1 = 0，虛部 2。","極限是 2i，也就是 (1 + i)²。"],"answer":"2i"},{"title":"沿直線靠近，答案不同","prompt":"證明 lim_{z→0} z̄/z 不存在。","steps":["沿直線 y = mx 靠近 0：z = x(1 + im)，z̄ = x(1 − im)，z̄/z = (1 − im)/(1 + im)。","乘上分母的共軛複數：(1 − im)²/(1 + m²) = (1 − m² − 2im)/(1 + m²)，實部是 (1 − m²)/(1 + m²)。","m = 0 時實部 1；m = 2 時實部 −3/5。不同直線給出不同的值，極限不存在。"],"answer":"極限不存在"},{"title":"z → ∞","prompt":"lim_{z→∞} (2z² + 1)/(z² − 3i)","steps":["分子分母同除以 z²：(2 + 1/z²)/(1 − 3i/z²)。","z → ∞ 時 1/z² → 0（|1/z²| = 1/|z|² → 0），不論方向。","極限 (2 + 0)/(1 − 0) = 2。（沿實軸檢查：實部 (2x² + 1)x²/(x⁴ + 9) → 2，虛部 3(2x² + 1)/(x⁴ + 9) → 0。）"],"answer":"2"}],"pitfalls":["只沿實軸檢查就說極限存在。","以為「沿幾條直線都一樣」就證明了極限存在。","把 z → ∞ 當成「z 往正實數方向跑」。","實部、虛部只算一個。"],"checks":[{"ask":"lim_{z→0} z̄/z：","options":[{"label":"不存在","correct":true},{"label":"1","why":"沿實軸是 1，但沿虛軸是 −1；方向不同給出不同值。"},{"label":"0","why":"|z̄/z| = 1，值一直在單位圓上，不會 → 0。"}]},{"ask":"f = u + iv。lim f(z) = 3 − 2i 等價於？","options":[{"label":"u → 3 而且 v → −2","correct":true},{"label":"u → 3 而且 v → −2i","why":"虛部 v 是實數；L 的虛部是 −2，不是 −2i。"},{"label":"|f| → √13 就夠了","why":"長度對了，方向可能不對；例如 f 一直在半徑 √13 的圓上繞。"}]},{"ask":"沿實軸、虛軸、直線 y = x 三條路徑，f 都趨近 0。可以下結論嗎？","options":[{"label":"不行，還可能有別的路徑給出不同值","correct":true},{"label":"可以，三條路徑已經足夠","why":"路徑測試只能證明「不存在」；例如沿拋物線靠近可能得到別的值。"},{"label":"可以，因為複數只有實部與虛部兩個方向","why":"z 可以沿任何曲線靠近，不只兩個坐標方向。"}]},{"ask":"lim_{z→∞} 1/z 是？","options":[{"label":"0","correct":true},{"label":"不存在，因為方向不同","why":"|1/z| = 1/|z| → 0，跟方向無關。"},{"label":"∞","why":"那是 lim_{z→0} 1/z 的情形。"}]}],"practice":[{"id":"mob-limtrap-008","core":true}]},"complex-differentiability":{"id":"complex-differentiability","prerequisites":["complex-limit","derivative-definition","jacobian-geometry"],"next":["cauchy-riemann"],"related":[],"objectives":["寫得出 f′(z₀) = lim_{h→0} (f(z₀ + h) − f(z₀))/h，並說清楚 h 是複數、要從所有方向趨近。","用定義證明 z² 可微、z̄ 處處不可微、|z|² 只在 0 可微。","說出 f′(z₀) 的幾何意義：在 z₀ 附近，f 把小圖形旋轉 arg f′(z₀)、放大 |f′(z₀)| 倍。"],"concept":[{"heading":"① 定義跟實數長得一樣","body":["f′(z₀) = lim_{h→0} (f(z₀ + h) − f(z₀))/h。差別在 h 是複數：h 可以沿實軸、虛軸、任何方向趨近 0，差商都要趨近同一個複數。","這個要求比看起來嚴格得多。在 ℝ² 上可微（〈Jacobian 的幾何意義〉）只要求局部長得像一個 2×2 線性映射；複變可微要求這個線性映射是「乘以一個複數 f′(z₀)」，也就是旋轉加等比例縮放，不能拉成橢圓、不能鏡射。"]},{"heading":"② 例子：z² 可以，z̄ 不行","body":["f(z) = z²：((z + h)² − z²)/h = 2z + h → 2z，跟 h 的方向無關。所以 (z²)′ = 2z。","f(z) = z̄：差商是 h̄/h。h 沿實軸時 h̄/h = 1，沿虛軸時 h̄/h = −1，沒有極限。所以 z̄ 在每一點都不可微——雖然它的實部 x、虛部 −y 都是最平滑的函數。","f(z) = |z|² = z z̄：差商 = z̄ + z(h̄/h) + h̄。z ≠ 0 時中間那項跟方向有關，不可微；z = 0 時差商 = h̄ → 0，可微，f′(0) = 0。可微的點可以只有一個。"]},{"heading":"③ 運算法則照搬","body":["和、差、積、商、合成的微分法則，證明跟實數一字不差（只用到極限定律）。所以多項式處處可微、(zⁿ)′ = nz^{n−1}，有理函數在分母不為 0 處可微。e^z、sin z 的可微性下一課用 Cauchy–Riemann 方程確認。"]},{"heading":"④ 幾何：局部是旋轉加縮放","body":["f(z₀ + h) ≈ f(z₀) + f′(z₀)h。乘以 f′(z₀) = r e^{iφ} 就是轉 φ、放大 r 倍。所以 f′(z₀) ≠ 0 時，f 在 z₀ 附近保持兩條曲線的夾角（含方向），這叫保角。"]}],"workedExamples":[{"title":"z² 在 1 + i 的導數","prompt":"f(z) = z²，求 f′(1 + i)，並用實部虛部檢查。","steps":["(z²)′ = 2z，f′(1 + i) = 2 + 2i。","檢查：沿實軸方向的差商就是 ∂f/∂x = u_x + i v_x。u = x² − y²、v = 2xy。","在 (1, 1)：u_x = 2x = 2，v_x = 2y = 2，所以 f′ = 2 + 2i。一致。"],"answer":"2 + 2i"},{"title":"z̄ 的差商跟方向有關","prompt":"證明 f(z) = z̄ 在任何一點都不可微。","steps":["差商 (f(z + h) − f(z))/h = (z̄ + h̄ − z̄)/h = h̄/h，跟 z 無關。","沿直線 h = t(1 + im)（t 實數 → 0）：h̄/h = (1 − im)/(1 + im)，實部 (1 − m²)/(1 + m²)。","m = 0（實軸）得 1，m = 1 得 0。方向不同、值不同，極限不存在，所以處處不可微。"],"answer":"處處不可微"},{"title":"高次方","prompt":"f(z) = z⁴，求 Re f′(1 + i)。","problemId":"der-085","steps":["f′(z) = 4z³。(1 + i)² = 2i，(1 + i)³ = 2i(1 + i) = −2 + 2i。","f′(1 + i) = 4(−2 + 2i) = −8 + 8i，實部 −8。","用 u_x + i v_x 檢查：u = x⁴ − 6x²y² + y⁴、v = 4x³y − 4xy³；在 (1, 1)，u_x = 4 − 12 = −8，v_x = 12 − 4 = 8。"],"answer":"−8"}],"pitfalls":["只沿實軸算差商，就說可微。","以為實部虛部都光滑，f 就複變可微（z̄ 是反例）。","以為不可微的點一定很多，或可微的點一定成片（|z|² 只在 0 可微）。","(1 + i)³ 展開錯；先算 (1 + i)² = 2i 比較不會錯。"],"checks":[{"ask":"f(z) = z̄ 在哪些點複變可微？","options":[{"label":"沒有任何一點","correct":true},{"label":"處處可微，因為 x 與 −y 都可微","why":"實部虛部可微只保證 ℝ² 意義下可微；差商 h̄/h 沿不同方向是 1 或 −1。"},{"label":"只在 0","why":"差商 h̄/h 跟 z 無關，在 0 也一樣沒有極限。只在 0 可微的是 |z|²。"}]},{"ask":"(z³)′ 在 z = i 的值是？","options":[{"label":"−3","correct":true},{"label":"3","why":"3z² 在 z = i 是 3i² = −3。"},{"label":"3i","why":"要代 z² = i² = −1，不是 z = i。"}]},{"ask":"f′(z₀) = 2i 的幾何意義是？","options":[{"label":"在 z₀ 附近把小圖形逆時針轉 90°、放大 2 倍","correct":true},{"label":"往上平移 2","why":"導數描述的是局部的線性部分（乘法），不是平移。"},{"label":"在虛軸方向拉長 2 倍、實軸方向不變","why":"那種非等比例的拉伸不是複數乘法；複變可微要求各方向一樣伸縮。"}]},{"ask":"|z|² 在 z = 0 的導數是？","options":[{"label":"0","correct":true},{"label":"不存在","why":"在 0 的差商是 |h|²/h = h̄ → 0，有極限。只有 z ≠ 0 的點不可微。"},{"label":"2z̄","why":"|z|² 在 z ≠ 0 根本不可微；在 0 直接用定義算出 0。"}]}],"practice":[{"id":"der-085","core":true},{"id":"der-086"}]},"cauchy-riemann":{"id":"cauchy-riemann","prerequisites":["complex-differentiability","partial-derivatives","clairaut"],"next":["holomorphic"],"related":[],"objectives":["從「沿實軸與沿虛軸的差商要相等」推出 u_x = v_y、u_y = −v_x，以及 f′ = u_x + i v_x。","說清楚條件：CR 方程是可微的必要條件；加上偏導數連續才是充分條件。","用 CR 方程判斷可微的點、算 f′，並由實部 u 求出共軛調和函數 v。"],"concept":[{"heading":"① 兩個方向，兩個式子","body":["設 f = u + iv 在 z₀ 可微。讓 h 沿實軸趨近 0（h = t）：差商 → ∂f/∂x = u_x + i v_x。","讓 h 沿虛軸趨近 0（h = it）：差商 = (f(z₀ + it) − f(z₀))/(it) → (1/i)(u_y + i v_y) = v_y − i u_y。","可微時兩者都等於 f′(z₀)，比較實部與虛部就得到 Cauchy–Riemann 方程。"],"tex":["u_x=v_y,\\qquad u_y=-v_x,\\qquad f'(z_0)=u_x+i\\,v_x"]},{"heading":"② 必要與充分","body":["必要：可微 ⇒ CR 方程在那一點成立。所以只要 CR 不成立，就一定不可微。z̄ = x − iy：u_x = 1、v_y = −1，不相等，處處不可微。","反過來，只有 CR 成立還不夠（有偏導數存在、CR 成立、卻不可微的反例）。常用的充分條件：u、v 在 z₀ 附近有連續的一階偏導數，而且在 z₀ 滿足 CR，則 f 在 z₀ 可微。"]},{"heading":"③ 調和函數","body":["若 u、v 有連續二階偏導數（下一課會看到全純函數自動如此），由 CR：u_xx = v_yx、u_yy = −v_xy，而 v_xy = v_yx（〈Clairaut 定理〉），相加得 u_xx + u_yy = 0。u 是調和函數，v 也是。","反過來，給一個調和的 u，可以用 CR 解出 v（叫 u 的共軛調和函數），湊成一個全純函數 u + iv。"]},{"heading":"充分條件的證明骨架","body":["偏導數連續 ⇒ u、v 在 ℝ² 意義下可微：Δu = u_x a + u_y b + o(|h|)、Δv = v_x a + v_y b + o(|h|)（h = a + ib）。代入 CR（u_y = −v_x、v_y = u_x）：Δu + iΔv = (u_x + i v_x)(a + ib) + o(|h|)。除以 h，o(|h|)/h → 0，差商 → u_x + i v_x。"],"collapsible":true}],"workedExamples":[{"title":"e^z 處處可微","prompt":"用 CR 方程證明 e^z 處處可微，並求導數。","steps":["e^z = eˣ cos y + i eˣ sin y：u = eˣ cos y、v = eˣ sin y。","u_x = eˣ cos y、v_y = eˣ cos y，相等；u_y = −eˣ sin y、v_x = eˣ sin y，u_y = −v_x。","四個偏導數處處連續，所以 e^z 處處可微，f′ = u_x + i v_x = eˣ cos y + i eˣ sin y = e^z。"],"answer":"(e^z)′ = e^z"},{"title":"只在一條線上可微","prompt":"f(z) = x² + i y² 在哪些點可微？","steps":["u = x²、v = y²。u_x = 2x、v_y = 2y；u_y = 0、v_x = 0。","第二條 u_y = −v_x 永遠成立；第一條要 2x = 2y，也就是 y = x。","偏導數處處連續，所以 f 恰好在直線 y = x 上的點可微，其他點都不可微。"],"answer":"只在直線 y = x 上"},{"title":"求共軛調和函數","prompt":"u = x³ − 3xy²。找 v 使 u + iv 全純。","problemId":"der-088","steps":["先檢查調和：u_xx = 6x，u_yy = −6x，和為 0。","v_y = u_x = 3x² − 3y²，對 y 積分：v = 3x²y − y³ + g(x)。","v_x = 6xy + g′(x) 要等於 −u_y = 6xy，所以 g′ = 0，g 是常數。","v = 3x²y − y³ + C，u + iv = z³ + iC。"],"answer":"v = 3x²y − y³ + C"}],"pitfalls":["第二條方程的負號：u_y = −v_x。","把 CR 成立當成可微的充分條件，忘了偏導數連續的要求。","求共軛調和函數時，積分常數寫成常數 C，而不是 g(x)（另一個變數的函數），結果漏項。","f′ 寫成 u_x + i u_y；正確是 u_x + i v_x。"],"checks":[{"ask":"Cauchy–Riemann 方程是？","options":[{"label":"u_x = v_y，u_y = −v_x","correct":true},{"label":"u_x = v_x，u_y = v_y","why":"比較的是沿實軸 (u_x + iv_x) 與沿虛軸 (v_y − iu_y) 的差商，交叉相等。"},{"label":"u_x = −v_y，u_y = v_x","why":"負號放錯了：用 z² 檢查，u = x² − y²、v = 2xy，u_x = 2x = v_y。"}]},{"ask":"u = x² + y²、v = 0。f = u + iv 在哪裡可微？","options":[{"label":"只在 0","correct":true},{"label":"處處可微","why":"u_x = 2x 要等於 v_y = 0，只有 x = 0；u_y = 2y 要等於 −v_x = 0，只有 y = 0。"},{"label":"處處不可微","why":"在 0 兩條方程都成立，偏導數也連續，所以在 0 可微（這就是 |z|²）。"}]},{"ask":"f 在 z₀ 可微時，f′(z₀) 用 u、v 表示是？","options":[{"label":"u_x + i v_x","correct":true},{"label":"u_x + i u_y","why":"那是 u 的梯度寫成複數，不是 f′。沿實軸的差商是 ∂f/∂x = u_x + i v_x。"},{"label":"u_y + i v_y","why":"沿虛軸的差商要除以 i：(u_y + iv_y)/i = v_y − iu_y。"}]},{"ask":"u = x² − y² 是哪個全純函數的實部？","options":[{"label":"z²","correct":true},{"label":"|z|²","why":"|z|² = x² + y²，而且它不是全純函數。"},{"label":"z̄²","why":"z̄² 的實部也是 x² − y²，但 z̄² 不全純（虛部是 −2xy，不滿足 CR）。"}]}],"practice":[{"id":"der-079","core":true},{"id":"der-080","core":true},{"id":"der-088","core":true},{"id":"der-087"}]},"holomorphic":{"id":"holomorphic","prerequisites":["cauchy-riemann","complex-functions"],"next":["complex-curves"],"related":["cauchy-integral-formula","complex-taylor"],"objectives":["分清楚「在一點可微」與「在一點全純」：全純要求在那一點的某個鄰域裡每一點都可微。","判斷常見函數在哪裡全純：多項式、e^z 是整函數；有理函數去掉分母的零點；Log z 去掉 (−∞, 0]。","說得出全純函數跟實數可微函數最不一樣的地方：可微一次就自動無限次可微，而且能展成冪級數（後面的課證明）。"],"concept":[{"heading":"① 定義：在一整塊開集上可微","body":["f 在開集 D 上全純（holomorphic），是指 f 在 D 的每一點都複變可微。說 f 在 z₀ 全純，意思是 f 在 z₀ 的某個小圓盤裡處處可微。","所以 |z|² 在 0 可微，但在 0 不全純：0 的任何小圓盤裡都有它不可微的點。在全平面全純的函數叫整函數，例如多項式、e^z、sin z、cos z。"]},{"heading":"② 常見函數的全純範圍","body":["有理函數 p(z)/q(z)：在 q ≠ 0 的地方全純。1/(z² + 1) 在 ℂ 去掉 ±i 的地方全純，雖然在實數線上它處處光滑——它的「問題」藏在實數線外面。","Log z：在 ℂ 去掉負實軸與 0（記作 ℂ ∖ (−∞, 0]）上全純，導數 1/z。在負實軸上 Log 不連續，當然也不可微。","z̄、Re z、|z|：哪裡都不全純。"]},{"heading":"③ 為什麼值得一個名字：剛性","body":["實數函數可以可微一次但不能微兩次（例如 x|x|），也可以無限次可微卻不等於它的 Taylor 級數（e^{−1/x²} 在 0 的所有導數都是 0）。","全純函數完全不是這樣：只要在開集上可微一次，就自動無限次可微，而且在每一點附近等於它的冪級數（〈Cauchy 積分公式〉與〈複數上的 Taylor 級數〉會證明）。它在一小塊上的值，就決定了它在整個連通區域上的值。這種「一處決定全部」的剛性，是複變能拿來算實積分的根本原因。"]},{"heading":"預告：幾個因此成立的定理","body":["Liouville 定理：有界的整函數一定是常數（所以 sin z、cos z 在複數上無界）。最大模原理：非常數的全純函數，|f| 的最大值只會出現在區域的邊界。恆等定理：兩個全純函數若在一個有聚點的集合上相等，就處處相等。"],"collapsible":true}],"workedExamples":[{"title":"有理函數","prompt":"f(z) = 1/(z² + 1) 在哪裡全純？求 f′。","steps":["分母 z² + 1 = 0 ⇔ z = ±i。","在 ℂ ∖ {i, −i} 上，f 是兩個全純函數的商，分母不為 0，所以全純。","f′(z) = −2z/(z² + 1)²（除法法則照搬）。限制在實數線上就是熟悉的 d/dx (1/(x² + 1))。"],"answer":"ℂ ∖ {±i}；f′ = −2z/(z² + 1)²"},{"title":"主值對數","prompt":"證明 Log z 在右半平面 x > 0 上全純，導數是 1/z。","steps":["x > 0 時 Arg z = arctan(y/x)，Log z = (1/2)ln(x² + y²) + i arctan(y/x)。","u_x = x/(x² + y²)、v_y = (1/x)/(1 + y²/x²) = x/(x² + y²)，相等；u_y = y/(x² + y²)、v_x = −y/(x² + y²)，u_y = −v_x。","偏導數連續，所以全純。f′ = u_x + i v_x = (x − iy)/(x² + y²) = z̄/|z|² = 1/z。"],"answer":"(Log z)′ = 1/z"},{"title":"可微但不全純","prompt":"f(z) = |z|²：在 0 全純嗎？","steps":["u = x² + y²、v = 0。CR 要 u_x = 2x = v_y = 0 而且 u_y = 2y = −v_x = 0，只有 (0, 0) 成立。","所以 f 只在 0 一點可微。","全純要求一整個鄰域裡都可微；0 的任何小圓盤裡都有 x ≠ 0 的點，那裡不可微。所以 f 在 0 不全純，在任何地方都不全純。"],"answer":"不全純"}],"pitfalls":["把「在一點可微」當成「在一點全純」。","以為實數線上光滑的函數，延伸到複數就處處全純（1/(z² + 1) 在 ±i 出問題）。","把 Log z 用在負實軸上。","以為 sin z、cos z 跟實數時一樣有界。"],"checks":[{"ask":"下面哪一個是整函數（在全平面全純）？","options":[{"label":"e^{z²} + z³","correct":true},{"label":"1/z","why":"在 z = 0 沒有定義，只在 ℂ ∖ {0} 全純。"},{"label":"z z̄","why":"z z̄ = |z|²，只在 0 可微，哪裡都不全純。"}]},{"ask":"f(z) = 1/(z² + 4) 在哪裡全純？","options":[{"label":"ℂ ∖ {2i, −2i}","correct":true},{"label":"ℂ ∖ {2, −2}","why":"z² + 4 = 0 的根是 ±2i，不是 ±2。"},{"label":"整個 ℂ","why":"分母在 ±2i 是 0，f 在那裡沒有定義。"}]},{"ask":"f 在 z₀ 可微，能不能推出 f 在 z₀ 全純？","options":[{"label":"不能，全純要求 z₀ 附近每一點都可微","correct":true},{"label":"能，可微就是全純","why":"|z|² 在 0 可微，但在 0 附近其他點都不可微，所以不全純。"},{"label":"能，只要再加上 CR 方程","why":"可微已經蘊含 CR 在那一點成立；問題是其他點。"}]},{"ask":"跟實數函數比，全純函數最特別的性質是？","options":[{"label":"在開集上可微一次，就自動無限次可微","correct":true},{"label":"它們都是有界的","why":"相反：有界的整函數只有常數（Liouville），e^z、sin z 都無界。"},{"label":"它們都是多項式","why":"e^z、Log z 都不是多項式；它們只是「局部等於冪級數」。"}]}],"practice":[{"id":"der-080","core":true},{"id":"der-079","core":true},{"id":"der-087"}]},"complex-curves":{"id":"complex-curves","prerequisites":["holomorphic","parametric-curves","parametric-arc-length","euler-formula"],"next":["contour-integral"],"related":["green-theorem"],"objectives":["把平面曲線寫成複數值的參數式 z(t) = x(t) + i y(t)，特別是圓 z₀ + r e^{it} 與線段 z₁ + t(z₂ − z₁)。","知道 z′(t) = x′(t) + i y′(t) 是切向量，弧長是 ∫ |z′(t)| dt。","分清楚封閉、簡單、正向（逆時針，內部在左手邊），以及反向會發生什麼。"],"concept":[{"heading":"① 參數式就是複數值的函數","body":["〈參數曲線〉用 (x(t), y(t)) 描述平面曲線；在複平面上把它寫成一個複數 z(t) = x(t) + i y(t)，t ∈ [a, b]。","兩個最常用的：以 z₀ 為圓心、半徑 r 的圓，逆時針一圈是 z(t) = z₀ + r e^{it}，t ∈ [0, 2π]；從 z₁ 到 z₂ 的線段是 z(t) = z₁ + t(z₂ − z₁)，t ∈ [0, 1]。"]},{"heading":"② 導數、切向量、弧長","body":["z′(t) = x′(t) + i y′(t)，就是速度向量，指向曲線前進的方向。例：z(t) = e^{it} 時 z′(t) = i e^{it}，等於把位置轉 90°——圓周運動的速度永遠垂直半徑。","弧長 L = ∫ₐᵇ |z′(t)| dt = ∫ₐᵇ √(x′² + y′²) dt，跟〈參數式弧長〉一樣。","z′ 連續而且不為 0 的曲線叫光滑；有限段光滑曲線接起來叫分段光滑曲線（例如三角形的邊界），下一課的積分都在這種曲線上做。"]},{"heading":"③ 封閉、簡單、方向","body":["z(a) = z(b) 叫封閉；除了起點等於終點以外不自己相交叫簡單。簡單封閉曲線把平面分成內部與外部（Jordan 曲線定理，直覺明顯但證明不簡單）。","正向：沿曲線走時內部在左手邊，對圓來說就是逆時針。同一條曲線反著走記作 −C；下一課會看到，反向會讓積分變號。"]}],"workedExamples":[{"title":"寫出圓的參數式","prompt":"|z − 1| = 2，逆時針一圈。寫出參數式、切向量與周長。","steps":["圓心 1、半徑 2：z(t) = 1 + 2e^{it}，t ∈ [0, 2π]。","z′(t) = 2i e^{it}，|z′(t)| = 2。","周長 ∫₀^{2π} 2 dt = 4π。逆時針，所以是正向。"],"answer":"z(t) = 1 + 2e^{it}，周長 4π"},{"title":"線段","prompt":"從 1 到 i 的線段，寫出參數式與長度。","steps":["z(t) = 1 + t(i − 1) = (1 − t) + it，t ∈ [0, 1]。","z′(t) = −1 + i，|z′| = √2。","長度 √2，就是 1 與 i 的距離。"],"answer":"z(t) = (1 − t) + it，長度 √2"},{"title":"螺線的弧長","prompt":"z(t) = e^{(1+i)t}，t ∈ [0, 1] 的弧長","steps":["z′(t) = (1 + i)e^{(1+i)t}（〈Euler 公式〉：對 t 微分照常乘上係數）。","|z′(t)| = |1 + i| · |e^{t}e^{it}| = √2 eᵗ。","弧長 ∫₀¹ √2 eᵗ dt = √2(e − 1) ≈ 2.430。用實部虛部 x = eᵗ cos t、y = eᵗ sin t 直接算也一樣。"],"answer":"√2(e − 1)"}],"pitfalls":["圓的參數式寫成 z₀ + e^{it}，忘了乘半徑 r。","順時針寫成 e^{it}；順時針是 e^{−it}。","線段寫成 z₁ + t z₂，起點對、終點錯。","|z′(t)| 算成 |x′| + |y′|。"],"checks":[{"ask":"以 i 為圓心、半徑 3、逆時針一圈的參數式是？","options":[{"label":"z(t) = i + 3e^{it}，t ∈ [0, 2π]","correct":true},{"label":"z(t) = 3i e^{it}","why":"那是以 0 為圓心、半徑 3 的圓（只是起點不同）；圓心要另外加上 i。"},{"label":"z(t) = i + 3e^{−it}","why":"e^{−it} 是順時針走。"}]},{"ask":"z(t) = e^{it} 的切向量 z′(t) 跟位置 z(t) 的關係是？","options":[{"label":"z′ = i z，也就是位置轉 90°","correct":true},{"label":"z′ = z","why":"對 t 微分 e^{it} 要乘上 i。"},{"label":"z′ = −z","why":"那是二階導數 z″ = i²z = −z（向心加速度）。"}]},{"ask":"單位圓順時針走一圈，是正向還是負向？","options":[{"label":"負向","correct":true},{"label":"正向","why":"正向是內部在左手邊；順時針走時圓的內部在右手邊。"},{"label":"圓沒有方向","why":"曲線本身的點集合沒有方向，但參數式有；積分會受方向影響。"}]},{"ask":"從 0 到 2 + 2i 的線段長度是？","options":[{"label":"2√2","correct":true},{"label":"4","why":"長度是 |z′| = |2 + 2i| = √8，不是 |2| + |2|。"},{"label":"√2","why":"√2 是 |1 + i|；這裡的位移是 2 + 2i。"}]}],"practice":[{"id":"cx-arc-003","core":true},{"id":"lec-10-q1c"}]},"contour-integral":{"id":"contour-integral","prerequisites":["complex-curves","work-line-integral","path-independence"],"next":["cauchy-theorem"],"related":["residue-real-integrals"],"objectives":["用定義 ∫_C f(z) dz = ∫ₐᵇ f(z(t)) z′(t) dt 把圍道積分化成實變數 t 的積分，並分開實部與虛部。","背熟並推得出 ∮_{|z−z₀|=r} (z − z₀)ⁿ dz：n = −1 時是 2πi，其他整數 n 都是 0。","知道有反導函數時積分只看端點（封閉曲線上是 0），並用 ML 不等式估計積分大小。"],"concept":[{"heading":"① 定義：把 dz 換成 z′(t) dt","body":["曲線 C 的參數式 z(t)，t ∈ [a, b]。定義 ∫_C f(z) dz = ∫ₐᵇ f(z(t)) z′(t) dt。右邊是實變數 t 的積分，被積函數是複數值，實部虛部分開積。","直覺：把曲線切成小段，每段乘上 f 的值再加起來，跟〈功的線積分〉同一個想法。事實上寫出實部虛部：∫_C f dz = ∫ (u dx − v dy) + i ∫ (v dx + u dy)，就是兩個實的線積分。"]},{"heading":"② 最重要的一個積分","body":["C：|z − z₀| = r 逆時針，z = z₀ + r e^{it}，dz = i r e^{it} dt。(z − z₀)ⁿ dz = i r^{n+1} e^{i(n+1)t} dt。","n = −1：被積函數是常數 i，積分 2πi。n ≠ −1：e^{i(n+1)t} = cos((n + 1)t) + i sin((n + 1)t) 在一整個週期上積分是 0。","這個結果跟 r 無關，後面的 Cauchy 積分公式與留數定理全都建立在它上面。"],"tex":["\\oint_{|z-z_0|=r}(z-z_0)^{n}\\,dz=\\begin{cases}2\\pi i,& n=-1\\\\ 0,& n\\neq-1\\end{cases}"]},{"heading":"③ 有反導函數就只看端點","body":["若 F′ = f 在一個包含 C 的開集上成立，則 ∫_C f dz = F(終點) − F(起點)（〈路徑無關〉的複數版）；封閉曲線上是 0。zⁿ（n ≠ −1）有反導函數 z^{n+1}/(n + 1)，所以 ② 的 0 不意外。","反過來：∮ dz/z = 2πi ≠ 0，所以 1/z 在 ℂ ∖ {0} 上沒有反導函數——log z 繞一圈會多出 2πi，接不起來。","沒有反導函數時，積分會跟路徑有關，例如 z̄（範例 2）。"]},{"heading":"④ 兩個基本性質","body":["反向變號：∫_{−C} f dz = −∫_C f dz。","ML 不等式：若 C 上 |f| ≤ M、C 長度 L，則 |∫_C f dz| ≤ ML。例如 |z| = R（R > 1）上 |z² + 1| ≥ R² − 1，所以 |∮ dz/(z² + 1)| ≤ 2πR/(R² − 1)，R → ∞ 時 → 0。這是〈用留數算實積分〉丟掉大半圓的工具。"]}],"workedExamples":[{"title":"圓上的 zⁿ","prompt":"∮_{|z|=1} dz/z 與 ∮_{|z|=1} z² dz","problemId":"der-084","steps":["z = e^{it}，dz = i e^{it} dt，t ∈ [0, 2π]。","dz/z = i dt，積分 ∫₀^{2π} i dt = 2πi。","z² dz = e^{2it} · i e^{it} dt = i e^{3it} dt = (−sin 3t + i cos 3t) dt，實部虛部在 [0, 2π] 上都積成 0。"],"answer":"2πi 與 0"},{"title":"沒有反導函數：跟路徑有關","prompt":"∫ z̄ dz 從 0 到 1 + i：(a) 沿線段；(b) 先到 1 再往上到 1 + i。","steps":["(a) z = (1 + i)t，z̄ = (1 − i)t，dz = (1 + i) dt。z̄ dz = (1 − i)(1 + i) t dt = 2t dt，積分 1。","(b) 第一段 z = t：∫₀¹ t dt = 1/2。第二段 z = 1 + it，z̄ = 1 − it，dz = i dt：(1 − it)i = t + i，積分 1/2 + i。","合計 1 + i ≠ 1。終點相同、路徑不同、答案不同：z̄ 沒有反導函數（它也不全純）。"],"answer":"(a) 1；(b) 1 + i"},{"title":"有反導函數：只看端點","prompt":"∫_C z² dz，C 是從 0 到 1 + i 的任何分段光滑曲線。","steps":["z² 的反導函數 z³/3 在全平面成立，所以答案 = (1 + i)³/3。","(1 + i)² = 2i，(1 + i)³ = 2i(1 + i) = −2 + 2i，答案 (−2 + 2i)/3。","檢查（走 0 → 1 → 1 + i）：第一段 ∫₀¹ t² dt = 1/3；第二段 (1 + it)² i = −2t + i(1 − t²)，積分 −1 + 2i/3。合計 −2/3 + 2i/3，一致。"],"answer":"(−2 + 2i)/3"}],"pitfalls":["dz 漏掉 z′(t)，直接寫 ∫ f(z(t)) dt。","∮ dz/z 算成 0（以為「繞一圈回到原點」就是 0）。","以為所有圍道積分都跟路徑無關；要有反導函數才是。","圓不是以原點為圓心時，參數式忘了加圓心。"],"checks":[{"ask":"∮_{|z−2|=5} dz/(z − 2)（逆時針）是？","options":[{"label":"2πi","correct":true},{"label":"10πi","why":"結果跟半徑無關：z − 2 = 5e^{it}，dz/(z − 2) = i dt。"},{"label":"0","why":"n = −1 是唯一不為 0 的情形；1/(z − 2) 在圓內沒有反導函數。"}]},{"ask":"∮_{|z|=1} z⁵ dz 是？","options":[{"label":"0","correct":true},{"label":"2πi","why":"只有 n = −1 才是 2πi；z⁵ 有反導函數 z⁶/6，封閉曲線上是 0。"},{"label":"2π/6","why":"反導函數在起點與終點的值相同，相減是 0。"}]},{"ask":"∫_C f dz 的定義（C：z(t)，t ∈ [a, b]）是？","options":[{"label":"∫ₐᵇ f(z(t)) z′(t) dt","correct":true},{"label":"∫ₐᵇ f(z(t)) dt","why":"漏了 dz = z′(t) dt；那是對參數 t 積分，結果會隨參數化方式改變。"},{"label":"∫ₐᵇ f(z(t)) |z′(t)| dt","why":"那是對弧長積分（純量線積分），不是 dz。"}]},{"ask":"反向走同一條曲線，∫ f dz 會？","options":[{"label":"變號","correct":true},{"label":"不變","why":"z′(t) 的方向全部反過來，每一小段 f Δz 都變號。"},{"label":"變成共軛複數","why":"反向只改變 dz 的方向，不會對 f 取共軛。"}]}],"practice":[{"id":"der-084","core":true}]},"cauchy-theorem":{"id":"cauchy-theorem","prerequisites":["contour-integral","green-theorem","cauchy-riemann"],"next":["cauchy-integral-formula"],"related":[],"objectives":["寫得出 Cauchy 定理的條件與結論：f 在簡單封閉曲線 C 上與 C 的內部全純，則 ∮_C f dz = 0。","用 Green 定理加上 CR 方程說明它為什麼成立（假設 f′ 連續）。","用「奇異點在不在曲線裡面」判斷積分是不是 0，並用變形曲線把複雜的圍道換成小圓。"],"concept":[{"heading":"① 結論：全純就繞一圈是 0","body":["Cauchy 定理：C 是簡單封閉的分段光滑曲線，f 在 C 上以及 C 的內部（某個包含它們的開集上）全純，則 ∮_C f dz = 0。","條件的重點是「內部沒有洞」：1/z 在單位圓上全純，但在內部的 0 不是，所以 ∮ dz/z = 2πi 不違反定理。"]},{"heading":"② 為什麼：Green 定理 + CR","body":["寫成實部虛部：∮ f dz = ∮ (u dx − v dy) + i ∮ (v dx + u dy)。","對兩個實線積分用〈Green 定理〉（假設 u、v 有連續偏導數）：第一個變成 ∬ (−v_x − u_y) dA，第二個變成 ∬ (u_x − v_y) dA。","CR 方程說 u_y = −v_x、u_x = v_y，兩個被積函數都是 0。所以 ∮ f dz = 0。","這個證明多假設了 f′ 連續；Goursat 證明了只要可微就夠，不需要這個假設。"]},{"heading":"③ 推論：路徑無關與變形","body":["路徑無關：在沒有洞的區域裡全純，從 a 到 b 的積分只看端點（兩條路徑合起來是一條封閉曲線，積分為 0）。","變形：f 在兩條封閉曲線 C₁、C₂ 之間的環形區域全純，則 ∮_{C₁} f dz = ∮_{C₂} f dz。所以繞著奇異點的任何曲線，都可以縮成一個小圓來算。這就是為什麼 ∮ dz/(z − z₀) 對任何繞 z₀ 一圈的曲線都是 2πi。"]},{"heading":"變形原理的證明","body":["在 C₁（外）與 C₂（內）之間切一刀，連成一條繞過環形區域邊界的封閉曲線：沿 C₁ 逆時針、沿切口進去、沿 C₂ 順時針、沿切口出來。這條曲線的內部不含奇異點，由 Cauchy 定理積分為 0；切口來回各走一次互相抵銷，剩下 ∮_{C₁} − ∮_{C₂} = 0。"],"collapsible":true}],"workedExamples":[{"title":"整函數","prompt":"∮_{|z|=1} e^{z²} dz","steps":["e^{z²} 是整函數，在單位圓及其內部全純。由 Cauchy 定理，積分是 0。","用參數式檢查：z = e^{it}，e^{z²} = e^{cos 2t}(cos(sin 2t) + i sin(sin 2t))，dz = (−sin t + i cos t) dt。","相乘後實部、虛部在 [0, 2π] 上的積分數值上都是 0。"],"answer":"0"},{"title":"奇異點在外面還是裡面","prompt":"∮ dz/(z − 3)，沿 |z| = 2 與 |z| = 4（逆時針）","steps":["1/(z − 3) 只在 z = 3 不全純。","|z| = 2：3 在圓外，函數在圓及其內部全純，積分 0。","|z| = 4：3 在圓內。由變形原理，換成繞 3 的小圓，∮ dz/(z − 3) = 2πi。","參數式檢查：|z| = 2 時虛部的被積函數化成 (4 − 6 cos t)/(13 − 12 cos t)，積分 0；|z| = 4 時是 (16 − 12 cos t)/(25 − 24 cos t)，積分 2π。"],"answer":"|z| = 2：0；|z| = 4：2πi"},{"title":"兩個奇異點，各自變形","prompt":"∮_{|z|=2} dz/(z² − 1)","steps":["奇異點 ±1 都在圓內，Cauchy 定理不能直接用。","部分分式：1/(z² − 1) = (1/2)(1/(z − 1) − 1/(z + 1))。","每一項各自變形成小圓：∮ dz/(z − 1) = 2πi、∮ dz/(z + 1) = 2πi。","結果 (1/2)(2πi − 2πi) = 0。注意：答案是 0，但不是因為 Cauchy 定理，而是兩個貢獻剛好抵銷。"],"answer":"0"}],"pitfalls":["只看曲線上全純，沒檢查內部有沒有奇異點。","反過來以為「積分是 0」就代表內部全純（範例 3）。","奇異點剛好在曲線上時也套定理；那時積分本身要另外定義。","變形時把曲線拉過奇異點；只能在全純的區域裡變形。"],"checks":[{"ask":"∮_{|z|=1} dz/(z − 2) 是？","options":[{"label":"0","correct":true},{"label":"2πi","why":"奇異點 z = 2 在單位圓外面；圓及其內部全純，Cauchy 定理給 0。"},{"label":"沒有定義","why":"被積函數在圓上連續，積分有定義。"}]},{"ask":"∮_{|z|=1} dz/z = 2πi ≠ 0，跟 Cauchy 定理矛盾嗎？","options":[{"label":"不矛盾：1/z 在圓的內部 z = 0 不全純，條件不成立","correct":true},{"label":"矛盾，所以 Cauchy 定理有例外","why":"定理要求內部全純；條件不成立時定理不說任何事。"},{"label":"不矛盾，因為 1/z 不連續","why":"1/z 在圓上連續；問題在內部的 0。"}]},{"ask":"用 Green 定理證明 Cauchy 定理時，哪一步用到 CR 方程？","options":[{"label":"讓 ∬(−v_x − u_y) 與 ∬(u_x − v_y) 的被積函數都等於 0","correct":true},{"label":"把 ∮ f dz 拆成實部虛部","why":"那只是代數展開，任何 f 都可以這樣拆。"},{"label":"把線積分換成二重積分","why":"那是 Green 定理本身，跟 CR 無關。"}]},{"ask":"C 是任意一條繞 z = 5i 一圈的正向簡單封閉曲線。∮_C dz/(z − 5i) 是？","options":[{"label":"2πi","correct":true},{"label":"要知道 C 的形狀才能算","why":"由變形原理，任何繞 5i 一圈的正向曲線都可以換成小圓，答案相同。"},{"label":"10πi","why":"答案跟奇異點的位置、曲線的大小都無關，永遠是 2πi。"}]}],"practice":[{"id":"der-084","core":true}]},"cauchy-integral-formula":{"id":"cauchy-integral-formula","prerequisites":["cauchy-theorem","contour-integral"],"next":["complex-taylor"],"related":["holomorphic"],"objectives":["寫得出 f(z₀) = (1/2πi)∮_C f(z)/(z − z₀) dz 與導數版 f⁽ⁿ⁾(z₀) = (n!/2πi)∮_C f(z)/(z − z₀)^{n+1} dz，以及條件。","用它算 ∮ g(z)/(z − z₀)ᵏ dz 型的圍道積分：先認出 f 與 z₀，再算 f 或它的導數。","說出它的後果：全純函數無限次可微、圓周平均等於圓心值。"],"concept":[{"heading":"① 公式：邊界上的值決定裡面的值","body":["f 在簡單封閉正向曲線 C 上與內部全純，z₀ 在 C 的內部，則下面的公式成立。","驚人之處：只要知道 f 在 C 上的值，就能算出 C 裡面每一點的值。實數函數完全沒有這種性質。"],"tex":["f(z_0)=\\frac{1}{2\\pi i}\\oint_C\\frac{f(z)}{z-z_0}\\,dz"]},{"heading":"② 為什麼：縮成小圓","body":["f(z)/(z − z₀) 只在 z₀ 不全純。由〈Cauchy 定理〉的變形原理，C 可以換成以 z₀ 為圓心、半徑 r 的小圓。","小圓上 f(z) ≈ f(z₀)，所以積分 ≈ f(z₀)∮ dz/(z − z₀) = 2πi f(z₀)。","嚴格化：積分減掉 2πi f(z₀) 等於 ∮ (f(z) − f(z₀))/(z − z₀) dz；f 連續，小圓上 |f(z) − f(z₀)| ≤ ε，ML 不等式給出這個差 ≤ (ε/r) · 2πr = 2πε。積分本身跟 r 無關，ε 任意小，所以差是 0。"]},{"heading":"③ 導數版：越微分次方越高","body":["對 z₀ 在積分號裡微分（被積函數在 C 上連續、對 z₀ 的導數也連續，可以交換），每微一次分母多一次方、前面多一個係數，n 次之後就是下面的式子。","後果：右邊對每個 n 都有意義，所以全純函數自動無限次可微——〈全純函數〉預告的剛性就是從這裡來的。"],"tex":["f^{(n)}(z_0)=\\frac{n!}{2\\pi i}\\oint_C\\frac{f(z)}{(z-z_0)^{n+1}}\\,dz"]},{"heading":"Liouville 定理與代數基本定理","body":["若整函數 |f| ≤ M，對以 z₀ 為圓心、半徑 R 的圓用 n = 1 的公式與 ML 不等式：|f′(z₀)| ≤ (1/2π)(M/R²)(2πR) = M/R → 0（R → ∞）。所以 f′ ≡ 0，f 是常數（Liouville）。","代數基本定理：若非常數多項式 p 沒有根，1/p 是整函數，而且 |z| → ∞ 時 |1/p| → 0，所以有界，由 Liouville 是常數，矛盾。所以每個非常數多項式都有複數根。"],"collapsible":true}],"workedExamples":[{"title":"直接套公式","prompt":"∮_{|z−1|=1} e^z/(z − 1) dz","steps":["f(z) = e^z 是整函數，z₀ = 1 在圓內。","積分 = 2πi f(1) = 2πie。","檢查（圓心平均）：z = 1 + e^{it} 時公式變成 f(1) = (1/2π)∫₀^{2π} f(1 + e^{it}) dt。實部 (1/2π)∫ e^{1+cos t} cos(sin t) dt = e，虛部的積分是 0。"],"answer":"2πie"},{"title":"分母要先拆出 f","prompt":"∮_{|z−i|=1} dz/(z² + 1)","steps":["z² + 1 = (z − i)(z + i)。圓 |z − i| = 1 只包住 i，不包住 −i（距離 2）。","寫成 [1/(z + i)]/(z − i)：f(z) = 1/(z + i) 在圓及其內部全純，z₀ = i。","積分 = 2πi f(i) = 2πi/(2i) = π。","檢查：f(i) = 1/(2i) 的虛部 −1/2 等於圓周平均；被積函數 1/(2i + e^{it}) 的虛部是 −(2 + sin t)/(5 + 4 sin t)，積分 −π。"],"answer":"π"},{"title":"導數版","prompt":"∮_{|z|=1} cos z/z³ dz","steps":["z³ = (z − 0)^{2+1}，所以 n = 2、z₀ = 0、f = cos z。","∮ f/z³ dz = (2πi/2!) f″(0)。f″(z) = −cos z，f″(0) = −1。","積分 = πi · (−1) = −πi。","檢查：z = e^{it} 時積分 = i∫₀^{2π} cos(e^{it}) e^{−2it} dt，裡面那個積分的實部數值上等於 −π。"],"answer":"−πi"}],"pitfalls":["導數版漏了 n!，或把 n 讀成分母的次方（分母是 n + 1 次方）。","沒有把不在圓內的因子留在 f 裡（範例 2 的 1/(z + i)）。","z₀ 在曲線外時也套公式；那時積分是 0（Cauchy 定理）。","忘了 2πi 的 i。"],"checks":[{"ask":"∮_{|z|=2} sin z/(z − 1) dz 是？","options":[{"label":"2πi sin 1","correct":true},{"label":"sin 1","why":"公式是 f(z₀) = (1/2πi)∮…，所以積分要乘回 2πi。"},{"label":"0","why":"z₀ = 1 在圓內，被積函數在 1 不全純，不能用 Cauchy 定理。"}]},{"ask":"∮_{|z|=1} e^{2z}/z² dz 是？","options":[{"label":"4πi","correct":true},{"label":"2πi","why":"分母是 z²，用 n = 1 的導數版：2πi f′(0)，f′(z) = 2e^{2z}，f′(0) = 2。"},{"label":"0","why":"0 在圓內，而且 f′(0) ≠ 0。"}]},{"ask":"∮_{|z|=1} e^z/(z − 3) dz 是？","options":[{"label":"0","correct":true},{"label":"2πie³","why":"z₀ = 3 在單位圓外，被積函數在圓及其內部全純，由 Cauchy 定理是 0。"},{"label":"2πi","why":"沒有任何奇異點在圓內。"}]},{"ask":"Cauchy 積分公式的導數版告訴我們什麼？","options":[{"label":"在開集上全純的函數，自動有任意階導數","correct":true},{"label":"全純函數的導數都是 0","why":"公式算的是 f⁽ⁿ⁾(z₀) 的值，一般不是 0。"},{"label":"只有多項式才有任意階導數","why":"e^z、sin z、1/z（在 0 以外）都有任意階導數。"}]}],"practice":[{"id":"der-084","core":true},{"id":"rel-hard-cpx-006"}]},"complex-taylor":{"id":"complex-taylor","prerequisites":["cauchy-integral-formula","taylor-series","radius-of-convergence","geometric-series"],"next":["laurent-series"],"related":["holomorphic","taylor-limits-higher"],"objectives":["說得出定理：f 在圓盤 |z − z₀| < R 上全純，則它在整個圓盤上等於自己的 Taylor 級數，係數 aₙ = f⁽ⁿ⁾(z₀)/n!。","用「收斂半徑 = 到最近奇異點的距離」直接讀出收斂半徑，包括實數函數的 Maclaurin 級數。","解釋 1/(1 + x²) 在實數線上處處光滑、Maclaurin 級數卻只在 |x| < 1 收斂的原因。"],"concept":[{"heading":"① 全純就能展開，而且展開到碰到奇異點為止","body":["定理：f 在 |z − z₀| < R 上全純，則 f(z) = Σ aₙ(z − z₀)ⁿ 對整個圓盤成立，aₙ = f⁽ⁿ⁾(z₀)/n!。","所以收斂半徑至少是「z₀ 到最近奇異點的距離」；而級數在收斂圓盤裡定義一個全純函數，不可能跨過奇異點，所以收斂半徑正好就是這個距離（f 在奇異點真的不能延伸時）。"]},{"heading":"② 解開實數的謎","body":["1/(1 + x²) = 1 − x² + x⁴ − ⋯ 只在 |x| < 1 收斂。在實數線上看，x = 1 一點特別的事都沒有：函數光滑、有界。","答案在複平面：1/(1 + z²) 在 z = ±i 有奇異點，到 0 的距離是 1。收斂圓盤是圓，它在實數線上的部分就是 (−1, 1)。實數上看不到的奇異點，控制了實數級數的收斂範圍。","同理，tan x 的 Maclaurin 級數收斂半徑是 π/2（cos z 在 ±π/2 為 0），eˣ、sin x 的半徑是 ∞（整函數）。"]},{"heading":"③ 實際算係數：借用已知的級數","body":["係數公式 f⁽ⁿ⁾(z₀)/n! 很少真的去微分。因為展開是唯一的（同一個圓盤上兩個冪級數相等，係數就逐項相等），任何方法得到的冪級數都是「那一個」Taylor 級數：代換（e^{z²} = Σ z^{2n}/n!）、幾何級數（1/(1 − z)）、相乘相除、逐項微分或積分，全部合法，而且在圓盤裡處處成立，不只在實數線上。"]},{"heading":"為什麼可以展開：幾何級數 + Cauchy 公式","body":["取 |z − z₀| < r < R，在圓 |w − z₀| = r 上用 Cauchy 積分公式 f(z) = (1/2πi)∮ f(w)/(w − z) dw。","把 1/(w − z) 寫成 (1/(w − z₀)) · 1/(1 − (z − z₀)/(w − z₀))，而 |(z − z₀)/(w − z₀)| < 1，展成〈幾何級數〉。級數在圓上一致收斂，可以逐項積分，每一項正好是 aₙ(z − z₀)ⁿ，aₙ = (1/2πi)∮ f(w)/(w − z₀)^{n+1} dw = f⁽ⁿ⁾(z₀)/n!。"],"collapsible":true}],"workedExamples":[{"title":"實數級數的收斂半徑","prompt":"1/(1 + x²) 的 Maclaurin 級數收斂半徑是多少？在 x = 0.5、0.9 檢查。","steps":["1/(1 + z²) 的奇異點在 z = ±i，到 0 的距離 1，所以半徑 1。","也可以從幾何級數看：1/(1 + x²) = Σ (−1)ⁿ x^{2n}，公比 −x²，|x| < 1 才收斂。","x = 0.5：Σ (−1)ⁿ 0.25ⁿ = 1/1.25 = 0.8；x = 0.9：和是 1/1.81。都在半徑內，跟函數值一致。"],"answer":"1"},{"title":"不在原點展開","prompt":"1/(z² + 4) 在 z₀ = 1 的 Taylor 級數收斂半徑","steps":["奇異點 z = ±2i。","距離 |1 − 2i| = √(1 + 4) = √5，|1 + 2i| = √5。","收斂半徑 √5。如果只看實數線（1/(x² + 4) 在實數上沒有奇異點），完全猜不到這個數。"],"answer":"√5"},{"title":"tan 的係數與半徑","prompt":"tan z 在 0 的 Taylor 級數：前三項與收斂半徑","steps":["tan z = sin z/cos z，奇異點是 cos z 的零點 ±π/2, ±3π/2, …（cos z 的零點全在實數線上）。最近的距離 π/2，所以半徑 π/2。","係數：用〈高階 Taylor 求極限〉的相除展開，tan z = z + z³/3 + 2z⁵/15 + ⋯。","檢查 z⁵ 的係數：lim (tan x − x − x³/3)/x⁵ = 2/15。"],"answer":"z + z³/3 + 2z⁵/15 + ⋯，半徑 π/2"}],"pitfalls":["只看實數線找奇異點，算錯收斂半徑。","不在原點展開時，距離算成 |奇異點| 而不是 |奇異點 − z₀|。","以為「無限次可微」就能等於 Taylor 級數；那只對全純函數保證，實數的 e^{−1/x²} 是反例。","收斂半徑內的端點行為：圓盤邊界上可能收斂也可能發散，定理不管邊界。"],"checks":[{"ask":"1/(1 + x²) 的 Maclaurin 級數只在 |x| < 1 收斂，原因是？","options":[{"label":"1/(1 + z²) 在 ±i 有奇異點，距離原點 1","correct":true},{"label":"1/(1 + x²) 在 x = 1 不可微","why":"它在實數線上處處無限次可微；限制來自複平面上的 ±i。"},{"label":"因為 x = 1 時分母等於 2","why":"分母不為 0 不構成任何限制；看的是複數的奇異點。"}]},{"ask":"1/(z − 3) 在 z₀ = i 的 Taylor 級數收斂半徑是？","options":[{"label":"√10","correct":true},{"label":"3","why":"3 是奇異點到原點的距離；展開中心是 i，距離是 |3 − i| = √10。"},{"label":"1","why":"1 是 |i|，跟奇異點無關。"}]},{"ask":"e^z 的 Maclaurin 級數收斂半徑是？","options":[{"label":"∞","correct":true},{"label":"1","why":"e^z 是整函數，沒有奇異點，半徑沒有上限。"},{"label":"2π","why":"週期 2πi 跟奇異點無關；e^z 處處全純。"}]},{"ask":"f 在 |z| < 2 全純，在 z = 2 有奇異點。它在 0 的 Taylor 級數在 z = 1 + i 收斂嗎？","options":[{"label":"收斂：|1 + i| = √2 < 2","correct":true},{"label":"發散：1 + i 不是實數","why":"收斂範圍是一個圓盤，不只實數線。"},{"label":"不能判斷","why":"定理保證整個 |z| < 2 都收斂，√2 < 2。"}]}],"practice":[{"id":"world-036","core":true},{"id":"td-ser-002"},{"id":"burst-boss-lim-001"}]},"laurent-series":{"id":"laurent-series","prerequisites":["complex-taylor","geometric-series","partial-fractions-linear"],"next":["singularities"],"related":["residue","contour-integral"],"objectives":["說得出 Laurent 級數：在環形區域 r < |z − z₀| < R 上全純的函數可以寫成 Σ_{n=−∞}^{∞} aₙ(z − z₀)ⁿ。","用已知級數（eᶻ、sin z、幾何級數）算 Laurent 展開，讀出 z^{−1} 的係數。","知道同一個函數在不同的環形區域有不同的 Laurent 展開，並會用 1/(1 − w) 往兩個方向展。"],"concept":[{"heading":"① 允許負次方","body":["Taylor 級數只有非負次方，所以只能描述在 z₀ 全純的函數。e^z/z³ 在 0 不全純，但把 e^z 展開再除以 z³：e^z/z³ = z^{−3} + z^{−2} + z^{−1}/2 + 1/6 + z/24 + ⋯。多了負次方，就能描述奇異點附近的行為。","一般定理：f 在環形區域 r < |z − z₀| < R 全純（r 可以是 0、R 可以是 ∞），則 f 在這個環上可以唯一地寫成雙向無窮級數 Σ aₙ(z − z₀)ⁿ。負次方的部分叫主要部分。"],"tex":["f(z)=\\sum_{n=-\\infty}^{\\infty}a_n(z-z_0)^n=\\underbrace{\\cdots+\\frac{a_{-2}}{(z-z_0)^2}+\\frac{a_{-1}}{z-z_0}}_{\\text{主要部分}}+a_0+a_1(z-z_0)+\\cdots"]},{"heading":"② 最重要的係數：a₋₁","body":["對以 z₀ 為圓心、落在環內的圓逐項積分，由〈圍道積分〉的 ∮ (z − z₀)ⁿ dz 只有 n = −1 時是 2πi，得到 ∮ f dz = 2πi a₋₁。整個級數只有 a₋₁ 活下來。下一課開始，這個係數叫留數。"]},{"heading":"③ 同一個函數，不同的環，不同的展開","body":["1/(z(1 − z)) = 1/z + 1/(1 − z)。","在 0 < |z| < 1：|z| < 1，1/(1 − z) = 1 + z + z² + ⋯，所以 f = 1/z + 1 + z + z² + ⋯。","在 |z| > 1：要讓幾何級數的公比小於 1，改寫 1/(1 − z) = −(1/z) · 1/(1 − 1/z) = −1/z − 1/z² − ⋯。於是 f = −1/z² − 1/z³ − ⋯。","兩個展開都對，只是各自在自己的環上成立。展開之前一定要先說在哪個環。"]},{"heading":"係數公式","body":["aₙ = (1/2πi)∮ f(z)/(z − z₀)^{n+1} dz（任何落在環內、繞 z₀ 一圈的正向圓）。證明跟〈複數上的 Taylor 級數〉一樣：在環的外圓與內圓上各用一次 Cauchy 公式，外圓那一項展成正次方、內圓那一項展成負次方。實際計算幾乎都用已知級數代換，不用這個公式。"],"collapsible":true}],"workedExamples":[{"title":"除以 z 的次方","prompt":"e^z/z³ 在 0 < |z| 上的 Laurent 級數，以及 z^{−1} 的係數","problemId":"der-083","steps":["e^z = 1 + z + z²/2 + z³/6 + ⋯ 對所有 z 成立。","除以 z³：z^{−3} + z^{−2} + z^{−1}/2 + 1/6 + z/24 + ⋯（z ≠ 0）。","z^{−1} 的係數 a₋₁ = 1/2。常數項 1/6 可以在實數線上檢查：lim_{x→0} (eˣ/x³ − 1/x³ − 1/x² − 1/(2x)) = 1/6。"],"answer":"a₋₁ = 1/2"},{"title":"兩個環，兩個展開","prompt":"1/(z(1 − z)) 在 0 < |z| < 1 與 |z| > 1 的 Laurent 級數","steps":["部分分式：1/(z(1 − z)) = 1/z + 1/(1 − z)。","0 < |z| < 1：1/z + Σ_{n≥0} zⁿ。檢查 z = 0.5：2 + 2 = 4 = 1/(0.5 · 0.5)。","|z| > 1：1/(1 − z) = −Σ_{n≥1} z^{−n}，加上 1/z 後 z^{−1} 項抵銷，f = −Σ_{n≥2} z^{−n}。檢查 z = 3：−(1/9 + 1/27 + ⋯) = −1/6 = 1/(3 · (−2))。"],"answer":"0 < |z| < 1：1/z + 1 + z + ⋯；|z| > 1：−1/z² − 1/z³ − ⋯"},{"title":"sin z/z⁴","prompt":"sin z/z⁴ 在 0 附近的 Laurent 級數與 a₋₁","problemId":"rel-hard-cpx-001","steps":["sin z = z − z³/6 + z⁵/120 − ⋯。","除以 z⁴：z^{−3} − z^{−1}/6 + z/120 − ⋯。","a₋₁ = −1/6。注意 z^{−2} 的係數是 0（sin 沒有偶次方項）。"],"answer":"a₋₁ = −1/6"}],"pitfalls":["不說明在哪個環上展開；|z| > 1 用了 |z| < 1 的幾何級數。","除以 zᵏ 時次方移錯：e^z 的 z³ 項除以 z³ 是常數，z² 項才變成 z^{−1}。","把「a₋₁」跟「主要部分的第一項」混淆；a₋₁ 永遠是 (z − z₀)^{−1} 的係數。","|z| > 1 的展開漏了 1/z 與 −1/z 的抵銷。"],"checks":[{"ask":"e^z/z² 在 0 附近的 Laurent 級數中，z^{−1} 的係數是？","options":[{"label":"1","correct":true},{"label":"1/2","why":"e^z 的 z¹ 項係數 1，除以 z² 變成 z^{−1}；1/2 是 z² 項，除完變常數。"},{"label":"0","why":"e^z 有 z¹ 項，除以 z² 後正好落在 z^{−1}。"}]},{"ask":"1/(1 − z) 在 |z| > 1 的展開是？","options":[{"label":"−1/z − 1/z² − 1/z³ − ⋯","correct":true},{"label":"1 + z + z² + ⋯","why":"那只在 |z| < 1 收斂；|z| > 1 時公比 z 的絕對值大於 1，發散。"},{"label":"1/z + 1/z² + ⋯","why":"改寫成 −(1/z)/(1 − 1/z) 時有一個負號。"}]},{"ask":"對一個落在環內、繞 z₀ 的正向圓，∮ f dz 等於？","options":[{"label":"2πi a₋₁","correct":true},{"label":"2πi a₀","why":"∮ (z − z₀)⁰ dz = 0；只有 n = −1 的那一項積分不為 0。"},{"label":"0","why":"f 在 z₀ 可能不全純，負一次方那一項會留下 2πi a₋₁。"}]},{"ask":"為什麼同一個函數可以有不同的 Laurent 級數？","options":[{"label":"不同的環形區域上展開不同；每個環上的展開是唯一的","correct":true},{"label":"因為 Laurent 級數不唯一，怎麼展都可以","why":"在同一個環上展開是唯一的；不同的是環。"},{"label":"因為計算方法不同（代換或微分）","why":"方法不同，在同一個環上的答案一定相同。"}]}],"practice":[{"id":"der-083","core":true},{"id":"rel-boss-009","core":true},{"id":"rel-hard-cpx-001","core":true},{"id":"rel-hard-cpx-002"},{"id":"der-082"}]},"singularities":{"id":"singularities","prerequisites":["laurent-series","discontinuity-types"],"next":["residue"],"related":["taylor-limits-higher"],"objectives":["用 Laurent 級數的主要部分把孤立奇異點分成三類：可去（沒有負次方）、m 階極點（最低到 (z − z₀)^{−m}）、本性（無窮多個負次方）。","不展開也能判斷：看 lim f 是否存在、(z − z₀)ᵐ f 的極限是否為有限非零，或用分子分母零點的階數相減。","知道本性奇異點附近 f 的行為極端：沿不同方向趨近，f 可以趨近 0、∞ 或任何值附近。"],"concept":[{"heading":"① 孤立奇異點：只有中間一個洞","body":["f 在 0 < |z − z₀| < r 全純、但在 z₀ 沒定義或不全純，z₀ 叫孤立奇異點。在這個去心圓盤上 f 有 Laurent 級數，分類就看主要部分（負次方）長什麼樣。","不是孤立的例子：Log z 在 0（負實軸整條都有問題）、1/sin(1/z) 在 0（奇異點 1/(kπ) 往 0 擠）。"]},{"heading":"② 三類","body":["可去：主要部分是 0。lim_{z→z₀} f 存在，補上這個值 f 就在 z₀ 全純。例：sin z/z、(1 − cos z)/z²。跟〈不連續的種類〉裡的可去不連續同一個想法。","m 階極點：主要部分有限，最低一項是 a₋ₘ/(z − z₀)ᵐ（a₋ₘ ≠ 0）。等價說法：(z − z₀)ᵐ f(z) → 有限非零的數。這時 |f| → ∞。例：1/(z − 1)² 在 1 是二階極點。","本性：主要部分有無窮多項。例：e^{1/z} = 1 + 1/z + 1/(2! z²) + ⋯ 在 0。"]},{"heading":"③ 快速判斷極點的階數","body":["f = g/h，g、h 在 z₀ 全純：若 h 在 z₀ 有 k 階零點、g 有 j 階零點（j 可以是 0），則 k > j 時是 (k − j) 階極點，k ≤ j 時是可去。零點的階數看 Taylor 展開的第一個非零項（〈高階 Taylor 求極限〉的技術）。","例：z/sin² z 在 0：sin² z = z² − ⋯ 是 2 階零點，分子 z 是 1 階，所以是 1 階極點。sin z/z⁴：分子 1 階、分母 4 階，3 階極點。"]},{"heading":"本性奇異點的極端行為","body":["Casorati–Weierstrass 定理：z₀ 是本性奇異點時，在 z₀ 的任何小去心圓盤裡，f 的值可以任意接近任何一個複數。（更強的 Picard 定理說：除了至多一個例外值，每個複數都會被取到無限多次。）e^{1/z} 從正實軸趨近 0 時 → ∞，從負實軸趨近時 → 0，沿虛軸時在單位圓上繞。"],"collapsible":true}],"workedExamples":[{"title":"可去奇異點","prompt":"判斷 (1 − cos z)/z² 在 0 的奇異點類型","steps":["1 − cos z = z²/2 − z⁴/24 + ⋯，除以 z²：1/2 − z²/24 + ⋯，沒有負次方。","所以是可去奇異點；補上 f(0) = 1/2，f 就在 0 全純。","等價檢查：lim_{z→0} (1 − cos z)/z² = 1/2 存在。"],"answer":"可去，補值 1/2"},{"title":"用零點階數判斷極點","prompt":"z/sin² z 在 0 是幾階極點？","problemId":"rel-hard-cpx-007","steps":["sin z = z − z³/6 + ⋯，sin² z = z² − ⋯，分母是 2 階零點；分子 z 是 1 階零點。","2 − 1 = 1，所以是 1 階（簡單）極點。","檢查：(z − 0)¹ · z/sin² z = z²/sin² z → 1，有限而且不為 0。"],"answer":"1 階極點"},{"title":"本性奇異點","prompt":"e^{1/z} 在 0 是哪一類？沿實軸兩側趨近時會怎樣？","steps":["e^{1/z} = Σ_{n≥0} 1/(n! zⁿ)，負次方有無窮多項：本性奇異點。","沿負實軸 z = x → 0⁻：1/x → −∞，e^{1/x} → 0。","沿正實軸 x → 0⁺：e^{1/x} → ∞，例如 x = 0.01 時 e^{100} ≈ 2.7 × 10⁴³。","兩個方向的極限一個是 0、一個是 ∞：既不是可去（極限不存在），也不是極點（|f| 沒有一致地 → ∞）。"],"answer":"本性奇異點"}],"pitfalls":["看到分母是 0 就說是極點；(1 − cos z)/z² 是可去。","極點階數只看分母的次方，忘了扣掉分子的零點（z/sin² z 是 1 階，不是 2 階）。","把「|f| → ∞」當成本性奇異點的特徵；那是極點的特徵。","把不孤立的奇異點（Log z 在 0）也拿來分類。"],"checks":[{"ask":"sin z/z 在 0 的奇異點是？","options":[{"label":"可去","correct":true},{"label":"1 階極點","why":"分子 sin z 在 0 也是 1 階零點，跟分母抵銷；sin z/z = 1 − z²/6 + ⋯，沒有負次方。"},{"label":"本性","why":"Laurent 級數根本沒有負次方，不可能是本性。"}]},{"ask":"sin z/z⁴ 在 0 是幾階極點？","options":[{"label":"3 階","correct":true},{"label":"4 階","why":"分子 sin z 在 0 有 1 階零點，4 − 1 = 3。"},{"label":"可去","why":"分母的零點階數比分子高，所以是極點。"}]},{"ask":"下列哪一個在 z = 0 是本性奇異點？","options":[{"label":"cos(1/z)","correct":true},{"label":"1/z⁵","why":"主要部分只有一項，是 5 階極點。"},{"label":"(e^z − 1)/z","why":"(e^z − 1)/z = 1 + z/2 + ⋯，可去。"}]},{"ask":"z₀ 是 m 階極點的等價說法是？","options":[{"label":"(z − z₀)ᵐ f(z) 趨近一個有限、非零的數","correct":true},{"label":"(z − z₀)ᵐ f(z) → 0","why":"那表示 m 取太大了；剛好的 m 會讓極限有限而且不為 0。"},{"label":"f(z) → ∞，而且 m 是分母的次方","why":"分子可能也有零點；階數要用 (z − z₀)ᵐ f 的極限或零點相減來定。"}]}],"practice":[{"id":"hc-der-007"},{"id":"rel-hard-cpx-007","core":true},{"id":"rel-boss-020"}]},"residue":{"id":"residue","prerequisites":["singularities","laurent-series","lhopital"],"next":["residue-theorem"],"related":["cauchy-integral-formula"],"objectives":["說得出留數的定義 Res_{z₀} f = a₋₁，以及它的意義：繞 z₀ 一小圈的積分除以 2πi。","用三個公式算留數：簡單極點 lim (z − z₀)f；f = g/h 型 g(z₀)/h′(z₀)；m 階極點的導數公式。","公式不好用時直接從 Laurent 級數讀 a₋₁；可去奇異點的留數是 0。"],"concept":[{"heading":"① 定義：Laurent 級數裡唯一留下來的係數","body":["z₀ 是 f 的孤立奇異點，f 在 0 < |z − z₀| < r 的 Laurent 級數是 Σ aₙ(z − z₀)ⁿ。定義 Res_{z₀} f = a₋₁。","名字的由來：繞 z₀ 一小圈積分，所有其他項都積成 0，只「留下」2πi a₋₁（〈Laurent 級數〉）。所以 Res_{z₀} f = (1/2πi)∮ f dz。","可去奇異點沒有負次方，留數是 0。"]},{"heading":"② 簡單極點的兩個公式","body":["z₀ 是簡單（1 階）極點：f = a₋₁/(z − z₀) + a₀ + ⋯，乘上 (z − z₀) 再取極限，Res = lim_{z→z₀} (z − z₀) f(z)。","f = g/h，g(z₀) ≠ 0，h 在 z₀ 是 1 階零點（h(z₀) = 0、h′(z₀) ≠ 0）：Res = g(z₀)/h′(z₀)。理由：(z − z₀)g/h = g/[(h(z) − h(z₀))/(z − z₀)] → g(z₀)/h′(z₀)。這個公式不用因式分解，最常用。"]},{"heading":"③ m 階極點","body":["(z − z₀)ᵐ f = a₋ₘ + ⋯ + a₋₁(z − z₀)^{m−1} + ⋯ 是全純的，a₋₁ 是它的第 m − 1 個 Taylor 係數，所以下面的公式成立。","m 大時微分很累，這時直接展開 Laurent 級數往往比較快，例如 e^z/z⁴ 的留數就是 e^z 的 z³ 係數 1/3! = 1/6。"],"tex":["\\operatorname{Res}_{z_0}f=\\frac{1}{(m-1)!}\\lim_{z\\to z_0}\\frac{d^{\\,m-1}}{dz^{\\,m-1}}\\Bigl[(z-z_0)^{m}f(z)\\Bigr]"]}],"workedExamples":[{"title":"簡單極點","prompt":"Res_{z=i} 1/(z² + 1)","problemId":"der-081","steps":["z² + 1 在 i 是 1 階零點，用 g/h′：g = 1，h′ = 2z。","Res = 1/(2i) = −i/2。","檢查：〈Cauchy 積分公式〉算過 ∮_{|z−i|=1} dz/(z² + 1) = π，而 π = 2πi · (1/(2i))。"],"answer":"1/(2i) = −i/2"},{"title":"高階極點：直接讀 Laurent 係數","prompt":"Res_{z=0} e^z/z⁴","problemId":"rel-boss-009","steps":["e^z/z⁴ = z^{−4}(1 + z + z²/2 + z³/6 + ⋯)，z^{−1} 項來自 z³/6。","Res = 1/6。","用導數公式也行（m = 4）：(1/3!) d³/dz³ e^z |₀ = 1/6，結果一樣。"],"answer":"1/6"},{"title":"二階極點：導數公式","prompt":"Res_{z=1} e^z/(z − 1)²","problemId":"rel-hard-cpx-006","steps":["z = 1 是 2 階極點（分子 e¹ ≠ 0）。","(z − 1)² f = e^z。公式 m = 2：Res = (1/1!) d/dz e^z |_{z=1} = e。","錯誤示範：用簡單極點的公式 lim (z − 1)f = lim e^z/(z − 1) 會發散——階數用錯了。"],"answer":"e"},{"title":"g/h′ 公式","prompt":"Res_{z=0} cot z","problemId":"rel-hard-cpx-008","steps":["cot z = cos z/sin z。sin z 在 0 是 1 階零點（sin 0 = 0、cos 0 = 1 ≠ 0），cos 0 = 1 ≠ 0。","Res = g(0)/h′(0) = cos 0/cos 0 = 1。","檢查：z cot z → 1。"],"answer":"1"}],"pitfalls":["對高階極點用簡單極點的公式。","m 階公式漏了 1/(m − 1)!，或微分次數用 m 而不是 m − 1。","g/h′ 公式用在 h 是 2 階零點的情況。","以為「分母為 0」的點留數一定不為 0；可去奇異點的留數是 0，有些極點的留數也剛好是 0（例如 1/z²）。"],"checks":[{"ask":"Res_{z=2i} 1/(z² + 4) 是？","options":[{"label":"1/(4i)","correct":true},{"label":"1/4","why":"h′(z) = 2z，在 z = 2i 是 4i，不是 4。"},{"label":"1/2","why":"用 g/h′：1/(2 · 2i) = 1/(4i)。"}]},{"ask":"Res_{z=0} sin z/z⁵ 是？","options":[{"label":"0","correct":true},{"label":"1/24","why":"z^{−1} 項要來自 sin z 的 z⁴ 項，但 sin z 只有奇次方，所以係數是 0。"},{"label":"1/120","why":"z⁵/120 除以 z⁵ 是常數項，不是 z^{−1} 項。"}]},{"ask":"Res_{z=0} 1/z² 是？","options":[{"label":"0","correct":true},{"label":"1","why":"1/z² 的 Laurent 級數只有 z^{−2} 一項，z^{−1} 的係數是 0。"},{"label":"不存在，因為是二階極點","why":"極點一定有留數；這裡剛好是 0。"}]},{"ask":"Res_{z=0} (e^{2z} − 1)/z³ 是？","options":[{"label":"2","correct":true},{"label":"4","why":"e^{2z} − 1 = 2z + 2z² + (4/3)z³ + ⋯，z² 項的係數是 (2z)²/2! 的 2，不是 4。"},{"label":"1/2","why":"z^{−1} 項來自分子的 z² 項，係數 2²/2! = 2。"}]}],"practice":[{"id":"rel-boss-009","core":true},{"id":"rel-boss-008","core":true},{"id":"rel-hard-cpx-006","core":true},{"id":"rel-hard-cpx-008","core":true},{"id":"rel-hard-cpx-005","core":true},{"id":"rel-hard-cpx-009","core":true},{"id":"rel-boss-020"},{"id":"rel-hard-cpx-002"},{"id":"rel-hard-cpx-003"},{"id":"rel-hard-cpx-004"},{"id":"der-081"},{"id":"der-082"},{"id":"rel-hard-cpx-007","challenge":true,"note":"挑戰：z/sin² z 在 0 是簡單極點，但分母是 2 階零點，g/h′ 不能直接用；改用 lim z · z/sin² z。"}]},"residue-theorem":{"id":"residue-theorem","prerequisites":["residue","cauchy-theorem"],"next":["residue-real-integrals"],"related":["cauchy-integral-formula"],"objectives":["寫得出留數定理與條件：∮_C f dz = 2πi Σ（C 內部所有奇異點的留數）。","說明它為什麼成立：把 C 變形成一個個繞奇異點的小圓，每個小圓貢獻 2πi 乘留數。","照步驟算圍道積分：找奇異點 → 判斷在不在 C 內 → 算留數 → 相加乘 2πi。"],"concept":[{"heading":"① 定理","body":["C 是正向的簡單封閉分段光滑曲線；f 在 C 上以及 C 的內部全純，只有有限個孤立奇異點 z₁, …, zₖ 例外，而且它們都不在 C 上。則：","內部沒有奇異點時，右邊是 0，就是〈Cauchy 定理〉；只有一個奇異點而且 f = g/(z − z₀)^{n+1} 時，就是〈Cauchy 積分公式〉。留數定理把兩者合成一條。"],"tex":["\\oint_C f(z)\\,dz=2\\pi i\\sum_{k}\\operatorname{Res}_{z_k}f"]},{"heading":"② 為什麼：每個洞各自貢獻","body":["在每個 zₖ 周圍畫一個小圓 Cₖ。在 C 與這些小圓之間的區域 f 全純，由變形原理（切開連成一條曲線，再用 Cauchy 定理），∮_C f dz = Σ ∮_{Cₖ} f dz。","每個小圓上把 f 展成 Laurent 級數，只有 a₋₁ 那一項積分不為 0，∮_{Cₖ} f dz = 2πi Res_{zₖ} f。相加就是定理。"]},{"heading":"③ 計算步驟","body":["1. 找出 f 的所有奇異點（分母的零點、e^{1/z} 這類）。","2. 只留下在 C 內部的。用距離判斷：|zₖ − 圓心| < 半徑。","3. 每個算留數（〈留數〉的三個公式或 Laurent 級數）。","4. 相加乘 2πi。曲線是順時針時再乘 −1。"]},{"heading":"④ 它把積分變成代數","body":["算一個圍道積分，原本要參數化、再積一個複雜的實積分；留數定理把它換成「在幾個點附近展開、讀一個係數」。下一課〈用留數算實積分〉反過來利用這件事：把一個難算的實積分，接上一段半圓或改寫成單位圓上的圍道積分，再用留數一次算完。"]},{"heading":"一個檢查：很大的圓","body":["若 f = p/q 是有理函數、而且 q 的次數比 p 至少高 2，則沿 |z| = R 的積分在 R → ∞ 時 → 0（ML 不等式：|f| 大約 C/R²，長度 2πR）。而 R 夠大時所有奇異點都在圓內，積分又等於 2πi 乘全部留數的和。所以這類函數全部留數的和一定是 0——範例 1 的 1/(z² + 1) 就是如此。算完可以用這個檢查。"],"collapsible":true}],"workedExamples":[{"title":"兩個留數互相抵銷","prompt":"∮_{|z|=2} dz/(z² + 1)","steps":["奇異點 ±i，|±i| = 1 < 2，都在圓內。","Res_i = 1/(2i)，Res_{−i} = 1/(−2i)（g/h′，h′ = 2z）。","和為 0，積分 = 2πi · 0 = 0。","參數式檢查：z = 2e^{it} 時實部與虛部的被積函數積分都是 0。"],"answer":"0"},{"title":"高階極點","prompt":"∮_{|z|=1} e^z/z³ dz","steps":["唯一的奇異點 0 在圓內，是 3 階極點。","Res = e^z 的 z² 係數 = 1/2。","積分 = 2πi · 1/2 = πi。","參數式檢查：z = e^{it}，積分 = i∫₀^{2π} e^{e^{it}} e^{−2it} dt，裡面的實部積分是 π。"],"answer":"πi"},{"title":"只有一部分奇異點在裡面","prompt":"∮_{|z|=2} z/((z − 1)(z − 3)) dz","steps":["奇異點 1 與 3。|1| < 2 在內，|3| > 2 在外，只算 z = 1。","z = 1 是簡單極點：Res = lim_{z→1} (z − 1)f = 1/(1 − 3) = −1/2。","積分 = 2πi · (−1/2) = −πi。（數值積分 z = 2e^{it} 也得到 −πi。）"],"answer":"−πi"}],"pitfalls":["把曲線外面的奇異點也算進去。","忘了乘 2πi，或只乘 2π。","奇異點剛好在曲線上時也套定理（那時積分要另外定義）。","順時針的曲線沒有變號。"],"checks":[{"ask":"∮_{|z|=3} dz/(z(z − 2)) 是？","options":[{"label":"0","correct":true},{"label":"−πi","why":"那只算了 z = 0 的留數 −1/2；z = 2 也在圓內，留數 1/2，兩者抵銷。"},{"label":"πi","why":"那只算了 z = 2；|0| < 3，z = 0 也在圓內。"}]},{"ask":"∮_{|z|=1} dz/(z(z − 2)) 是？","options":[{"label":"−πi","correct":true},{"label":"0","why":"z = 2 在單位圓外，不算；只剩 z = 0 的留數 1/(0 − 2) = −1/2。"},{"label":"−1/2","why":"那是留數；積分要再乘 2πi。"}]},{"ask":"留數定理的證明中，關鍵的一步是？","options":[{"label":"把 C 變形成繞各奇異點的小圓，每個小圓上只有 a₋₁ 項積分不為 0","correct":true},{"label":"用 Green 定理把線積分換成二重積分","why":"奇異點處 f 不全純，Green 定理加 CR 不能直接用在整個內部。"},{"label":"把 f 寫成多項式","why":"f 一般不是多項式；關鍵是每個奇異點附近的 Laurent 級數。"}]},{"ask":"∮_{|z|=1} sin z/z⁴ dz 是？","options":[{"label":"−πi/3","correct":true},{"label":"πi/3","why":"sin z 的 z³ 係數是 −1/6，留數 −1/6，乘 2πi 得 −πi/3。"},{"label":"0","why":"sin z/z⁴ 在 0 有 3 階極點，留數 −1/6 ≠ 0。"}]}],"practice":[{"id":"der-084","core":true},{"id":"rel-hard-cpx-001"}]},"residue-real-integrals":{"id":"residue-real-integrals","prerequisites":["residue-theorem","contour-integral","improper-infinite"],"next":[],"related":["beta-gamma-relation","feynman-trick-advanced"],"objectives":["∫_{−∞}^∞ p(x)/q(x) dx（q 無實根、次數比 p 至少高 2）：接上上半圓，用 ML 不等式證明半圓那段 → 0，答案是 2πi 乘上半平面的留數和。","∫₀^{2π} R(cos θ, sin θ) dθ：令 z = e^{iθ} 變成單位圓上的圍道積分。","∫ f(x) cos kx dx 型：改積 f(z)e^{ikz}，說得出 Jordan 引理的條件，以及 k > 0 時為什麼要往上半平面接。"],"concept":[{"heading":"① 想法：補一段曲線，讓它變成封閉的","body":["實數線上的積分不是封閉曲線，不能直接用留數定理。補一段：∫_{−R}^{R} + ∫_{C_R} = 2πi Σ（C_R 與線段圍住的極點的留數），C_R 是半徑 R 的上半圓。","如果能證明 ∫_{C_R} → 0（R → ∞），就得到 ∫_{−∞}^∞ f(x) dx = 2πi Σ_{上半平面} Res f。"]},{"heading":"② 有理函數：半圓為什麼趨近 0","body":["f = p/q，q 沒有實根，deg q ≥ deg p + 2。|z| = R 很大時 |f(z)| ≤ C/R²（分母至少比分子多兩次方）。半圓長度 πR，由 ML 不等式 |∫_{C_R} f dz| ≤ πR · C/R² = πC/R → 0。","條件「至少高 2」也保證 ∫_{−∞}^∞ f dx 本身收斂（〈瑕積分 I：無窮區間〉加上比較）；只高 1 次時這個論證不成立。"]},{"heading":"③ 三角函數的積分：z = e^{iθ}","body":["∫₀^{2π} R(cos θ, sin θ) dθ：θ 從 0 到 2π 時 z = e^{iθ} 走一圈單位圓。代換 cos θ = (z + 1/z)/2、sin θ = (z − 1/z)/(2i)、dθ = dz/(iz)，積分變成單位圓上有理函數的圍道積分，只算單位圓內部的留數。"]},{"heading":"④ 乘上 cos kx：改用 e^{ikz}","body":["∫ f(x) cos kx dx 不能直接用 cos kz，因為 cos(iy) = cosh y 在上半平面爆掉。改積 f(z)e^{ikz}，最後取實部（f 是實係數時）。k > 0 時 |e^{ikz}| = e^{−k Im z} ≤ 1 在上半平面成立，所以要往上接；k < 0 就往下接（並注意方向變號）。","Jordan 引理：若在上半圓 C_R 上 |f(z)| ≤ M_R 而且 M_R → 0，k > 0，則 |∫_{C_R} f(z)e^{ikz} dz| ≤ πM_R/k → 0。它只要求 f → 0，不要求比 1/R² 快，所以 x sin x/(1 + x²) 這類次數只差 1 的也能處理。"]},{"heading":"Jordan 引理的證明","body":["z = Re^{it}，|e^{ikz}| = e^{−kR sin t}，|dz| = R dt。積分 ≤ M_R R ∫₀^π e^{−kR sin t} dt = 2M_R R ∫₀^{π/2} e^{−kR sin t} dt。在 [0, π/2] 上 sin t ≥ 2t/π（凹函數在弦的上方），所以 ≤ 2M_R R ∫₀^{π/2} e^{−2kRt/π} dt < 2M_R R · π/(2kR) = πM_R/k。"],"collapsible":true}],"workedExamples":[{"title":"有理函數：1/(1 + x⁴)","prompt":"∫_{−∞}^∞ dx/(1 + x⁴)","problemId":"rel-hard-int-012","steps":["1 + z⁴ = 0 的根是 e^{iπ/4}, e^{3iπ/4}, e^{5iπ/4}, e^{7iπ/4}，上半平面是前兩個。分母比分子高 4 次，半圓 → 0。","用 g/h′：Res = 1/(4z₀³)。因為 z₀⁴ = −1，1/(4z₀³) = z₀/(4z₀⁴) = −z₀/4。","留數和 = −(e^{iπ/4} + e^{3iπ/4})/4 = −(i√2)/4（兩個實部 ±√2/2 抵銷，虛部各 √2/2）。","積分 = 2πi · (−i√2/4) = π√2/2 = π/√2 ≈ 2.221。從 0 積到 ∞ 是一半，π/(2√2)。"],"answer":"π/√2"},{"title":"三角積分","prompt":"∫₀^{2π} dθ/(2 + cos θ)","steps":["z = e^{iθ}：2 + (z + 1/z)/2 = (z² + 4z + 1)/(2z)，dθ = dz/(iz)。被積式變成 [2z/(z² + 4z + 1)] · dz/(iz) = 2 dz/(i(z² + 4z + 1))。","z² + 4z + 1 = 0 的根 −2 ± √3。|−2 + √3| ≈ 0.268 在單位圓內，−2 − √3 在外。","Res_{−2+√3} = 2/(i(2z + 4)) = 2/(i · 2√3) = 1/(i√3)。","積分 = 2πi · 1/(i√3) = 2π/√3 ≈ 3.628。"],"answer":"2π/√3"},{"title":"乘上 cos x","prompt":"∫_{−∞}^∞ cos x/(1 + x²) dx","problemId":"world-045","steps":["改積 e^{iz}/(1 + z²)，取實部。k = 1 > 0，往上半平面接。","上半圓上 |e^{iz}| ≤ 1，|1/(1 + z²)| ≤ 1/(R² − 1)，ML 給 ≤ πR/(R² − 1) → 0（這裡分母高 2 次，不用 Jordan 引理也行）。","上半平面只有 z = i：Res = e^{i·i}/(2i) = e^{−1}/(2i)。","∫_{−∞}^∞ e^{ix}/(1 + x²) dx = 2πi · e^{−1}/(2i) = π/e，已經是實數；實部就是答案 π/e ≈ 1.156（虛部 ∫ sin x/(1 + x²) dx = 0，奇函數）。"],"answer":"π/e"}],"pitfalls":["把下半平面的極點也算進去。","沒有檢查半圓那段 → 0 的條件（次數差至少 2，或 Jordan 引理的條件）。","直接對 cos z 做圍道積分；cos z 在上半平面無界，要改用 e^{iz}。","z = e^{iθ} 代換時漏了 dθ = dz/(iz)，或算了單位圓外的極點。"],"checks":[{"ask":"∫_{−∞}^∞ dx/(x² + 4) 是？","options":[{"label":"π/2","correct":true},{"label":"π/4","why":"Res_{2i} = 1/(4i)，2πi · 1/(4i) = π/2；π/4 是只從 0 積到 ∞ 的值。"},{"label":"π","why":"π 是 1/(x² + 1) 的答案；分母換成 x² + 4 會縮成一半。"}]},{"ask":"∫_{−∞}^∞ dx/(1 + x²)² 是？","options":[{"label":"π/2","correct":true},{"label":"π","why":"z = i 是 2 階極點，Res = d/dz (z + i)^{−2}|_{z=i} = −2/(2i)³ = −i/4，2πi · (−i/4) = π/2。"},{"label":"π/4","why":"π/4 是 ∫₀^∞ 的值；整條實數線是兩倍。"}]},{"ask":"為什麼 ∫ f(x) cos 3x dx（f 有理、在 ∞ 衰減）要改積 f(z)e^{3iz}，並往上半平面接？","options":[{"label":"上半平面 |e^{3iz}| = e^{−3 Im z} ≤ 1，半圓上的積分才會 → 0","correct":true},{"label":"因為 cos 3z 在上半平面有界","why":"cos(iy) = cosh y，在上半平面無界；所以不能直接用 cos 3z。"},{"label":"往哪邊接都可以","why":"往下半平面時 |e^{3iz}| = e^{−3 Im z} 會指數變大，半圓那段不會 → 0。"}]},{"ask":"用 z = e^{iθ} 算 ∫₀^{2π} R(cos θ, sin θ) dθ 時，dθ 要換成？","options":[{"label":"dz/(iz)","correct":true},{"label":"dz","why":"dz = i e^{iθ} dθ = iz dθ，所以 dθ = dz/(iz)。"},{"label":"iz dz","why":"方向反了：dz = iz dθ，要除以 iz。"}]}],"practice":[{"id":"lec-08-q2c","core":true},{"id":"uni-int-025","core":true},{"id":"uni-int-014","core":true},{"id":"rel-hard-int-012","core":true},{"id":"world-045","core":true},{"id":"depth-int-020"},{"id":"cx-hi-007"},{"id":"hc-rad-008"},{"id":"burst-boss-int-008"},{"id":"td-int-001"},{"id":"world-043","challenge":true,"note":"挑戰：含 ln x 的積分要用扇形或鑰匙孔形的圍道。"}]}});
